// 短文閱讀題庫（Part 6、7 風格，原創）：id, lv, p=6/7, k=類型, ti, tx, zh, w=用到的單字 id, qs=[{q, o, a, k=解題關鍵, n=各選項解析 [中文, 用法, 為什麼]}]
window.QUIZ_READ = [{"id":"r400-01","lv":400,"p":7,"k":"email","ti":"Your order is on the way","tx":"To: Kevin Wu\nFrom: Bright Home Store\nSubject: Your order is on the way\n\nDear Mr. Wu,\n\nThank you for shopping with us. We sent your desk lamp this morning. We will deliver it to your home on Thursday. The receipt is attached to this e-mail.\n\nIf the item is damaged, please contact us within seven days. We will replace it or give you a full refund.\n\nBright Home Store","zh":"收件人：Kevin Wu\n寄件人：Bright Home Store\n主旨：您的訂單已在配送途中\n\nWu 先生您好：\n\n感謝您的購買。我們今天早上已經寄出您的檯燈，會在星期四送到您家。收據已附在這封電子郵件裡。\n\n如果商品有損壞，請在七天內與我們聯絡。我們會為您更換，或是全額退款。\n\nBright Home Store","w":[179,15,219,34,242,230,212,119,2],"qs":[{"q":"What is the purpose of the e-mail?","o":["To say that an order has been sent","To advertise a new lamp","To cancel an order","To ask for a payment"],"a":0,"k":"主旨題：看開頭 We sent your desk lamp this morning","n":[["通知訂單已寄出","","文中 'We sent your desk lamp this morning'"],["宣傳新檯燈","","文中沒有推銷新檯燈，只談已買的那一盞"],["取消訂單","","文中沒有取消訂單，商品已寄出"],["要求付款","","文中沒有要求付款，只說收據附在信中"]]},{"q":"When will the lamp arrive at Mr. Wu's home?","o":["This morning","On Tuesday","On Thursday","In seven days"],"a":2,"k":"細節題：找 Thursday → We will deliver it ... on Thursday","n":[["今天早上","","'this morning' 是寄出的時間，不是送達"],["星期二","","文中沒提到 Tuesday"],["星期四","","文中 'deliver it to your home on Thursday'"],["七天後","","'seven days' 是損壞時聯絡商店的期限"]]},{"q":"What will the store do if the lamp is damaged?","o":["Repair it at Mr. Wu's home","Give a discount on the next order","Send another receipt","Send a new one or give the money back"],"a":3,"k":"細節題：找 damaged → replace it or give you a full refund","n":[["到府修理","","文中沒說要到府修理，是換貨或退款"],["下次訂單打折","","文中沒提到折扣，是 'full refund'"],["再寄一張收據","","收據已附在信中，損壞時不是補寄收據"],["寄新的或退錢","","文中 'replace it or give you a full refund'"]]}]},
{"id":"r400-02","lv":400,"p":7,"k":"notice","ti":"Third floor printer is not working","tx":"NOTICE: Third Floor Printer\n\nThe printer on the third floor is not working. A repair person will come on Wednesday morning. Until then, please use the printer on the second floor, next to the elevator.\n\nPlease do not try to repair the printer yourself. If you need to print many pages, contact Ms. Park in the IT department.\n\nThank you.","zh":"公告：三樓印表機\n\n三樓的印表機故障了。維修人員會在星期三早上過來。在那之前，請使用二樓電梯旁邊的印表機。\n\n請不要自己動手修理印表機。如果需要列印很多頁，請聯絡資訊部門的 Park 小姐。\n\n謝謝。","w":[16,232,230,35],"qs":[{"q":"What is the notice mainly about?","o":["A new elevator in the building","A meeting with Ms. Park","A change in office hours","A printer that is broken"],"a":3,"k":"主旨題：開頭 The printer ... is not working","n":[["大樓新電梯","","電梯只用來說明二樓印表機位置"],["與 Ms. Park 開會","","文中沒有開會，Ms. Park 只是聯絡人"],["上班時間改變","","文中沒提到上班時間"],["壞掉的印表機","","文中 'The printer on the third floor is not working'"]]},{"q":"Where is the printer that people should use now?","o":["On the third floor","On the second floor","In the IT department","In Ms. Park's office"],"a":1,"k":"細節題：找 please use the printer on the second floor","n":[["三樓","","三樓的印表機壞了，不能用"],["二樓","","文中 'use the printer on the second floor'"],["資訊部門","","IT department 是印大量文件時的聯絡單位"],["Ms. Park 的辦公室","","文中沒說印表機在她辦公室"]]},{"q":"The word \"repair\" in the notice is closest in meaning to","o":["clean","fix","buy","move"],"a":1,"k":"字義題：do not try to repair it yourself → 不要自己修","n":[["(v.) 清潔","","語意不合：公告談的是故障，不是清潔"],["(v.) 修理","","repair = fix，指修好壞掉的機器"],["(v.) 購買","","語意不合：公告沒有要大家買印表機"],["(v.) 搬移","","語意不合：公告沒說要搬印表機"]]}]},
{"id":"r400-03","lv":400,"p":7,"k":"advertisement","ti":"Annual Summer Sale at Sunny Shoes","tx":"Sunny Shoes — Annual Summer Sale!\n\nFrom July 1 to July 7, all shoes are 30% off. We have a wide selection of popular brands for men, women, and children. Bags are also on sale at a 10% discount.\n\nQuantities are limited, so come early! The store is open from 10 A.M. to 9 P.M. every day. Sorry, we cannot give refunds on sale items.","zh":"Sunny Shoes——年度夏季特賣！\n\n7 月 1 日到 7 月 7 日，全部鞋款打七折。我們有多種熱門品牌可以挑選，男鞋、女鞋、童鞋都有。包包也有九折優惠。\n\n數量有限，請早點來！本店每天從上午 10 點營業到晚上 9 點。很抱歉，特賣商品無法退款。","w":[146,57,25,111,144,119,34],"qs":[{"q":"What is being advertised?","o":["A shoe repair service","A job at a shoe store","The opening of a new store","A sale at a shoe store"],"a":3,"k":"主旨題：開頭 Annual Summer Sale、all shoes are 30% off","n":[["鞋子修理服務","","文中是特價活動，不是修鞋服務"],["鞋店的工作","","文中沒有徵人資訊"],["新店開幕","","文中沒提到開幕，是 'Summer Sale'"],["鞋店的特賣","","文中 'all shoes are 30% off'"]]},{"q":"How much is the discount on bags?","o":["30%","10%","50%","7%"],"a":1,"k":"細節題：找 Bags ... 10% discount","n":[["百分之三十","","30% 是鞋子的折扣，不是包包"],["百分之十","","文中 'Bags are also on sale at a 10% discount'"],["百分之五十","","文中沒有 50%"],["百分之七","","7 是活動到 July 7，不是折扣"]]},{"q":"Why are customers told to come early?","o":["The store closes at noon","Early shoppers get a free bag","The number of sale items is limited","The sale is only for one day"],"a":2,"k":"細節題：找 come early 前面的原因 Quantities are limited","n":[["店家中午關門","","文中營業到 9 P.M.，不是中午"],["早到送免費包包","","文中沒提到贈品"],["特價品數量有限","","文中 'Quantities are limited, so come early'"],["活動只有一天","","文中是 July 1 to July 7，共七天"]]}]},
{"id":"r400-04","lv":400,"p":7,"k":"message","ti":"My flight is late","tx":"Dana Kim (9:12 A.M.): Hi, Tom. My flight is late because of bad weather. I will reach the office at about 2 P.M.\n\nTom Reyes (9:15 A.M.): OK. The client meeting is at 1 P.M. Should I cancel it?\n\nDana Kim (9:17 A.M.): No, please don't. Can you move it to 3 P.M.? Our client, Ms. Ito, said she is available all afternoon.\n\nTom Reyes (9:18 A.M.): Sure. I will call her now.","zh":"Dana Kim（上午 9:12）：嗨，Tom。因為天氣不好，我的班機延誤了。我大約下午 2 點才會到辦公室。\n\nTom Reyes（上午 9:15）：好的。和客戶的會議是下午 1 點。要我取消嗎？\n\nDana Kim（上午 9:17）：不，請不要取消。可以幫我改到下午 3 點嗎？我們的客戶 Ito 小姐說她整個下午都有空。\n\nTom Reyes（上午 9:18）：沒問題。我現在就打電話給她。","w":[24,216,38,176,139],"qs":[{"q":"Why did Ms. Kim write to Mr. Reyes?","o":["To ask about the weather","To say that she will arrive late","To book a flight","To invite him to lunch"],"a":1,"k":"細節題：第一句 My flight is late ... about 2 P.M.","n":[["詢問天氣","","天氣只是班機延誤的原因，不是目的"],["說她會晚到","","文中 'My flight is late'，約 2 P.M. 到公司"],["訂機票","","文中沒有訂機票，Dana 只是說班機延誤"],["邀請吃午餐","","文中沒提到午餐"]]},{"q":"What time will the client meeting most likely start?","o":["2 P.M.","9 A.M.","1 P.M.","3 P.M."],"a":3,"k":"推論題：Can you move it to 3 P.M.? → Tom: Sure","n":[["下午兩點","","2 P.M. 是 Dana 到公司的時間，不是會議"],["上午九點","","9 A.M. 是訊息時間，不是會議"],["下午一點","","1 P.M. 是原訂時間，Dana 要改期"],["下午三點","","Dana 'move it to 3 P.M.'，Tom 回 'Sure'"]]},{"q":"What will Mr. Reyes probably do next?","o":["Go to the airport","Call Ms. Ito","Book a new flight","Cancel the meeting"],"a":1,"k":"推論題：最後一句 I will call her now","n":[["去機場","","文中沒說他要去機場，只說 Dana 的班機延誤"],["打給 Ms. Ito","","文中 'I will call her now'，her 指 Ms. Ito"],["訂新班機","","文中沒提到訂班機"],["取消會議","","Dana 說 'No, please don't'，是改時間"]]}]},
{"id":"r400-05","lv":400,"p":7,"k":"form","ti":"Order confirmation: Maple Office Supplies","tx":"Maple Office Supplies\nOrder Confirmation\n\nOrder number: 4521\nCustomer: Ms. Lisa Chang\nOrder date: May 3\n\nItems:\nPrinter paper, 5 boxes: $40\nBlue pens, 20: $10\nDelivery fee: $5\nTotal amount: $55\n\nPayment: Paid by credit card\nDelivery date: May 6\n\nQuestions? Contact us at 555-0142. Please keep this page as your receipt.","zh":"Maple Office Supplies\n訂單確認單\n\n訂單編號：4521\n顧客：Lisa Chang 小姐\n訂購日期：5 月 3 日\n\n品項：\n印表機用紙，5 箱：40 美元\n藍色原子筆，20 支：10 美元\n運費：5 美元\n總金額：55 美元\n\n付款：已用信用卡付款\n送貨日期：5 月 6 日\n\n有問題嗎？請撥 555-0142 與我們聯絡。請保留此頁作為收據。","w":[34,16,7,5,29,230,15],"qs":[{"q":"What did Ms. Chang order?","o":["A printer and pens","Pens and notebooks","Boxes and a desk","Paper and pens"],"a":3,"k":"細節題：看 Items 清單 Printer paper、Blue pens","n":[["印表機和筆","","清單是 'Printer paper'（紙），不是印表機"],["筆和筆記本","","清單沒有筆記本"],["箱子和書桌","","清單沒有書桌，boxes 是紙的包裝單位"],["紙和筆","","清單 'Printer paper' 和 'Blue pens'"]]},{"q":"How much is the delivery fee?","o":["$55","$40","$5","$10"],"a":2,"k":"細節題：找 Delivery fee","n":[["55 美元","","$55 是 Total amount 總金額"],["40 美元","","$40 是紙的價格"],["5 美元","","文中 'Delivery fee: $5'"],["10 美元","","$10 是藍筆的價格"]]},{"q":"What is NOT shown on the form?","o":["The order number","The delivery date","The total amount","The customer's address"],"a":3,"k":"NOT 題：其他三項都有出現，找沒出現的","n":[["訂單編號","","有：'Order number: 4521'"],["送達日期","","有：'Delivery date: May 6'"],["總金額","","有：'Total amount: $55'"],["客戶地址","","表單沒列地址，這是唯一沒出現的"]]}]},
{"id":"r400-06","lv":400,"p":7,"k":"review","ti":"A good stay at Lakeside Hotel","tx":"Lakeside Hotel — Review by Mark T.\nRating: 4 out of 5\n\nI stayed at the Lakeside Hotel for three nights on a business trip. My room was clean and quiet, and the staff was very friendly. The receptionist helped me book a taxi to the airport. The hotel is also near the train station.\n\nMy only complaint is the breakfast. There was not much variety. Still, I recommend this hotel.","zh":"Lakeside Hotel——Mark T. 的評論\n評分：4 分（滿分 5 分）\n\n我因為出差，在 Lakeside Hotel 住了三個晚上。房間乾淨又安靜，員工也非常親切。接待人員幫我預訂了去機場的計程車。飯店離火車站也很近。\n\n我唯一的抱怨是早餐，菜色變化不多。不過，我還是推薦這家飯店。","w":[40,32,185,95,82,208],"qs":[{"q":"What is the review about?","o":["A taxi company","A stay at a hotel","A train trip","A meal at a restaurant"],"a":1,"k":"主旨題：開頭 I stayed at the Lakeside Hotel for three nights","n":[["計程車公司","","計程車只是接待員幫忙訂的"],["住飯店的經驗","","文中 'I stayed at the Lakeside Hotel'"],["火車旅行","","火車站只是說明飯店位置"],["餐廳用餐","","早餐只是其中一點抱怨"]]},{"q":"What did the receptionist do for the writer?","o":["Booked a taxi","Made breakfast","Cleaned the room","Carried the bags"],"a":0,"k":"細節題：找 The receptionist helped me book a taxi","n":[["訂計程車","","文中 'helped me book a taxi to the airport'"],["做早餐","","文中沒說接待員做早餐"],["打掃房間","","文中沒說接待員打掃，只說房間乾淨"],["搬行李","","文中沒提到搬行李"]]},{"q":"What did the writer NOT like about the hotel?","o":["The staff","The breakfast","The room","The location"],"a":1,"k":"細節題：問不喜歡什麼 → 找 My only complaint is the breakfast","n":[["員工","","文中 'the staff was very friendly'，他喜歡"],["早餐","","文中 'My only complaint is the breakfast'"],["房間","","文中 'My room was clean and quiet'，他喜歡"],["地點","","文中 'near the train station'，是優點"]]}]},
{"id":"r400-07","lv":400,"p":7,"k":"announcement","ti":"Flight 208: new time and gate","tx":"Attention, passengers on Flight 208 to Tokyo.\n\nBecause of heavy rain, the departure time has changed. The flight will now leave at 4:30 P.M., not 3:00 P.M. The gate has also changed from Gate 12 to Gate 5 in the same terminal.\n\nPassengers can get a free beverage at the café near Gate 5. Please show your ticket to the cashier. We apologize for the delay.","zh":"搭乘 208 號班機前往東京的旅客請注意。\n\n由於大雨，起飛時間已經更改。班機將改在下午 4:30 起飛，而不是下午 3:00。登機門也從 12 號改為同一航廈的 5 號登機門。\n\n旅客可以在 5 號登機門附近的咖啡店免費領取一杯飲料。請向收銀員出示您的機票。造成延誤，我們深感抱歉。","w":[1,24,67,99,86,4,180],"qs":[{"q":"What is the announcement mainly about?","o":["A lost ticket","A new café at the airport","A change to a flight","A cheaper flight to Tokyo"],"a":2,"k":"主旨題：開頭 the departure time has changed","n":[["遺失機票","","文中沒提到遺失機票"],["機場新咖啡廳","","咖啡廳只是補充免費飲料的地點"],["航班的變動","","文中 'departure time has changed'、gate 也改了"],["較便宜的班機","","文中沒提到票價"]]},{"q":"Which gate should passengers go to now?","o":["Gate 5","Gate 12","Gate 3","Gate 4"],"a":0,"k":"細節題：找 changed from Gate 12 to Gate 5","n":[["5 號登機門","","文中 'from Gate 12 to Gate 5'"],["12 號登機門","","Gate 12 是舊登機門"],["3 號登機門","","文中沒有 Gate 3，3:00 P.M. 是舊時間"],["4 號登機門","","文中沒有 Gate 4，4:30 是新起飛時間"]]},{"q":"What can passengers get for free?","o":["A drink","A taxi ride","A new ticket","A meal"],"a":0,"k":"細節題：找 free beverage → beverage = drink","n":[["飲料","","文中 'a free beverage'，beverage 就是飲料"],["計程車","","文中沒提到免費計程車"],["新機票","","文中沒提到換新機票，只要出示現有機票"],["餐點","","文中只說 beverage，不是 meal"]]}]},
{"id":"r400-08","lv":400,"p":7,"k":"memo","ti":"Sales meeting moves to Tuesday","tx":"MEMO\nTo: All sales staff\nFrom: Helen Brooks, Sales Manager\nDate: March 4\n\nNext week, our regular Monday sales meeting will move to Tuesday because Monday is a holiday. The meeting will start at 10 A.M. in Meeting Room B.\n\nAll staff must attend. Please bring your sales figures for February. We will also talk about our targets for April. If you cannot come, tell me by Friday.","zh":"備忘錄\n收件人：全體業務人員\n寄件人：業務經理 Helen Brooks\n日期：3 月 4 日\n\n下星期，我們固定在星期一舉行的業務會議將改到星期二，因為星期一是假日。會議將於上午 10 點在 B 會議室開始。\n\n全體人員都必須出席。請帶二月份的銷售數字。我們也會討論四月份的目標。如果無法出席，請在星期五之前告訴我。","w":[40,137,175,69,112],"qs":[{"q":"What is the purpose of the memo?","o":["To ask about holiday plans","To welcome new staff","To report February sales","To announce a change of meeting day"],"a":3,"k":"主旨題：開頭 meeting will move to Tuesday","n":[["詢問假期計畫","","Monday is a holiday 只是改期的原因"],["歡迎新員工","","文中沒提到新員工"],["回報二月業績","","二月業績是要大家帶來的資料，不是目的"],["宣布改開會日","","文中 'will move to Tuesday'"]]},{"q":"When is next week's sales meeting?","o":["Tuesday at 10 A.M.","Monday at 10 A.M.","Tuesday at 2 P.M.","Friday at 10 A.M."],"a":0,"k":"細節題：找 move to Tuesday、start at 10 A.M.","n":[["週二上午十點","","文中 'move to Tuesday' 和 'start at 10 A.M.'"],["週一上午十點","","週一是舊日期，因假日改到週二"],["週二下午兩點","","時間是 10 A.M.，不是 2 P.M."],["週五上午十點","","Friday 是回覆能否出席的期限"]]},{"q":"The word \"figures\" in the memo is closest in meaning to","o":["pictures","people","numbers","shapes"],"a":2,"k":"字義題：sales figures for February → 銷售的數字","n":[["(n.) 圖片","","語意不合：要帶的是銷售資料"],["(n.) 人","","語意不合：figures 在此不是人"],["(n.) 數字","","figures 在此指數據，sales figures 即銷售數字"],["(n.) 形狀","","語意不合：與銷售資料無關"]]}]},
{"id":"r400-09","lv":400,"p":7,"k":"article","ti":"New bakery opens on Lake Street","tx":"New Bakery Opens Downtown\n\nSweet Morning Bakery opened last Saturday on Lake Street. The owner, Ms. Rosa Diaz, has ten years of experience as a hotel baker. Now she has her own shop.\n\nThe bakery sells bread, cakes, and various beverages. Ms. Diaz buys her fruit and milk from local farms. \"I want to support local farmers,\" she said. The shop is open every day except Monday.","zh":"市中心新麵包店開幕\n\nSweet Morning Bakery 上星期六在 Lake Street 開幕。老闆 Rosa Diaz 小姐有十年在飯店當麵包師傅的經驗，現在她有了自己的店。\n\n這家麵包店販售麵包、蛋糕和各種飲料。Diaz 小姐的水果和牛奶都是向當地農場買的。她說：「我想支持當地的農民。」這家店除了星期一以外，每天都營業。","w":[106,148,86,164,235],"qs":[{"q":"What is the article about?","o":["A new shop in town","A hotel restaurant","A baking class","A farm that sells fruit"],"a":0,"k":"主旨題：開頭 Sweet Morning Bakery opened last Saturday","n":[["鎮上的新店","","文中 'Bakery opened last Saturday on Lake Street'"],["飯店餐廳","","飯店只是 Ms. Diaz 以前的工作"],["烘焙課","","文中沒提到上課"],["賣水果的農場","","農場只是供應水果和牛奶的來源"]]},{"q":"When is the bakery closed?","o":["On Sundays","On holidays","On Mondays","On Saturdays"],"a":2,"k":"細節題：找 open every day except Monday","n":[["星期日","","文中 every day except Monday，週日有開"],["假日","","文中沒提到假日休息"],["星期一","","文中 'every day except Monday'"],["星期六","","Saturday 是開幕的日子，不是休息日"]]},{"q":"What is suggested about Ms. Diaz?","o":["She is new to baking","She grows her own fruit","She wants to help farmers in her area","She plans to open a hotel"],"a":2,"k":"推論題：'I want to support local farmers' → 想幫在地農民","n":[["她剛接觸烘焙","","文中她有十年飯店烘焙經驗"],["她自己種水果","","文中是向在地農場買 fruit and milk"],["她想幫在地農民","","文中 'I want to support local farmers'"],["她打算開飯店","","她以前在飯店工作，沒說要開飯店"]]}]},
{"id":"r400-10","lv":400,"p":7,"k":"letter","ti":"Your new savings account","tx":"Stone Bridge Bank\n\nDear Mr. Allen,\n\nThank you for opening a savings account at Stone Bridge Bank. Your bank card will arrive by mail within five days.\n\nBefore you use the card, please call 555-0177 to create a personal password. To keep your account secure, do not tell anyone your password.\n\nIf you have any questions, please visit your local Stone Bridge Bank or contact us by phone.\n\nSincerely,\nNina Ford\nCustomer Service","zh":"Stone Bridge Bank\n\nAllen 先生您好：\n\n感謝您在 Stone Bridge Bank 開立儲蓄帳戶。您的金融卡將在五天內郵寄送達。\n\n使用卡片之前，請先撥打 555-0177 設定個人密碼。為了保護帳戶安全，請不要把密碼告訴任何人。\n\n如果有任何問題，請到您當地的 Stone Bridge Bank，或是打電話與我們聯絡。\n\n敬上\nNina Ford\n客戶服務部","w":[30,183,135,168,164,230],"qs":[{"q":"Why did the bank write to Mr. Allen?","o":["To say that his card was lost","To offer him a loan","To give information about his new account","To ask him to pay a fee"],"a":2,"k":"主旨題：Thank you for opening a savings account","n":[["說他的卡遺失","","文中沒有卡遺失，卡還沒寄到"],["提供貸款","","文中沒提到貸款"],["提供新帳戶資訊","","文中 'opening a savings account'，說明卡與密碼"],["要他付費用","","文中沒有要求付費"]]},{"q":"How will Mr. Allen get his bank card?","o":["By e-mail","By mail","From a bank machine","From Ms. Ford in person"],"a":1,"k":"細節題：找 bank card will arrive by mail","n":[["用電子郵件","","文中是 by mail，不是 e-mail"],["郵寄","","文中 'will arrive by mail within five days'"],["從提款機","","文中沒提到提款機"],["Ms. Ford 當面給","","文中沒有當面交給，卡是郵寄的"]]},{"q":"The word \"secure\" in the letter is closest in meaning to","o":["busy","new","open","safe"],"a":3,"k":"字義題：keep your account secure → 保護帳戶安全","n":[["(adj.) 忙碌的","","語意不合：帳戶不是忙碌"],["(adj.) 新的","","語意不合：secure 不是新舊"],["(adj.) 開放的","","語意相反：不讓別人知道密碼才安全"],["(adj.) 安全的","","secure = safe，指帳戶受到保護"]]}]},
{"id":"r400-11","lv":400,"p":7,"k":"advertisement","ti":"Now hiring: receptionist","tx":"Now Hiring: Receptionist\n\nPine Street Clinic is seeking a full-time receptionist. The job starts on June 1.\n\nTasks: answer the phone, welcome visitors, and arrange appointments.\nYou need: one year of office experience and basic computer skills.\nHours: Monday to Friday, 9 A.M. to 6 P.M.\n\nTo apply, send your résumé to Ms. Gomez by May 15. We will contact you for an interview.","zh":"徵才：接待人員\n\nPine Street Clinic 誠徵全職接待人員。工作從 6 月 1 日開始。\n\n工作內容：接聽電話、接待訪客、安排預約。\n條件：一年辦公室工作經驗及基本電腦能力。\n上班時間：星期一到星期五，上午 9 點到下午 6 點。\n\n想應徵的人，請在 5 月 15 日前把履歷寄給 Gomez 小姐。我們會與您聯絡安排面試。","w":[202,32,6,221,11,205,8,106,197,230,231],"qs":[{"q":"What job is being advertised?","o":["A nurse","A cleaner","A computer teacher","A receptionist"],"a":3,"k":"細節題：標題 Now Hiring: Receptionist","n":[["護理師","","診所徵的不是護理師，是 receptionist"],["清潔人員","","文中沒有徵清潔人員"],["電腦老師","","只要求 basic computer skills，不是教電腦"],["櫃台接待員","","文中 'seeking a full-time receptionist'"]]},{"q":"What is NOT a task of the job?","o":["Welcoming visitors","Answering the phone","Arranging appointments","Cleaning the office"],"a":3,"k":"NOT 題：Tasks 只列三項，找沒列的","n":[["歡迎訪客","","有：'welcome visitors'"],["接電話","","有：'answer the phone'"],["安排預約","","有：'arrange appointments'"],["打掃辦公室","","Tasks 沒有打掃，這是唯一沒出現的"]]},{"q":"What must people who want the job do by May 15?","o":["Call the clinic","Start the job","Come for an interview","Send a résumé"],"a":3,"k":"細節題：找 by May 15 → send your résumé","n":[["打電話給診所","","文中沒要求打電話，要寄履歷"],["開始上班","","上班是 June 1，不是 May 15"],["來面試","","面試是之後 'We will contact you'"],["寄履歷","","文中 'send your résumé to Ms. Gomez by May 15'"]]}]},
{"id":"r400-12","lv":400,"p":7,"k":"notice","ti":"East elevator closed on Friday","tx":"Oak Tower Apartments — Notice\n\nThe east elevator will be closed on Friday, April 12, from 9 A.M. to 3 P.M. Workers will replace some old parts.\n\nDuring this period, please use the west elevator or the stairs. If you need help with heavy items, contact the front desk in the lobby. We apologize for the trouble.\n\nBuilding Management","zh":"Oak Tower Apartments——公告\n\n東側電梯將於 4 月 12 日星期五上午 9 點到下午 3 點暫停使用。工人要更換一些老舊的零件。\n\n在這段期間，請使用西側電梯或樓梯。如果您需要有人幫忙搬重物，請聯絡大廳的櫃台。造成不便，我們深感抱歉。\n\n大樓管理處","w":[212,43,34,230,13,180],"qs":[{"q":"What is the purpose of the notice?","o":["To say that an elevator will be closed","To announce new stairs","To welcome new neighbors","To ask people to move out"],"a":0,"k":"主旨題：開頭 The east elevator will be closed","n":[["電梯將關閉","","文中 'The east elevator will be closed'"],["宣布新樓梯","","stairs 只是替代方式，不是新設施"],["歡迎新鄰居","","文中沒提到新鄰居"],["要求住戶搬走","","文中沒要求搬家，只是電梯維修"]]},{"q":"How long will the east elevator be closed?","o":["Two days","Three hours","Six hours","Nine hours"],"a":2,"k":"細節題：from 9 A.M. to 3 P.M. → 算時間","n":[["兩天","","只關 Friday, April 12 一天"],["三小時","","9 A.M. 到 3 P.M. 不是三小時"],["六小時","","'from 9 A.M. to 3 P.M.' 共六小時"],["九小時","","9 是開始的時間，不是時數"]]},{"q":"The word \"period\" in the notice is closest in meaning to","o":["place","rule","time","price"],"a":2,"k":"字義題：During this period → 這段時間","n":[["(n.) 地點","","語意不合：9 A.M. 到 3 P.M. 是時間"],["(n.) 規定","","語意不合：period 不是規定"],["(n.) 時間","","period 在此指一段時間"],["(n.) 價格","","語意不合：與價格無關"]]}]},
{"id":"r400-13","lv":400,"p":7,"k":"email","ti":"Your reservation at Garden View Hotel","tx":"To: Jason Lee\nFrom: Garden View Hotel\nSubject: Your reservation\n\nDear Mr. Lee,\n\nThis e-mail is to confirm your reservation. You booked a single room for two nights, from October 8 to October 10. The price is $90 per night, and breakfast is included.\n\nYou can check in after 3 P.M. If you need to cancel, please tell us at least 24 hours in advance.\n\nWe look forward to your visit.","zh":"收件人：Jason Lee\n寄件人：Garden View Hotel\n主旨：您的訂房\n\nLee 先生您好：\n\n這封電子郵件是要確認您的訂房。您預訂了一間單人房，共兩晚，從 10 月 8 日到 10 月 10 日。房價是每晚 90 美元，含早餐。\n\n您可以在下午 3 點以後辦理入住。如果需要取消，請至少提前 24 小時告訴我們。\n\n期待您的光臨。","w":[196,9,185,176,246,2],"qs":[{"q":"What is the purpose of the e-mail?","o":["To advertise a new hotel","To ask for a payment","To confirm a hotel booking","To cancel a reservation"],"a":2,"k":"主旨題：開頭 to confirm your reservation","n":[["宣傳新飯店","","文中是確認訂房，不是廣告"],["要求付款","","文中只列價格，沒有要求付款"],["確認飯店訂房","","文中 'to confirm your reservation'"],["取消訂房","","取消只是說明規定，不是目的"]]},{"q":"How many nights will Mr. Lee stay?","o":["One","Two","Three","Eight"],"a":1,"k":"細節題：from October 8 to October 10 + two nights","n":[["一晚","","文中 'for two nights'"],["兩晚","","文中 'for two nights, from October 8 to October 10'"],["三晚","","10 月 8 日到 10 日是兩晚，不是三晚"],["八晚","","8 是入住日期，不是晚數"]]},{"q":"What should Mr. Lee do if he needs to cancel?","o":["Send a letter","Call after 3 P.M.","Pay $90","Tell the hotel at least one day before"],"a":3,"k":"細節題：找 cancel → at least 24 hours in advance","n":[["寄信","","文中沒要求寄信，只說 tell us"],["三點後打電話","","3 P.M. 是入住時間，與取消無關"],["付 90 美元","","$90 是一晚房價，不是取消要做的事"],["至少提前一天告知","","'at least 24 hours in advance' = 至少一天前"]]}]},
{"id":"r400-14","lv":400,"p":7,"k":"message","ti":"Wrong ink from the supplier","tx":"Amy (10:02): Hi, Ben. We have a problem. The supplier sent the wrong ink for our printer.\n\nBen (10:05): Oh no. Did you contact them?\n\nAmy (10:06): Yes. They apologized and will deliver the right ink tomorrow morning.\n\nBen (10:08): But I need to print my sales report today.\n\nAmy (10:09): You can use the printer in the marketing department. I already got permission.\n\nBen (10:10): Great. Thanks!","zh":"Amy（10:02）：嗨，Ben。我們有個問題。供應商寄錯了我們印表機要用的墨水。\n\nBen（10:05）：糟糕。妳聯絡他們了嗎？\n\nAmy（10:06）：聯絡了。他們道了歉，明天早上會把正確的墨水送來。\n\nBen（10:08）：可是我今天就要列印我的業務報告。\n\nAmy（10:09）：你可以用行銷部門的印表機。我已經得到許可了。\n\nBen（10:10）：太好了，謝謝！","w":[97,16,230,180,179,35,41],"qs":[{"q":"What problem does Amy mention?","o":["A report is missing","The printer is broken","The supplier is closed","The wrong ink was sent"],"a":3,"k":"細節題：第一句 sent the wrong ink","n":[["報告不見了","","文中 Ben 要印報告，沒說不見"],["印表機壞了","","印表機沒壞，是墨水送錯"],["供應商休息","","文中供應商有回應並道歉"],["寄錯墨水","","文中 'sent the wrong ink'"]]},{"q":"When will the right ink arrive?","o":["This afternoon","Tomorrow morning","Next week","Tomorrow night"],"a":1,"k":"細節題：找 deliver the right ink tomorrow morning","n":[["今天下午","","文中是明天，不是今天下午"],["明天早上","","文中 'deliver the right ink tomorrow morning'"],["下週","","文中沒說下週"],["明天晚上","","文中是 morning，不是 night"]]},{"q":"What will Ben most likely do today?","o":["Wait for the delivery","Print his report in another department","Buy ink at a store","Call the supplier"],"a":1,"k":"推論題：Ben 要印報告 → 用 marketing department 的印表機","n":[["等送貨","","Ben 今天就要印，不能等明天"],["到別的部門印報告","","文中 'use the printer in the marketing department'"],["去店裡買墨水","","文中沒提到去店裡買"],["打給供應商","","Amy 已經聯絡過供應商"]]}]},
{"id":"r400-15","lv":400,"p":7,"k":"form","ti":"City Museum: Saturday schedule","tx":"City Museum — Saturday Schedule\n\n10:00 A.M. Museum opens\n10:30 A.M. Guided tour (meet in the lobby)\n12:00 P.M. Lunch break — café on the second floor\n2:00 P.M. Talk by the author Paul Grant, Room 3\n4:00 P.M. Children's art class\n5:30 P.M. Museum closes\n\nAdmission: $8 for adults, free for children under 12.\nThe guided tour is free, but please reserve a place online.","zh":"City Museum——星期六行程表\n\n上午 10:00 博物館開館\n上午 10:30 導覽（在大廳集合）\n中午 12:00 午休——二樓咖啡廳\n下午 2:00 作家 Paul Grant 演講，3 號室\n下午 4:00 兒童美術課\n下午 5:30 博物館閉館\n\n門票：成人 8 美元，12 歲以下兒童免費。\n導覽免費，但請先在網路上預約名額。","w":[108,13,20,84,234],"qs":[{"q":"How much is admission for an adult?","o":["$8","$12","$3","It is free"],"a":0,"k":"細節題：找 Admission: $8 for adults","n":[["8 美元","","文中 'Admission: $8 for adults'"],["12 美元","","12 是 under 12 的年齡，不是票價"],["3 美元","","文中沒有 $3，Room 3 是演講地點"],["免費","","免費的是 12 歲以下兒童和導覽"]]},{"q":"Who is Paul Grant?","o":["An art teacher","A museum cashier","A writer","A tour guide"],"a":2,"k":"推論題：Talk by the author Paul Grant","n":[["美術老師","","美術課是另一場，沒說他教課"],["博物館收銀員","","文中沒說他是收銀員"],["作家","","'Talk by the author Paul Grant'，author 即作家"],["導覽員","","導覽是另一場，沒說是他"]]},{"q":"What must visitors do to join the guided tour?","o":["Come after lunch","Go to Room 3","Reserve a place online","Buy a tour ticket"],"a":2,"k":"細節題：找 please reserve a place online","n":[["午餐後再來","","導覽是 10:30，在午餐前"],["去 3 號房","","Room 3 是演講地點，不是導覽"],["線上預約名額","","文中 'please reserve a place online'"],["買導覽票","","文中 'The guided tour is free'，不用買票"]]}]},
{"id":"r400-16","lv":400,"p":7,"k":"review","ti":"Blue Wave speaker: small and clear","tx":"Blue Wave Speaker — Review by Sara P.\nRating: 5 out of 5\n\nI bought this speaker last month for $35. It is small and portable, so I carry it in my bag every day. The sound is clear, even at high volume. The battery lasts about ten hours.\n\nMy only complaint is the manual. It is not detailed, so I watched a video to learn how to use the speaker. For this price, it is a real bargain.","zh":"Blue Wave 喇叭——Sara P. 的評論\n評分：5 分（滿分 5 分）\n\n我上個月用 35 美元買了這個喇叭。它體積小、方便攜帶，所以我每天都放在包包裡帶著走。即使音量開得很大，聲音還是很清楚。電池大約可以用十個小時。\n\n唯一的缺點是使用手冊。內容不夠詳細，所以我看了影片才學會怎麼使用這個喇叭。以這個價格來說，真的非常划算。","w":[154,33,95,104,161,129],"qs":[{"q":"What is the review about?","o":["A mobile phone","A music video","A small speaker","A travel bag"],"a":2,"k":"主旨題：開頭 Blue Wave Speaker，It is small and portable","n":[["手機","","文中沒提到手機"],["音樂影片","","影片是用來學習使用方法，不是主題"],["小型喇叭","","文中評論 'Blue Wave Speaker'，'small and portable'"],["旅行袋","","bag 只是用來放喇叭"]]},{"q":"What does the writer say about the manual?","o":["It is easy to understand","It was not in the box","It does not give enough information","It is too long"],"a":2,"k":"細節題：找 My only complaint is the manual","n":[["很好懂","","文中 'It is not detailed'，不好懂"],["盒子裡沒有","","文中沒說沒附說明書"],["資訊不夠詳細","","文中 'It is not detailed'，所以要看影片"],["太長","","文中是不夠詳細，不是太長"]]},{"q":"The word \"portable\" in the review is closest in meaning to","o":["hard to find","nice to look at","easy to break","easy to carry"],"a":3,"k":"字義題：small and portable, carry it in my bag","n":[["難找到","","語意不合：他每天帶著走"],["外觀好看","","文中沒談外觀"],["容易壞","","文中沒說容易壞"],["容易攜帶","","'carry it in my bag every day'，portable = 好帶"]]}]},
{"id":"r400-17","lv":400,"p":7,"k":"announcement","ti":"Sunrise Foods anniversary party","tx":"Sunrise Foods: Anniversary Party\n\nDear colleagues,\n\nNext month, Sunrise Foods will be 20 years old! To celebrate our anniversary, we will have a party on Friday, September 18, at 6 P.M. The venue is the Rose Garden Restaurant, next to our office.\n\nAll employees are invited. Dinner and beverages are free. Please respond to Ms. Ortiz in the HR department by September 10 so that we can reserve enough tables.","zh":"Sunrise Foods：周年慶祝派對\n\n各位同事：\n\n下個月，Sunrise Foods 就要滿 20 歲了！為了慶祝周年，我們將在 9 月 18 日星期五下午 6 點舉辦派對。場地是辦公室隔壁的 Rose Garden Restaurant。\n\n我們邀請所有員工參加。晚餐和飲料都免費。請在 9 月 10 日前回覆人資部門的 Ortiz 小姐，這樣我們才能預訂足夠的桌子。","w":[87,90,96,10,173,86,186,35,234],"qs":[{"q":"Why will the company have a party?","o":["A new manager is coming","Sales were good this year","A new restaurant is opening","It will be 20 years old"],"a":3,"k":"細節題：找 will be 20 years old! To celebrate","n":[["新經理要來","","文中沒提到新經理"],["今年業績好","","文中沒提到業績"],["新餐廳開幕","","餐廳只是辦派對的地點"],["公司滿二十年","","文中 'will be 20 years old' 'To celebrate'"]]},{"q":"What is indicated about the party?","o":["Only managers can go","Employees do not need to pay for food","It will be held in the morning","It is far from the office"],"a":1,"k":"推論題：Dinner and beverages are free","n":[["只有主管能去","","文中 'All employees are invited'"],["員工不用付餐費","","文中 'Dinner and beverages are free'"],["在早上舉行","","文中是 6 P.M.，不是早上"],["離公司很遠","","文中餐廳在 'next to our office'"]]},{"q":"What should employees do by September 10?","o":["Pay for dinner","Buy a ticket","Bring beverages","Reply to Ms. Ortiz"],"a":3,"k":"細節題：找 by September 10 → respond to Ms. Ortiz","n":[["付晚餐錢","","晚餐免費，不用付錢"],["買票","","文中沒提到票"],["帶飲料","","飲料免費提供，不用自備"],["回覆 Ms. Ortiz","","文中 'respond to Ms. Ortiz'，respond = 回覆"]]}]},
{"id":"r400-18","lv":400,"p":7,"k":"email","ti":"Software update on Saturday","tx":"To: All employees\nFrom: IT Department\nSubject: Software update on Saturday\n\nDear all,\n\nWe will install new software on all office computers this Saturday. The work will start at 8 A.M. and take about four hours. During this time, you cannot use your e-mail account or the company network.\n\nBefore you leave on Friday, please save your files and turn off your computer. If you have a problem on Monday, contact the IT help desk.","zh":"收件人：全體員工\n寄件人：資訊部門\n主旨：星期六軟體更新\n\n大家好：\n\n這個星期六，我們會在辦公室所有的電腦上安裝新軟體。作業將從上午 8 點開始，大約需要四個小時。這段時間內，各位無法使用電子郵件帳號或公司網路。\n\n星期五下班前，請儲存您的檔案並把電腦關機。如果星期一有問題，請聯絡資訊服務台。","w":[10,35,46,233,189,30,0,125,172,230,2],"qs":[{"q":"What is the e-mail mainly about?","o":["A change in office hours","A new employee","A software update","A lost computer"],"a":2,"k":"主旨題：標題 Software update on Saturday","n":[["上班時間改變","","文中沒提到上班時間"],["新員工","","文中沒提到新員工"],["軟體更新","","文中 'install new software on all office computers'"],["電腦遺失","","文中沒提到遺失"]]},{"q":"When will the work most likely finish?","o":["On Monday morning","At 8 A.M. on Saturday","On Friday evening","Around noon on Saturday"],"a":3,"k":"推論題：starts at 8 A.M. + take about four hours","n":[["週一早上","","週一是有問題時才找 help desk"],["週六早上八點","","8 A.M. 是開始時間，不是結束"],["週五晚上","","週五是下班前存檔關機"],["週六中午左右","","8 A.M. 加 about four hours，約中午"]]},{"q":"What should employees do before they leave on Friday?","o":["Turn off their computers","Change their e-mail password","Install the software","Call the help desk"],"a":0,"k":"細節題：找 Before you leave on Friday","n":[["關掉電腦","","文中 'save your files and turn off your computer'"],["改電子郵件密碼","","文中沒提到改密碼"],["安裝軟體","","安裝由 IT 部門做，員工不用裝"],["打給服務台","","help desk 是週一有問題時才找"]]}]},
{"id":"r400-19","lv":400,"p":7,"k":"article","ti":"New bus route to the airport","tx":"New Bus Route to the Airport\n\nStarting May 1, a new bus route will run between the city center and the airport. Bus 88 will depart from Central Station every 20 minutes. The trip takes about 40 minutes.\n\nThe fare is $3 for adults and $1 for children. Passengers can pay with cash or a bus card. The city hopes the new route will reduce traffic on the airport road.","zh":"通往機場的新公車路線\n\n從 5 月 1 日起，將有一條新的公車路線往返市中心和機場。88 號公車每 20 分鐘從 Central Station 發車，車程大約 40 分鐘。\n\n票價是成人 3 美元、兒童 1 美元。乘客可以用現金或公車卡付費。市政府希望這條新路線能減少機場道路的車流量。","w":[48,222,39,1,198],"qs":[{"q":"What is the article about?","o":["A new airport","A train station closing","Higher parking fees","A new bus service"],"a":3,"k":"主旨題：標題 New Bus Route to the Airport","n":[["新機場","","新的是公車路線，不是機場"],["火車站關閉","","Central Station 只是公車發車處"],["停車費漲價","","文中沒提到停車費"],["新公車服務","","文中 'a new bus route will run ... airport'"]]},{"q":"How often will Bus 88 leave Central Station?","o":["Every hour","Every 20 minutes","Every 10 minutes","Every 40 minutes"],"a":1,"k":"細節題：找 depart from Central Station every 20 minutes","n":[["每小時","","文中是 every 20 minutes"],["每 20 分鐘","","文中 'every 20 minutes'"],["每 10 分鐘","","文中沒有 10 分鐘"],["每 40 分鐘","","40 分鐘是車程，不是間隔"]]},{"q":"What does the city hope the new route will do?","o":["Give drivers more jobs","Lower the amount of traffic","Make bus fares cheaper","Bring more visitors to the city"],"a":1,"k":"細節題：找 The city hopes ... reduce traffic","n":[["給司機更多工作","","文中沒提到工作機會"],["減少車流量","","文中 'reduce traffic on the airport road'"],["讓車費變便宜","","文中只列票價，沒說要降價"],["吸引更多遊客","","文中沒提到遊客"]]}]},
{"id":"r400-20","lv":400,"p":7,"k":"notice","ti":"New parking rules at Riverside Mall","tx":"Riverside Mall — New Parking Rules\n\nThese rules start on August 1.\n\nCustomers with a shopping receipt can park free for two hours. Please show the receipt to the cashier at the exit. After two hours, the fee is $2 per hour.\n\nMotorcycles must use the separate section near Gate B. Vehicles cannot stay in the parking lot overnight. The lot is open from 8 A.M. to 11 P.M.","zh":"Riverside Mall——停車新規定\n\n這些規定從 8 月 1 日開始實施。\n\n持有購物收據的顧客可以免費停車兩小時。請在出口把收據拿給收銀員看。超過兩小時後，費用是每小時 2 美元。\n\n機車必須停在 B 入口附近的獨立區域。車輛不可以在停車場過夜。停車場的開放時間是上午 8 點到晚上 11 點。","w":[15,4,7,249,55,26],"qs":[{"q":"What is the notice about?","o":["New rules for parking","A new store at the mall","A sale at the mall","A job for cashiers"],"a":0,"k":"主旨題：標題 New Parking Rules","n":[["停車新規定","","文中 'New Parking Rules'"],["商場新店","","文中沒提到新店"],["商場特賣","","文中沒提到特賣"],["收銀員職缺","","cashier 只是出示收據的對象"]]},{"q":"How can customers park free for two hours?","o":["By paying $2","By parking near Gate B","By arriving before 8 A.M.","By showing a shopping receipt"],"a":3,"k":"細節題：找 with a shopping receipt can park free for two hours","n":[["付 2 美元","","$2 是兩小時後每小時的費用"],["停在 B 門附近","","Gate B 是機車專用區"],["早上八點前到","","8 A.M. 是開放時間，不是免費條件"],["出示購物收據","","文中 'with a shopping receipt can park free'"]]},{"q":"What are drivers NOT allowed to do?","o":["Leave a vehicle in the lot all night","Park a motorcycle","Pay the cashier at the exit","Park for more than two hours"],"a":0,"k":"細節題：問禁止什麼 → 找 Vehicles cannot stay ... overnight","n":[["整晚把車留在停車場","","文中 'cannot stay in the parking lot overnight'"],["停機車","","可以，但要用 Gate B 附近專區"],["向出口收銀員付費","","文中只說在出口向 cashier 出示收據，沒有禁止這件事"],["停超過兩小時","","可以，超過後每小時 $2"]]}]},
{"id":"r400-21","lv":400,"p":6,"k":"email","ti":"Your interview on May 14","tx":"To: Maria Santos\nFrom: Daniel Cho, Human Resources\nSubject: Your interview\n\nDear Ms. Santos,\n\nThank you for applying for the sales job at Brightway Electronics. We would like to [1] ------- you to an interview on Tuesday, May 14, at 10 A.M.\n\nThe interview [2] ------- about 30 minutes. Please bring a copy of your résumé. When you arrive, please give your name to the receptionist in the lobby.\n\n[3] ------- We look forward to meeting you.","zh":"收件人：Maria Santos\n寄件人：Daniel Cho（人力資源部）\n主旨：您的面試\n\nSantos 小姐您好：\n\n感謝您應徵 Brightway Electronics 的業務工作。我們想邀請您在 5 月 14 日星期二上午 10 點來面試。\n\n面試大約需要 30 分鐘。請帶一份履歷。抵達時，請把您的名字告訴大廳的接待人員。\n\n請回覆這封電子郵件確認時間。我們期待與您見面。","w":[197,173,231,32,13,196,2],"qs":[{"q":"[1]","o":["attend","invite","deliver","remind"],"a":1,"k":"單字：invite you to an interview → 邀請你面試","n":[["(v.) 參加","","attend 後面直接接活動，不接 you 再加 to"],["(v.) 邀請","invite + 人 + to + 活動","文中 invite you to an interview 語意通順"],["(v.) 遞送","","語意不合：不是遞送面試"],["(v.) 提醒","","remind 不接 to an interview，也不符合邀請語意"]]},{"q":"[2]","o":["took","has taken","will take","taking"],"a":2,"k":"時態／語態：面試還沒發生，about 30 minutes → 未來式","n":[["(過去式) 花了","","面試在 May 14，還沒發生，不用過去式"],["(完成式) 已花了","","現在完成式表示已發生，與未來面試不合"],["(未來式) 將花","will + 原形動詞","面試在未來，用 will take 說明時長"],["(-ing) 花","","taking 不是完整動詞，句子缺動詞"]]},{"q":"[3]","o":["Your first day of work is May 14.","Please reply to this e-mail to confirm the time.","The sales job is no longer open.","We were happy to meet you last week."],"a":1,"k":"句子插入：信的結尾，要求確認時間 → 呼應 look forward","n":[["你的上班第一天是 5 月 14 日","","與前文矛盾：5 月 14 日是面試日"],["請回覆此信確認時間","","承接面試時間，下一句 look forward 也通順"],["這份業務工作已不再開放","","與前文矛盾：信中正邀請她面試"],["我們上週很高興見到你","","與前文矛盾：還沒見過面，才說 look forward"]]}]},
{"id":"r400-22","lv":400,"p":6,"k":"notice","ti":"Power off on Sunday","tx":"NOTICE: Power Off on Sunday\n\nThe power in the Green Tower office building will be turned off on Sunday, June 9, from 7 A.M. to 1 P.M. Workers need to [1] ------- some old equipment.\n\nDuring this time, the lights, elevators, and air conditioners will not work. [2] -------, please do not come to the office on Sunday morning.\n\nBefore you leave on Friday, turn off your computer and printer. This will [3] ------- damage to your devices.","zh":"公告：星期日停電\n\nGreen Tower 辦公大樓將在 6 月 9 日星期日上午 7 點到下午 1 點停電。工人需要更換一些老舊的設備。\n\n這段時間內，電燈、電梯和冷氣都無法使用。所以，星期日早上請不要到辦公室來。\n\n星期五下班前，請把電腦和印表機關機。這樣可以防止您的裝置受損。","w":[117,212,44,16,215,242,71],"qs":[{"q":"[1]","o":["replace","remain","respond","participate"],"a":0,"k":"單字：old equipment 當受詞 → replace some old equipment","n":[["(v.) 更換","replace + 受詞","文中 Workers need to replace some old equipment 通順"],["(v.) 保持","","remain 不接受詞，不能接 some old equipment"],["(v.) 回應","","respond 要加 to，且語意不合"],["(v.) 參加","","participate 要加 in，且語意不合"]]},{"q":"[2]","o":["Or","So","Because","But"],"a":1,"k":"連接詞：前句說停電、後句說別來 → 結果，用 So","n":[["(conj.) 或者","","文法可以，但語意不通：前後不是二選一"],["(adv.) 所以","So, + 祈使句","停電是原因，不要來是結果"],["(conj.) 因為","","Because 引導子句，後面不能接 please 祈使句"],["(conj.) 但是","","文法可以，但語意不通：前後不是轉折"]]},{"q":"[3]","o":["prevent","perform","present","propose"],"a":0,"k":"單字：關電腦 → 防止損壞，prevent damage","n":[["(v.) 防止","prevent + damage","prevent damage 是常見搭配，語意通順"],["(v.) 執行","","語意不合：不會 perform damage"],["(v.) 呈現","","語意不合：present damage 不是此意"],["(v.) 提議","","語意不合：propose damage 不通"]]}]},
{"id":"r400-23","lv":400,"p":6,"k":"memo","ti":"New employee starts Monday","tx":"MEMO\nTo: All staff\nFrom: Grace Liu, Office Manager\nSubject: New employee\n\nA new employee, Mr. Ryan Scott, will join the sales department on Monday. Before this, he [1] ------- at a bank for five years.\n\nOn his first day, Ms. Tan will give him a [2] ------- of the office and introduce him to everyone. His desk is next to the printer on the second floor.\n\nPlease [3] ------- him if he has any questions.","zh":"備忘錄\n收件人：全體員工\n寄件人：辦公室經理 Grace Liu\n主旨：新進員工\n\n新員工 Ryan Scott 先生將於星期一加入業務部門。在這之前，他在銀行工作了五年。\n\n第一天上班時，Tan 小姐會帶他參觀辦公室，並把他介紹給大家。他的座位在二樓的印表機旁邊。\n\n如果他有任何問題，請大家協助他。","w":[40,10,35,108,214,16,193,2],"qs":[{"q":"[1]","o":["will work","working","worked","works"],"a":2,"k":"時態：Before this 指上班之前 + for five years → 過去式","n":[["(未來式) 將工作","","Before this 指過去，不是未來"],["(-ing) 工作","","working 不是完整動詞，句子缺動詞"],["(過去式) 工作","worked + for + 時間","他過去在銀行工作五年，用過去式"],["(現在式) 工作","","現在式與 Before this 的過去時間不合"]]},{"q":"[2]","o":["tour","fare","sample","loan"],"a":0,"k":"單字：give him a ___ of the office → 導覽","n":[["(n.) 導覽","a tour of + 地點","give sb a tour of + 地點 指帶人參觀"],["(n.) 車資","","語意不合：fare 是交通費用"],["(n.) 樣品","","語意不合：sample 是樣本"],["(n.) 貸款","","語意不合：loan 是貸款"]]},{"q":"[3]","o":["assistant","assisted","assistance","assist"],"a":3,"k":"詞性：Please 後接原形動詞 + him → assist him","n":[["(n.) 助理","","名詞，Please 後面要接動詞"],["(過去式) 協助","","Please 後面要用原形動詞，不用過去式"],["(n.) 協助","","名詞，不能直接接受詞 him"],["(v.) 協助","Please + 原形動詞","Please + 原形動詞，assist him 是請協助他"]]}]},
{"id":"r400-24","lv":400,"p":6,"k":"advertisement","ti":"Happy Road Car Rental","tx":"Happy Road Car Rental\n\nDo you need a car for your next trip? At Happy Road, you can [1] ------- a car for only $40 a day. We have a wide range of vehicles, from small cars to large vans.\n\nEvery car is [2] ------- by our staff before you drive it. You do not need to pay extra for insurance [3] ------- it is included in the price.\n\nBook online today and save 10%!","zh":"Happy Road Car Rental\n\n下一趟旅行需要用車嗎？在 Happy Road，您每天只要 40 美元就可以租到一輛車。我們有各式各樣的車輛，從小型車到大型廂型車都有。\n\n每一輛車在您開走之前，都由我們的員工檢查過。您不需要為保險額外付費，因為保險已經包含在價格裡。\n\n今天就上網預訂，可以省下 10%！","w":[228,127,26,40,78,185,172],"qs":[{"q":"[1]","o":["retire","attend","depart","rent"],"a":3,"k":"單字：a car for only $40 a day → 租車","n":[["(v.) 退休","","語意不合：車不能 retire"],["(v.) 參加","","語意不合：attend 後面不接 a car"],["(v.) 出發","","depart 指出發離開（可接地點），不能接 a car"],["(v.) 租用","rent + a car","文中是租車公司，rent a car 租車"]]},{"q":"[2]","o":["checks","checking","checked","check"],"a":2,"k":"語態：Every car is ___ by our staff → 被動","n":[["(v.) 檢查（第三人稱）","","is 後面不能接 checks"],["(-ing) 檢查","","is checking 是主動，車不會自己檢查"],["(p.p.) 被檢查","be + p.p. + by","is + 過去分詞，by our staff 表被動"],["(原形) 檢查","","is 後面不能接原形動詞"]]},{"q":"[3]","o":["so","or","but","because"],"a":3,"k":"連接詞：免付保險費 ← 保險已含在價格內 → 原因","n":[["(conj.) 所以","","文法可以，但因果顛倒：保險已含才不用付"],["(conj.) 或","","文法可以，但語意不通：不是二選一"],["(conj.) 但是","","文法可以，但語意不通：後句不是轉折"],["(conj.) 因為","結果, because + 原因","後句 it is included 是不用付的原因"]]}]},
{"id":"r400-25","lv":400,"p":6,"k":"letter","ti":"About your coffee maker","tx":"Dear Ms. Howard,\n\nThank you for your letter of March 3. We are sorry that the coffee maker you bought at our store [1] ------- working after only one week. We would like to [2] ------- for this problem.\n\nYou have two options. We can send you a new coffee maker, [3] ------- we can give you a full refund. Please call us at 555-0199 and tell us your decision.\n\nSincerely,\nTom Berg\nCustomer Service, Kitchen Corner","zh":"Howard 小姐您好：\n\n感謝您 3 月 3 日的來信。很抱歉，您在本店購買的咖啡機才用了一個星期就故障了。我們想為這個問題向您道歉。\n\n您有兩個選擇。我們可以寄一台新的咖啡機給您，或是全額退款給您。請撥打 555-0199，告訴我們您的決定。\n\n敬上\nTom Berg\nKitchen Corner 客戶服務部","w":[180,14,119,53],"qs":[{"q":"[1]","o":["stopped","stops","will stop","stopping"],"a":0,"k":"時態：bought 與 after only one week → 過去式","n":[["(過去式) 停了","stop working","stopped working 表示壞掉了，與 bought 同為過去"],["(現在式) 停","","現在式與 bought、after one week 的過去時間不合"],["(未來式) 將停","","問題已發生，不是未來"],["(-ing) 停","","stopping 不是完整動詞，句子缺動詞"]]},{"q":"[2]","o":["apply","apologize","subscribe","participate"],"a":1,"k":"單字：We would like to ___ for this problem → 為此道歉","n":[["(v.) 申請","","apply for 通常接職位或許可，不接 problem"],["(v.) 道歉","apologize for + N","apologize for + 事情，與 sorry 呼應"],["(v.) 訂閱","","語意不合：subscribe 要加 to"],["(v.) 參加","","語意不合：participate 要加 in"]]},{"q":"[3]","o":["or","until","because","so"],"a":0,"k":"連接詞：兩個選項 → send a new one or refund，用 or","n":[["(conj.) 或者","A, or B","You have two options，用 or 連接兩個選項"],["(conj.) 直到","","語意不合：until 表時間持續"],["(conj.) 因為","","語意不合：兩個選項不是因果"],["(conj.) 所以","","語意不合：兩個選項不是結果"]]}]},
{"id":"r400-26","lv":400,"p":6,"k":"announcement","ti":"Holiday hours at Green Basket Market","tx":"Holiday Hours at Green Basket Market\n\nDear customers,\n\nGreen Basket Market will be closed on Thursday, January 1, for the New Year holiday. We will open again on Friday at our [1] ------- time, 8 A.M.\n\nOn Wednesday, December 31, the store will close early at 6 P.M. [2] -------\n\nThis week, all beverages are 20% off. Thank you for your [3] ------- this year. We wish you a happy New Year!","zh":"Green Basket Market 假期營業時間\n\n各位顧客您好：\n\nGreen Basket Market 將於 1 月 1 日星期四元旦假期休息一天。我們會在星期五照平常的時間上午 8 點恢復營業。\n\n12 月 31 日星期三，本店將提早在下午 6 點打烊。請在那之前完成購物。\n\n本週所有飲料一律八折。感謝您這一年來的支持。祝您新年快樂！","w":[137,86,111,235],"qs":[{"q":"[1]","o":["annual","frequent","entire","regular"],"a":3,"k":"單字：open again at our ___ time, 8 A.M. → 平常的","n":[["(adj.) 每年的","","語意不合：開店時間不是每年一次"],["(adj.) 頻繁的","","語意不合：frequent 指次數多"],["(adj.) 整個的","","語意不合：不是整個時間"],["(adj.) 平常的","our regular + N","regular time 指平常的營業時間"]]},{"q":"[2]","o":["We will stay open until midnight that day.","Please finish your shopping before then.","The meeting will be in Room 2.","Thank you for returning the item."],"a":1,"k":"句子插入：前句 close early at 6 P.M. → 提醒提早購物","n":[["當天營業到午夜","","與前句矛盾：前句說 6 P.M. 就關門"],["請在那之前完成購物","","承接 close early at 6 P.M.，提醒顧客"],["會議在二號會議室","","與賣場公告無關"],["謝謝你退回商品","","文中沒有退貨相關內容"]]},{"q":"[3]","o":["damage","pollution","support","complaint"],"a":2,"k":"單字：Thank you for your ___ this year → 支持","n":[["(n.) 損害","","語意不合：不會感謝顧客的損害"],["(n.) 污染","","語意不合：與感謝無關"],["(n.) 支持","thank you for your + N","Thank you for your support 是常用感謝語"],["(n.) 抱怨","","語意不合：不會感謝抱怨"]]}]},
{"id":"r400-27","lv":400,"p":6,"k":"message","ti":"Price list for Mr. Baker","tx":"Hi Jenny,\n\nI am sorry to [1] ------- you on your day off. I looked in every folder on my computer, but I cannot find the price list for our client, Mr. Baker. He [2] ------- it by 3 P.M. today.\n\nCould you tell me where the file is? [3] ------- you have a copy, please attach it to an e-mail and send it to me. Then I can give it to Mr. Baker immediately.\n\nThank you!\nCarla","zh":"嗨，Jenny：\n\n很抱歉在妳休假的時候打擾妳。我找遍了電腦裡的每一個資料夾，還是找不到要給客戶 Baker 先生的價目表。他今天下午 3 點以前就需要這份資料。\n\n可以告訴我檔案放在哪裡嗎？如果妳有備份，請把它附在電子郵件裡寄給我。這樣我就可以立刻交給 Baker 先生。\n\n謝謝！\nCarla","w":[223,38,219,170],"qs":[{"q":"[1]","o":["disturb","develop","deliver","display"],"a":0,"k":"單字：sorry to ___ you on your day off → 打擾","n":[["(v.) 打擾","sorry to disturb you","在休假日聯絡對方，用 disturb"],["(v.) 發展","","語意不合：develop you 不通"],["(v.) 遞送","","語意不合：不是遞送人"],["(v.) 展示","","語意不合：display you 不通"]]},{"q":"[2]","o":["need","needs","to need","needing"],"a":1,"k":"主詞動詞一致：He 為第三人稱單數 → needs","n":[["(原形) 需要","","主詞 He 是單數，動詞要加 s"],["(第三人稱單數) 需要","He + V-s","He + needs，現在式第三人稱單數"],["(不定詞) 需要","","to need 不是完整動詞，句子缺動詞"],["(-ing) 需要","","needing 不是完整動詞，句子缺動詞"]]},{"q":"[3]","o":["But","So","Or","If"],"a":3,"k":"連接詞：假設有副本 → 請寄給我，用 If","n":[["(conj.) 但是","","兩個完整句只用逗號連接不合文法，句意也不是轉折"],["(conj.) 所以","","兩個完整句只用逗號連接不合文法，也沒有因果關係"],["(conj.) 或者","","兩個完整句只用逗號連接不合文法，句意也不是二選一"],["(conj.) 如果","If + 子句, 祈使句","If you have a copy 表條件，後接 please 祈使句"]]}]},
{"id":"r400-28","lv":400,"p":6,"k":"article","ti":"Survey: workers like short meetings","tx":"Survey: Workers Like Short Meetings\n\nA new survey asked 500 office workers about meetings. The [1] ------- show that most workers do not like long meetings. Nearly 70% said that a meeting should be 30 minutes or less.\n\nMany workers also said that they [2] ------- too many meetings each week. Experts recommend that managers send the topics to staff before each meeting. This can [3] ------- the time that workers spend in meetings.","zh":"調查：上班族喜歡簡短的會議\n\n一項新的調查詢問了 500 位上班族對會議的看法。結果顯示，大多數上班族不喜歡冗長的會議。將近 70% 的人說，一場會議應該在 30 分鐘以內。\n\n許多上班族也說，他們每星期參加太多會議。專家建議主管在每次開會前，先把討論的主題寄給員工。這樣可以減少員工花在會議上的時間。","w":[126,105,171,175,88,208,40,198],"qs":[{"q":"[1]","o":["results","fares","wages","goods"],"a":0,"k":"單字：The ___ show that most workers... → 調查結果","n":[["(n.) 結果","the results show that","survey results 調查結果，與複數 show 一致"],["(n.) 車資","","語意不合：與調查無關"],["(n.) 薪資","","語意不合：調查說的是開會看法"],["(n.) 商品","","語意不合：調查不是商品"]]},{"q":"[2]","o":["to attend","attends","attending","attend"],"a":3,"k":"詞形：they 為複數主詞 + too many meetings → attend","n":[["(不定詞) 參加","","to attend 不是完整動詞，句子缺動詞"],["(第三人稱單數) 參加","","主詞 they 是複數，不加 s"],["(-ing) 參加","","attending 不是完整動詞，句子缺動詞"],["(原形) 參加","they + 原形動詞","they + attend，現在式複數主詞用原形"]]},{"q":"[3]","o":["remind","reduce","respond","retire"],"a":1,"k":"單字：send the topics before → 縮短時間 → reduce","n":[["(v.) 提醒","","語意不合：remind the time 不通"],["(v.) 減少","reduce + the time","reduce the time 減少時間，語意通順"],["(v.) 回應","","respond 要加 to，且語意不合"],["(v.) 退休","","語意不合：不接 the time"]]}]},
{"id":"r400-29","lv":400,"p":6,"k":"email","ti":"Welcome to Bayside Business Weekly","tx":"To: Paul Green\nFrom: Bayside Business Weekly\nSubject: Welcome!\n\nDear Mr. Green,\n\nThank you for [1] ------- to Bayside Business Weekly. You can now read all of our articles online. The week's top news [2] ------- to your e-mail address every Monday morning.\n\nYour first month is free. After that, the [3] ------- is $5 per month. You can cancel at any time. If you have any questions, please contact us.","zh":"收件人：Paul Green\n寄件人：Bayside Business Weekly\n主旨：歡迎！\n\nGreen 先生您好：\n\n感謝您訂閱 Bayside Business Weekly。您現在可以在網路上閱讀我們所有的文章。每星期一早上，當週的重點新聞會寄到您的電子郵件信箱。\n\n第一個月免費。之後的費用是每個月 5 美元。您隨時可以取消。如果有任何問題，請與我們聯絡。","w":[211,64,7,176,230,2],"qs":[{"q":"[1]","o":["subscribing","subscribe","subscribed","subscribes"],"a":0,"k":"詞性：Thank you for 後面接 -ing → subscribing","n":[["(v.-ing) 訂閱","thank you for + V-ing","for 是介系詞，後面接動名詞"],["(原形) 訂閱","","介系詞 for 後不能接原形動詞"],["(過去式) 訂閱","","介系詞 for 後不能接過去式"],["(第三人稱單數) 訂閱","","介系詞 for 後不能接第三人稱單數動詞"]]},{"q":"[2]","o":["is sent","sent","is sending","sends"],"a":0,"k":"語態：news 被寄到信箱 → 被動 is sent","n":[["(被動) 被寄送","be + p.p. + to","news 是被寄出，is sent to 表被動"],["(過去式) 寄","","every Monday 表習慣，且缺少被動的 is"],["(現在進行式) 在寄","","is sending 是主動，news 不會自己寄"],["(現在式) 寄","","sends 是主動，news 不會自己寄"]]},{"q":"[3]","o":["fare","loan","fee","wage"],"a":2,"k":"單字：After that, the ___ is $5 per month → 費用","n":[["(n.) 車資","","fare 指交通費，不用於訂閱費"],["(n.) 貸款","","語意不合：訂閱不是貸款"],["(n.) 費用","the fee is + 金額","$5 per month 是訂閱費，用 fee"],["(n.) 薪資","","語意不合：wage 是工資"]]}]},
{"id":"r400-30","lv":400,"p":6,"k":"review","ti":"Lunch at Corner Table Café","tx":"Corner Table Café — Review by Tina R.\n\nI had lunch at Corner Table Café with two colleagues last Friday. We did not have a [1] -------, but we got a table in five minutes.\n\nThe menu is small, but there is a good selection of beverages. Our food [2] ------- only ten minutes after we ordered. The prices are a little high. [3] -------, I will go back again because the service was so good.","zh":"Corner Table Café——Tina R. 的評論\n\n上星期五我和兩位同事在 Corner Table Café 吃午餐。我們沒有訂位，但是五分鐘就有位子了。\n\n菜單上的選擇不多，不過飲料的種類很豐富。我們點餐後才十分鐘，餐點就送來了。價格有一點高。不過，因為服務非常好，我還會再去。","w":[90,9,57,86],"qs":[{"q":"[1]","o":["reservation","description","departure","destination"],"a":0,"k":"單字：did not have a ___, but got a table → 訂位","n":[["(n.) 訂位","have a reservation","沒訂位，但五分鐘就有位子"],["(n.) 描述","","語意不合：和找座位無關"],["(n.) 出發","","語意不合：與用餐無關"],["(n.) 目的地","","語意不合：餐廳不是目的地"]]},{"q":"[2]","o":["arrived","will arrive","arriving","arrives"],"a":0,"k":"時態：last Friday、ordered → 過去式","n":[["(過去式) 抵達","V-ed + after we ordered","last Friday 是過去，用 arrived"],["(未來式) 將抵達","","last Friday 是過去，不用 will"],["(-ing) 抵達","","arriving 不是完整動詞，句子缺動詞"],["(現在式) 抵達","","現在式與 last Friday 的過去時間不合"]]},{"q":"[3]","o":["For example","Therefore","However","Because"],"a":2,"k":"連接詞：價格偏高 → 還是會再來 → 轉折，用 However","n":[["(片語) 例如","","語意不合：後句不是舉例"],["(adv.) 因此","","文法可以，但語意不通：價高不是回去的原因"],["(adv.) 然而","However, + 句子","價格高、仍想回去，是轉折"],["(conj.) 因為","","Because 引導子句，不能接逗號後主句"]]}]},
{"id":"r600-01","lv":600,"p":7,"k":"email","ti":"Your shipment is delayed","tx":"To: Kevin Wu\nFrom: Customer Service, Maple Home Store\nSubject: Your shipment is delayed\n\nDear Mr. Wu,\n\nThank you for your recent purchase. We are sorry to tell you that your shipment has been delayed. The desk lamp you ordered is in stock, but heavy snow has stopped our courier from leaving the warehouse. We now expect your order to arrive on Friday, March 14, instead of Tuesday.\n\nYou can track your package on our website at any time. Because of this delay, we will not charge you for shipping. The $8 fee will be returned to your credit card within approximately five days.\n\nIf you have any questions, please do not hesitate to contact us.\n\nSincerely,\nNina Ross","zh":"收件人：Kevin Wu\n寄件人：Maple Home Store 客服部\n主旨：您的貨件延遲了\n\n吳先生您好：\n\n感謝您最近的購買。很抱歉通知您，您的貨件延遲了。您訂購的檯燈有現貨，但大雪讓我們的快遞員無法離開倉庫。我們現在預計您的訂單會在 3 月 14 日星期五送達，而不是星期二。\n\n您可以隨時在我們的網站上追蹤包裹。由於這次延遲，我們不會向您收取運費。8 美元的費用將在大約五天內退回您的信用卡。\n\n如果您有任何問題，請不要猶豫，隨時與我們聯絡。\n\nNina Ross 敬上","w":[492,316,345,341,485,486,366,420,430],"qs":[{"q":"What is the purpose of the e-mail?","o":["To advertise a new desk lamp","To say that an item is out of stock","To explain that an order will arrive late","To ask a customer to pay a fee"],"a":2,"k":"主旨題：開頭 'shipment has been delayed' → 通知訂單晚到","n":[["宣傳新檯燈","","檯燈是已訂購的商品，信中沒有促銷內容"],["說明商品缺貨","","文中說 'is in stock'，是有貨，不是缺貨"],["說明訂單會晚到","","文中 'has been delayed'，改為 Friday, March 14 到貨"],["要求顧客付費","","文中說不收運費，$8 會退回，剛好相反"]]},{"q":"Why has the order been delayed?","o":["The customer's address was wrong","Bad weather stopped the courier","The payment was not received","The lamp is not in stock"],"a":1,"k":"細節題：找 delayed 的原因 → 'heavy snow has stopped our courier'","n":[["顧客地址有誤","","文中沒提到地址問題"],["壞天氣讓快遞無法出發","","文中 'heavy snow has stopped our courier'，snow = 壞天氣"],["沒收到款項","","文中沒提到付款問題"],["檯燈沒有庫存","","文中說 'is in stock'，有庫存"]]},{"q":"The word \"track\" in the passage is closest in meaning to","o":["follow","weigh","wrap","cancel"],"a":0,"k":"字義題：'track your package' 看包裹的動向 → 追蹤","n":[["(v.) 追蹤、跟隨","","'track your package' 是追蹤包裹行蹤，意思同 follow"],["(v.) 秤重","","在網站上不可能秤重，語意不合"],["(v.) 包裝","","在網站上查詢不是包裝，語意不合"],["(v.) 取消","","文中說追蹤，不是取消訂單"]]}]},
{"id":"r600-02","lv":600,"p":7,"k":"email","ti":"Interview for sales assistant position","tx":"To: Grace Liu\nFrom: Daniel Ortiz, Human Resources\nSubject: Interview for sales assistant position\n\nDear Ms. Liu,\n\nThank you for your application for the sales assistant position at Bright Office Supplies. We were pleased with your résumé and would like to invite you to an interview on Thursday, May 8, at 10:00 A.M. The interview will be held at our main office and will take approximately 40 minutes.\n\nPlease bring photo identification and a copy of your computer skills certificate. You will meet Ms. Park, the supervisor of the sales team.\n\nIf this time is not possible for you, please reply by Monday so that we can reschedule.\n\nBest regards,\nDaniel Ortiz","zh":"收件人：Grace Liu\n寄件人：人力資源部 Daniel Ortiz\n主旨：業務助理職位面試\n\n劉小姐您好：\n\n感謝您應徵 Bright Office Supplies 的業務助理職位。我們對您的履歷很滿意，想邀請您在 5 月 8 日星期四上午 10 點來面試。面試將在我們的總公司進行，大約需要 40 分鐘。\n\n請攜帶附照片的身分證明文件，以及您的電腦技能證書影本。您將會見到業務團隊的主管 Park 小姐。\n\n如果這個時間您不方便，請在星期一之前回覆，以便我們改期。\n\nDaniel Ortiz 敬上","w":[276,338,291,420,269,256,319,424],"qs":[{"q":"Why did Mr. Ortiz write to Ms. Liu?","o":["To invite her to a job interview","To tell her she got the job","To cancel an appointment","To ask her to send a résumé"],"a":0,"k":"主旨題：'would like to invite you to an interview'","n":[["邀請她來面試","","文中 'would like to invite you to an interview'"],["告訴她錄取了","","信中只是邀請面試，並未錄取"],["取消約定","","文中是安排面試，不是取消"],["請她寄履歷","","文中 'pleased with your résumé'，已收到履歷"]]},{"q":"What is Ms. Liu asked to bring?","o":["A letter from her supervisor","Her university transcript","A printed résumé","Photo identification"],"a":3,"k":"細節題：找 bring → 'Please bring photo identification'","n":[["主管寫的信","","文中 supervisor 是 Ms. Park，沒要求帶信"],["大學成績單","","文中沒要求成績單"],["列印的履歷","","履歷已收到，文中沒要求再帶"],["附照片的身分證明","","文中 'Please bring photo identification'"]]},{"q":"The word \"position\" in the passage is closest in meaning to","o":["order","opinion","place","job"],"a":3,"k":"字義題：'sales assistant position' 是應徵的職缺 → job","n":[["(n.) 訂單、順序","","order 不能指職缺，語意不合"],["(n.) 意見","","應徵的是職缺，不是意見"],["(n.) 地方","","position 這裡不是地點，是職位"],["(n.) 工作、職位","","'sales assistant position' = 業務助理的工作"]]}]},
{"id":"r600-03","lv":600,"p":6,"k":"email","ti":"Conference registration confirmed","tx":"To: Peter Yang\nFrom: Events Team, National Marketing Conference\nSubject: Registration confirmed\n\nDear Mr. Yang,\n\nThank you for registering for the National Marketing Conference on September 19. We have received your payment of $120.\n\nThe conference will be held at the Lakeside Convention Center. Each [1] ------- lasts one hour, and the full schedule [2] ------- to this e-mail. Please arrive by 8:30 A.M. to pick up your name badge at the reception desk.\n\nLunch is included in the fee. [3] -------, parking is not, so we suggest using public transportation.\n\nWe look forward to seeing you.\n\nEvents Team","zh":"收件人：Peter Yang\n寄件人：National Marketing Conference 活動小組\n主旨：報名已確認\n\n楊先生您好：\n\n感謝您報名 9 月 19 日的 National Marketing Conference。我們已收到您 120 美元的款項。\n\n研討會將在 Lakeside Convention Center 舉行。每一場活動進行一小時，完整的時程表已附在這封電子郵件中。請在上午 8 點 30 分前抵達，到接待櫃台領取您的名牌。\n\n費用包含午餐。不過，停車費不包含在內，所以我們建議您搭乘大眾運輸工具。\n\n期待與您見面。\n\n活動小組","w":[262,278,494,320,325,451,279],"qs":[{"q":"[1]","o":["shipment","division","pension","session"],"a":3,"k":"單字：Each ___ lasts one hour，研討會的一場活動 → session","n":[["(n.) 貨運、出貨","","貨件不會 last one hour，語意不通"],["(n.) 部門","","部門不會持續一小時，語意不通"],["(n.) 退休金","","和研討會、時程表無關"],["(n.) 一場（會議、課程）","Each session lasts one hour","conference 裡的一場活動，後文有 schedule"]]},{"q":"[2]","o":["attaching","is attached","attaches","has attached"],"a":1,"k":"時態／語態：主詞 schedule 是被附上 → 被動 is attached","n":[["(V-ing) 附上","","前面沒有 be 動詞，不能當主要動詞"],["(被動) 被附上","be attached to + N","schedule 是被附上的東西，用被動"],["(v.) 附上（主動）","","主動語態，變成時程表自己去附加，語意不通"],["(完成式) 已附上","","主動式缺受詞，時程表不會自己附加，要用被動"]]},{"q":"[3]","o":["Therefore","For example","In addition","However"],"a":3,"k":"連接詞：前句午餐含在內、後句停車不含 → 轉折 However","n":[["(adv.) 因此","","前後是相反關係，不是因果"],["(adv.) 例如","","停車不是午餐的例子"],["(adv.) 此外","","用於補充同類資訊，這裡是相反"],["(adv.) 然而","However, + 句子","午餐包含、停車不包含，語氣轉折"]]}]},
{"id":"r600-04","lv":600,"p":7,"k":"notice","ti":"Elevator maintenance in the east wing","tx":"NOTICE TO ALL TENANTS\n\nThe elevator in the east wing of Lakeview Tower will be closed for maintenance on Wednesday, June 4, from 9:00 A.M. to 3:00 P.M. Technicians will replace several old parts so that the elevator continues to operate safely.\n\nDuring this time, please use the elevator in the west wing or the stairs adjacent to the lobby. Tenants who need help carrying heavy items may call the front desk at extension 105.\n\nWe apologize for the trouble and thank you for your patience. The work will be finished in one day, and no additional closures are planned this month.\n\nBuilding Management Office","zh":"致全體承租戶的公告\n\nLakeview Tower 東側的電梯將於 6 月 4 日星期三上午 9 點至下午 3 點關閉，進行維護保養。技術人員會更換幾個老舊零件，讓電梯能繼續安全運作。\n\n在這段時間，請使用西側的電梯，或大廳旁邊的樓梯。需要協助搬運重物的承租戶，可以撥分機 105 聯絡櫃台。\n\n造成不便，我們深感抱歉，也感謝您的耐心配合。工程將在一天內完成，本月沒有安排其他的關閉時間。\n\n大樓管理室","w":[339,292,333,443,389,283,405],"qs":[{"q":"What is the notice mainly about?","o":["The opening of a new lobby","A change in front desk hours","A temporary elevator closure","A new parking rule"],"a":2,"k":"主旨題：'elevator ... will be closed for maintenance'","n":[["新大廳啟用","","文中 lobby 只是樓梯的位置，沒說新開"],["櫃台時間變更","","櫃台只是求助電話，時間沒變"],["電梯暫時關閉","","'closed for maintenance' 且 'finished in one day'"],["新的停車規定","","文中沒提到停車"]]},{"q":"What should tenants do if they need help with heavy items?","o":["Visit the management office","Call the front desk","Wait for a technician","Use the east wing elevator"],"a":1,"k":"細節題：找 heavy items → 'may call the front desk'","n":[["去管理室","","文中沒叫人去管理室"],["打電話給櫃台","","文中 'may call the front desk at extension 105'"],["等技術人員","","技術人員在換零件，沒說要等他們"],["使用東側電梯","","東側電梯當天關閉，不能用"]]},{"q":"What is suggested about Lakeview Tower?","o":["It is closed on Wednesdays","It has more than one elevator","It was built this year","It has no stairs"],"a":1,"k":"推論題：east wing 與 west wing 各有電梯 → 不只一部","n":[["週三公休","","週三只是這次維修日，不是固定公休"],["有不只一部電梯","","文中有 'east wing' 和 'west wing' 的電梯"],["今年蓋好","","文中沒提建造時間"],["沒有樓梯","","文中有 'stairs adjacent to the lobby'"]]}]},
{"id":"r600-05","lv":600,"p":7,"k":"notice","ti":"Customer database update this Saturday","tx":"IT Department Notice: Customer Database Update\n\nThe customer database will not be available this Saturday, October 18, from 8:00 P.M. to midnight. During these hours, our technicians will install new hardware and add a search function that many employees have requested.\n\nPlease save your work and log out before 8:00 P.M. Any data entered after that time may be lost. Access will be restored on Sunday morning, and you will not need a new password.\n\nIf the database does not function correctly on Monday, do not attempt to fix the problem yourself. Call the help desk at extension 220, and a technician will assist you.","zh":"資訊部公告：客戶資料庫更新\n\n客戶資料庫將於本週六 10 月 18 日晚上 8 點至午夜暫停使用。在這段時間，我們的技術人員會安裝新的硬體設備，並加入許多員工要求的搜尋功能。\n\n請在晚上 8 點前儲存您的工作並登出。在那之後輸入的資料可能會遺失。星期日早上就可以恢復使用，您不需要新的密碼。\n\n如果星期一資料庫無法正常運作，請不要試著自己修理。請撥分機 220 聯絡服務台，會有技術人員協助您。","w":[302,333,323,491,371,487,283],"qs":[{"q":"What is the purpose of the notice?","o":["To ask employees to change their passwords","To report that customer data was lost","To introduce a new technician","To tell staff when a system will be unavailable"],"a":3,"k":"主旨題：'database will not be available' + 時間 → 通知停用","n":[["要求員工換密碼","","文中 'will not need a new password'"],["通報客戶資料遺失","","文中只說可能遺失輸入的資料，並未發生"],["介紹新技術人員","","文中沒有介紹任何人"],["告知系統何時無法使用","","'not be available' + 週六 8 點到午夜，通知停用時間"]]},{"q":"What should employees do before 8:00 P.M. on Saturday?","o":["Create a new password","Save their work and log out","Call the help desk","Install new hardware"],"a":1,"k":"細節題：找 before 8:00 P.M. → 'save your work and log out'","n":[["建立新密碼","","文中說不需要新密碼"],["存檔並登出","","文中 'save your work and log out before 8:00 P.M.'"],["打電話給服務台","","那是週一資料庫有問題時才做的事"],["安裝新硬體","","文中是 technicians 要安裝，不是員工"]]},{"q":"The word \"attempt\" in the passage is closest in meaning to","o":["forget","refuse","try","agree"],"a":2,"k":"字義題：'do not attempt to fix' 不要試著修 → try","n":[["(v.) 忘記","","'do not forget to fix' 與全文意思相反"],["(v.) 拒絕","","refuse 帶拒絕義，不是不要嘗試"],["(v.) 嘗試","attempt / try + to V","'attempt to fix' = try to fix，嘗試修理"],["(v.) 同意","","'agree to fix' 語意不合，且 agree 非嘗試"]]}]},
{"id":"r600-06","lv":600,"p":6,"k":"email","ti":"Replacement for your coffee maker","tx":"To: Olivia Grant\nFrom: Tom Reed, Customer Service\nSubject: Your coffee maker\n\nDear Ms. Grant,\n\nThank you for contacting us about the coffee maker that you [1] ------- from our online store last month. We are sorry to hear that it has stopped working.\n\nAll of our appliances come with a one-year [2] -------, so we will be happy to replace yours at no charge. Please put the machine back in its original box. A courier will pick it up from your home on a day that you choose.\n\n[3] ------- we receive the machine, a new one will be shipped to you within three business days.\n\nSincerely,\nTom Reed","zh":"收件人：Olivia Grant\n寄件人：客服部 Tom Reed\n主旨：您的咖啡機\n\nGrant 小姐您好：\n\n感謝您來信告知上個月在我們網路商店購買的咖啡機的狀況。很遺憾聽到它已經不能運作了。\n\n我們所有的家電都附有一年保固，所以我們很樂意免費為您更換。請把機器放回原本的箱子裡。快遞員會在您選擇的日期到府收件。\n\n我們收到機器之後，會在三個工作天內把新的咖啡機寄給您。\n\nTom Reed 敬上","w":[492,252,522,486,341],"qs":[{"q":"[1]","o":["purchased","purchase","purchasing","will purchase"],"a":0,"k":"時態：關鍵字 last month → 過去式 purchased","n":[["(過去式) 購買","","'last month' 指過去，用過去式"],["(v.) 購買（原形）","","現在式，與 last month 時間不合"],["(V-ing) 購買","","前面沒有 be 動詞，不能當子句動詞"],["(未來式) 將購買","","未來式，與 last month 矛盾"]]},{"q":"[2]","o":["deadline","agenda","warranty","proposal"],"a":2,"k":"單字：一年的___ → 免費更換 → 保固 warranty","n":[["(n.) 截止日","","電器不會附帶截止日，語意不通"],["(n.) 議程","","議程與電器無關"],["(n.) 保固","come with a one-year warranty","後面 'replace yours at no charge' 就是保固內容"],["(n.) 提案","","電器不會附帶提案，語意不通"]]},{"q":"[3]","o":["After","Unless","Although","During"],"a":0,"k":"連接詞：we receive the machine 後接 will be shipped → After","n":[["(conj.) 在…之後","After + 子句, 主要子句","先收到舊機器，之後才寄新的，時間順序"],["(conj.) 除非","","文法可以，但語意變成「沒收到舊機才寄新機」，不合理"],["(conj.) 雖然","","文法可以，但語意不通：前後沒有讓步關係"],["(prep.) 在…期間","During + N","介系詞，後面不能接 we receive 這種子句"]]}]},
{"id":"r600-07","lv":600,"p":7,"k":"memo","ti":"New travel expense policy","tx":"MEMO\n\nTo: All sales staff\nFrom: Helen Brooks, Accounting\nDate: August 25\nSubject: New travel expense policy\n\nA new policy for travel expenses will be effective on September 1. All expense reports must be submitted within ten days after your trip ends. Reports sent after this deadline will not be paid until the following month.\n\nPlease attach receipts for every expense over $20. Your supervisor must approve the report before it goes to Accounting. Meals with clients are still covered, but hotel rates may not exceed $150 per night.\n\nA summary of the policy is on the company website. If you have a specific question, call me at extension 314.","zh":"備忘錄\n\n收件人：全體業務人員\n寄件人：會計部 Helen Brooks\n日期：8 月 25 日\n主旨：新的差旅費用政策\n\n新的差旅費用政策將於 9 月 1 日生效。所有費用報告必須在出差結束後十天內提交。超過這個截止日才送出的報告，要到下個月才會付款。\n\n每一筆超過 20 美元的費用都請附上收據。報告送到會計部之前，必須先由您的主管批准。與客戶用餐的費用仍然可以報帳，但飯店費用每晚不得超過 150 美元。\n\n政策摘要已放在公司網站上。如果您有具體的問題，請撥分機 314 與我聯絡。","w":[329,286,288,384,455,260,319,450,368,474,259,379,283],"qs":[{"q":"What is the memo mainly about?","o":["Training for the accounting team","A change in sales targets","A list of hotels for business trips","New rules for reporting travel costs"],"a":3,"k":"主旨題：標題 New travel expense policy → 差旅費申報新規定","n":[["會計部的訓練","","Accounting 只是寄件單位，沒提訓練"],["業績目標的變動","","文中沒提業績目標"],["出差飯店清單","","只提飯店價格上限，沒有飯店清單"],["申報差旅費的新規定","","'new policy for travel expenses' 加上申報期限"]]},{"q":"What will happen if a report is sent in late?","o":["It must be approved by Ms. Brooks","It will be paid the following month","It will not be paid at all","The employee must pay a $20 fee"],"a":1,"k":"細節題：找 late 報告 → 'not be paid until the following month'","n":[["必須由 Brooks 女士核准","","文中 'Your supervisor must approve'，是主管"],["下個月才會付款","","文中 'not be paid until the following month'"],["完全不會付款","","文中只是延到下個月，不是不付"],["員工須付 20 美元","","$20 是需附收據的門檻，不是罰款"]]},{"q":"What is suggested about meals with clients?","o":["The company paid for them under the old policy","They will not be paid for anymore","They no longer need receipts","They are limited to $20 each"],"a":0,"k":"推論題：Meals ... are 'still covered' → 舊制就能報","n":[["舊制度下公司也付餐費","","'still covered'，still 表示以前就給付"],["不再給付","","文中說 'still covered'，仍然給付"],["不再需要收據","","文中 'every expense over $20' 都要收據，沒排除餐費"],["每餐上限 20 美元","","$20 是收據門檻；$150 才是飯店上限"]]}]},
{"id":"r600-08","lv":600,"p":7,"k":"memo","ti":"Move to the third floor","tx":"MEMO\n\nTo: Marketing Division\nFrom: Paul Chen, Office Administration\nSubject: Move to the third floor\n\nNext Friday, June 13, the marketing division will move to the third floor. The new area is more spacious and has two meeting rooms. Each employee has been assigned a desk, and the new layout is attached to this memo.\n\nPlease pack your personal items in the boxes provided by Thursday at 5:00 P.M. A moving company will carry the boxes and computers, so you do not need to move anything yourself.\n\nIf your assigned desk is not appropriate for your work, please tell me by Wednesday so that I can revise the layout.","zh":"備忘錄\n\n收件人：行銷部\n寄件人：辦公室行政組 Paul Chen\n主旨：搬到三樓\n\n下週五 6 月 13 日，行銷部將搬到三樓。新的區域比較寬敞，還有兩間會議室。每位員工都已經分配好座位，新的座位配置圖附在這份備忘錄後面。\n\n請在星期四下午 5 點前，把您的個人物品裝進公司提供的箱子裡。搬家公司會負責搬運箱子和電腦，所以您不需要自己搬任何東西。\n\n如果分配給您的座位不適合您的工作，請在星期三之前告訴我，讓我可以修改配置圖。","w":[287,318,397,449,336,334,407,463],"qs":[{"q":"What is the main purpose of the memo?","o":["To announce a new division manager","To explain plans for an office move","To ask staff to order new computers","To invite employees to a meeting"],"a":1,"k":"主旨題：'marketing division will move to the third floor'","n":[["宣布新部門主管","","文中沒提人事異動"],["說明辦公室搬遷安排","","'will move to the third floor'，並交代打包、座位"],["請員工訂購新電腦","","電腦由搬家公司搬，沒提訂購"],["邀請員工開會","","會議室只是新區域的設施，不是邀約"]]},{"q":"What must employees do by Thursday at 5:00 P.M.?","o":["Call the moving company","Choose a new desk","Pack their personal items","Carry their computers upstairs"],"a":2,"k":"細節題：找 Thursday at 5:00 → 'pack your personal items'","n":[["打給搬家公司","","文中沒要員工聯絡搬家公司"],["選新座位","","文中 'has been assigned a desk'，座位已分配"],["打包個人物品","","文中 'pack your personal items' by Thursday 5:00"],["自己把電腦搬上樓","","'moving company will carry' 箱子和電腦，不用自己搬"]]},{"q":"What is NOT mentioned about the new area?","o":["It has more space","It has two meeting rooms","It has a kitchen","It is on the third floor"],"a":2,"k":"NOT 題：逐項對照第一段 → 沒提到 kitchen","n":[["空間更大","","文中 'more spacious'，有提到"],["有兩間會議室","","文中 'has two meeting rooms'，有提到"],["有廚房","","全文沒提到 kitchen，所以是答案"],["在三樓","","文中 'move to the third floor'，有提到"]]}]},
{"id":"r600-09","lv":600,"p":6,"k":"notice","ti":"Parking Lot B closed for construction","tx":"NOTICE: Parking Lot B Closed\n\nBecause of construction work, Parking Lot B will be closed from Monday, April 7, to Friday, April 18. During this period, workers [1] ------- new lights and security cameras.\n\nEmployees who usually park in Lot B may use Lot D, which is [2] ------- to the main gate. A parking pass is not required there during these two weeks. Please note that Lot D is smaller, so spaces may fill up early. [3] -------\n\nWe thank you for your patience. If you have any concerns, please contact the facilities office at extension 410.","zh":"公告：B 停車場關閉\n\n由於施工，B 停車場將於 4 月 7 日星期一至 4 月 18 日星期五關閉。在這段期間，工人將安裝新的照明燈和監視器。\n\n平常停在 B 停車場的員工可以使用 D 停車場，它就在大門旁邊。這兩週在那裡停車不需要停車證。請注意，D 停車場比較小，車位可能很早就停滿。因此，我們建議您在上午 8 點 30 分前抵達。\n\n感謝您的耐心配合。如果您有任何疑慮，請撥分機 410 聯絡總務處。","w":[251,389,451,490,283],"qs":[{"q":"[1]","o":["will install","have installed","installed","installing"],"a":0,"k":"時態：施工期間 During this period → 未來式 will install","n":[["(未來式) 將安裝","","前句 will be closed，施工期間是未來"],["(現在完成式) 已安裝","","施工尚未開始，不能用完成式"],["(過去式) 安裝了","","日期是 April，尚未發生，時間不合"],["(V-ing) 安裝","","前面沒有 be 動詞，不能當主要動詞"]]},{"q":"[2]","o":["flexible","adjacent","essential","relevant"],"a":1,"k":"單字：Lot D ___ to the main gate → 位置 → adjacent","n":[["(adj.) 有彈性的","","文法可以，但語意不通：不能形容位置"],["(adj.) 鄰近的","be adjacent to + N","說明 Lot D 位在大門旁，to 是固定搭配"],["(adj.) 必要的","","文法可以，但語意不通：不表示位置"],["(adj.) 相關的","","文法可以，但語意不通：relevant to 是相關，非位置"]]},{"q":"[3]","o":["The new lights were installed last year.","Lot B will open again on April 7.","We therefore suggest arriving before 8:30 A.M.","Please show your receipt to the cashier."],"a":2,"k":"句子插入：前句 Lot D 較小、可能早滿 → 建議早到","n":[["新燈去年就裝好了","","與前文 workers 現在要裝新燈矛盾"],["B 停車場 4 月 7 日重新開放","","4 月 7 日是開始關閉日，不是重開日"],["因此建議 8:30 前抵達","","接 'spaces may fill up early'，therefore 順接"],["請向收銀員出示收據","","文中不需 pass，也沒提收費或收銀員"]]}]},
{"id":"r600-10","lv":600,"p":7,"k":"advertisement","ti":"Kitchen Corner summer appliance sale","tx":"Kitchen Corner Summer Appliance Sale\n\nFrom July 1 to July 15, save up to 30 percent on kitchen appliances at all Kitchen Corner outlets. Choose from a wide range of affordable ovens, coffee makers, and rice cookers.\n\nEvery purchase over $200 comes with complimentary delivery within the city. All appliances have a two-year warranty, and our technicians will install large items at no additional charge.\n\nNot sure which model is right for you? Our staff will be happy to demonstrate any product in the store. Visit us soon, because stock is limited!\n\nAll outlets are open daily from 10:00 A.M. to 9:00 P.M.","zh":"Kitchen Corner 夏季家電特賣\n\n7 月 1 日至 7 月 15 日，Kitchen Corner 所有門市的廚房家電最高可省 30%。多款價格實惠的烤箱、咖啡機和電鍋任您挑選。\n\n每筆消費超過 200 美元，即可享有市區內免費配送。所有家電都有兩年保固，大型商品由我們的技術人員安裝，不另外收費。\n\n不確定哪一款適合您嗎？我們的店員很樂意在店內為您示範任何產品。存貨有限，請盡快來店選購！\n\n所有門市每天上午 10 點至晚上 9 點營業。","w":[252,300,381,492,393,522,333,405,486,466,345],"qs":[{"q":"What is being advertised?","o":["A sale on kitchen appliances","A repair service for ovens","A cooking class","A new restaurant"],"a":0,"k":"主旨題：標題 Summer Appliance Sale → 廚房家電特賣","n":[["廚房家電特賣","","文中 'save up to 30 percent on kitchen appliances'"],["烤箱維修服務","","文中賣烤箱，沒提維修"],["烹飪課","","文中沒提到課程"],["新餐廳","","文中是賣家電的門市，不是餐廳"]]},{"q":"How can customers get free delivery?","o":["By ordering online","By buying two appliances","By spending more than $200","By shopping on July 1"],"a":2,"k":"細節題：找 delivery → 'purchase over $200 ... complimentary'","n":[["線上訂購","","文中沒提網路訂購"],["買兩件家電","","條件是金額，不是件數"],["消費超過 200 美元","","'over $200' 附 'complimentary delivery'，即免運"],["7 月 1 日購物","","活動 July 1 to July 15，非限定首日"]]},{"q":"What is NOT offered by Kitchen Corner?","o":["Product demonstrations in the store","A monthly payment plan","A two-year warranty","Installation of large items"],"a":1,"k":"NOT 題：另三項在文中都有 → 找沒提到的分期付款","n":[["店內產品示範","","'staff will be happy to demonstrate'，有提到"],["每月分期付款","","全文沒提到分期付款，所以是答案"],["兩年保固","","'a two-year warranty'，有提到"],["大型商品安裝","","文中 'install large items'，有提到"]]}]},
{"id":"r600-11","lv":600,"p":7,"k":"advertisement","ti":"Now hiring: store assistants at Sunny Mart","tx":"Now Hiring: Store Assistants at Sunny Mart\n\nSunny Mart, a growing retail company, is looking for store assistants for its new outlet on Pine Street. The position involves helping customers, putting merchandise on the shelves, and using the cash register.\n\nInexperienced candidates are welcome because we provide one week of paid training. Work hours are flexible, with morning, evening, and weekend shifts available. Employees also receive a 15 percent discount on all purchases.\n\nTo apply, please submit your résumé on our website. The deadline is April 30, and interviews will begin the following week.","zh":"徵才：Sunny Mart 門市助理\n\nSunny Mart 是一家成長中的零售公司，正在為位於 Pine Street 的新門市招募門市助理。這份工作的內容包括協助顧客、把商品上架，以及操作收銀機。\n\n歡迎沒有經驗的求職者，因為我們會提供一週的有薪訓練。工作時間有彈性，有早班、晚班和週末班可以選擇。員工購買任何商品還可享有 85 折優惠。\n\n如要應徵，請在我們的網站上提交履歷。截止日是 4 月 30 日，面試將在隔週開始。","w":[364,300,338,429,331,494,388,315,382,369,492,455,291,260],"qs":[{"q":"What is the purpose of the advertisement?","o":["To find new workers for a store","To advertise a training school","To announce a store sale","To introduce a new product"],"a":0,"k":"主旨題：標題 Now Hiring → 為新門市徵人","n":[["為門市徵求新員工","","'Now Hiring' 和 'looking for store assistants'"],["宣傳訓練學校","","訓練是公司提供的一週訓練，不是學校廣告"],["宣布門市特賣","","15% 折扣是員工福利，不是特賣"],["介紹新產品","","文中沒有介紹產品"]]},{"q":"What do Sunny Mart employees receive?","o":["Free meals during shifts","Two weeks of paid training","A free uniform","A discount on things they buy"],"a":3,"k":"細節題：找 employees receive → '15 percent discount'","n":[["上班期間免費餐點","","文中沒提到餐點"],["兩週有薪訓練","","文中是 'one week of paid training'，不是兩週"],["免費制服","","文中沒提到制服"],["購物折扣","","文中 '15 percent discount on all purchases'"]]},{"q":"What is suggested about the position?","o":["It requires working every weekend","It lasts for only one week","It is at the company's head office","Past work experience is not necessary"],"a":3,"k":"推論題：'Inexperienced candidates are welcome' → 不需經驗","n":[["每個週末都要上班","","文中 'flexible'，班別有早、晚、週末可選"],["只持續一週","","one week 指訓練期，不是工作期間"],["在公司總部","","文中是 'new outlet on Pine Street'"],["不需要過去的工作經驗","","文中 'Inexperienced candidates are welcome'"]]}]},
{"id":"r600-12","lv":600,"p":6,"k":"memo","ti":"Training for new software","tx":"MEMO\n\nTo: All employees\nFrom: Sandra Lopez, Human Resources\nSubject: Training for new software\n\nNext month, the company will begin using new software to manage work hours and pay. To help everyone learn the system, an [1] ------- from the software company will teach two training sessions: one on Tuesday, May 6, and one on Thursday, May 8.\n\nEach session will last [2] ------- two hours and will be held in Meeting Room 3. You only need to attend one of them. Please [3] ------- on the company website by April 30 so that we can prepare enough seats.\n\nIf neither date is possible for you, please speak to your supervisor.","zh":"備忘錄\n\n收件人：全體員工\n寄件人：人力資源部 Sandra Lopez\n主旨：新軟體訓練\n\n下個月起，公司將開始使用新軟體來管理工時和薪資。為了幫助大家學會這套系統，軟體公司的一位講師會來上兩場訓練課程：一場在 5 月 6 日星期二，另一場在 5 月 8 日星期四。\n\n每場課程大約兩小時，地點在第 3 會議室。您只需要參加其中一場。請在 4 月 30 日前到公司網站報名，好讓我們準備足夠的座位。\n\n如果這兩個日期您都無法參加，請告訴您的主管。","w":[267,320,420,494,319],"qs":[{"q":"[1]","o":["instructive","instructor","instruction","instruct"],"a":1,"k":"詞性：冠詞 an 後接名詞，且是教課的「人」→ instructor","n":[["(adj.) 有教育意義的","","形容詞，後面沒有名詞可修飾"],["(n.) 講師","an instructor from + 公司","an 後接名詞，且是 teach 的人"],["(n.) 指示、教學","","是名詞，但不是人，不能 teach sessions"],["(v.) 指導","","動詞，冠詞 an 後不能接動詞"]]},{"q":"[2]","o":["approximately","particularly","immediately","frequently"],"a":0,"k":"單字：放在數字 two hours 前 → 大約 approximately","n":[["(adv.) 大約","approximately + 數字","放在數字前表示約略，'approximately two hours'"],["(adv.) 特別地","","文法可以，但語意不通：不能修飾時間長度"],["(adv.) 立刻","","文法可以，但語意不通：與時間長度無關"],["(adv.) 經常","","文法可以，但語意不通：表頻率，不修飾數字"]]},{"q":"[3]","o":["hesitate","register","commute","operate"],"a":1,"k":"單字：Please ___ on the website, 好準備座位 → 報名","n":[["(v.) 猶豫","","'Please hesitate' 語意相反，不合"],["(v.) 報名、登記","register on + 網站","報名後才能 'prepare enough seats'"],["(v.) 通勤","","通勤不會在網站上進行"],["(v.) 操作、運作","","語意不通：與準備座位無關"]]}]},
{"id":"r600-13","lv":600,"p":7,"k":"message","ti":"Presentation moved to 2:00","tx":"Maria Santos (9:12 A.M.): Hi, Tom. My train is delayed because of a problem on the line. I won't reach the office until about 10:30.\n\nTom Becker (9:14 A.M.): Thanks for telling me. Our presentation to Mr. Hill is at 10:00, isn't it?\n\nMaria Santos (9:15 A.M.): Yes. Could you ask him to postpone it until 11:00? The slides are on my laptop.\n\nTom Becker (9:21 A.M.): I just called him. He has another meeting at 11:00, but he is free at 2:00 this afternoon.\n\nMaria Santos (9:22 A.M.): Perfect. Please reschedule it for 2:00 and book Conference Room B.\n\nTom Becker (9:24 A.M.): Done. I'll also forward the new agenda to the team.","zh":"Maria Santos（上午 9:12）：嗨，Tom。因為路線出了問題，我的火車誤點了。我大概要到 10:30 才會到辦公室。\n\nTom Becker（上午 9:14）：謝謝妳告訴我。我們對 Hill 先生的簡報是 10 點，對吧？\n\nMaria Santos（上午 9:15）：對。你可以請他延到 11 點嗎？投影片在我的筆電裡。\n\nTom Becker（上午 9:21）：我剛剛打給他了。他 11 點有另一個會議，但今天下午 2 點有空。\n\nMaria Santos（上午 9:22）：太好了。請把簡報改到 2 點，並預訂 B 會議室。\n\nTom Becker（上午 9:24）：辦好了。我也會把新的議程轉寄給團隊。","w":[322,423,424,262,432,348],"qs":[{"q":"Why does Ms. Santos contact Mr. Becker?","o":["To borrow his laptop","To say she will arrive late","To ask for a ride to the office","To cancel a presentation"],"a":1,"k":"細節題：第一則訊息 → 'My train is delayed' 要晚到","n":[["借他的筆電","","'slides are on my laptop'，是她自己的筆電"],["告知她會晚到","","文中 'won't reach the office until about 10:30'"],["請他載去公司","","文中她搭火車，沒要求接送"],["取消簡報","","她只是請他延後，不是取消"]]},{"q":"When will the presentation take place?","o":["At 2:00 P.M.","At 10:30 A.M.","At 10:00 A.M.","At 11:00 A.M."],"a":0,"k":"細節題：找最後敲定時間 → 'reschedule it for 2:00'","n":[["下午 2 點","","'Please reschedule it for 2:00'，Hill 先生 2:00 有空"],["上午 10:30","","那是她到辦公室的時間"],["上午 10:00","","那是原訂時間，後來改了"],["上午 11:00","","Hill 先生 'another meeting at 11:00'"]]},{"q":"At 9:24 A.M., what does Mr. Becker mean when he writes, \"Done\"?","o":["He has finished making the slides","He has arrived at the office","He has done what Ms. Santos asked","He does not want to talk anymore"],"a":2,"k":"語意題：Done 回應前一句的請求 → 已照辦","n":[["他做完投影片了","","投影片在 Santos 的筆電，不是他做的"],["他已到辦公室","","Done 回應的是改時間與訂會議室"],["他已完成 Santos 的請求","","她要求 'reschedule ... and book Conference Room B'"],["他不想再聊","","後面還說 'I'll also forward the new agenda'"]]}]},
{"id":"r600-14","lv":600,"p":7,"k":"message","ti":"Photocopier problem on the fourth floor","tx":"Jenny Wang (1:05 P.M.): Hi, Mark. The photocopier on the fourth floor has malfunctioned again. Paper keeps getting stuck inside.\n\nMark Davis (1:07 P.M.): Oh no. I need 50 copies of the sales summary for the 3:00 meeting.\n\nJenny Wang (1:08 P.M.): I already called the maintenance company. A technician will come tomorrow morning.\n\nMark Davis (1:10 P.M.): That's too late for me. Is there another machine I can use?\n\nJenny Wang (1:11 P.M.): The accounting division on the second floor has one. Just ask Ms. Ito for permission first.\n\nMark Davis (1:12 P.M.): Great. I'll go down there right now. Thanks!","zh":"Jenny Wang（下午 1:05）：嗨，Mark。四樓的影印機又故障了，紙一直卡在裡面。\n\nMark Davis（下午 1:07）：糟糕。我需要印 50 份業績摘要，3 點開會要用。\n\nJenny Wang（下午 1:08）：我已經打電話給維修公司了。技術人員明天早上會來。\n\nMark Davis（下午 1:10）：那對我來說太晚了。有其他機器可以用嗎？\n\nJenny Wang（下午 1:11）：二樓的會計部有一台。只是要先徵求 Ito 小姐的同意。\n\nMark Davis（下午 1:12）：太好了，我現在就下去。謝謝！","w":[277,499,259,292,333,329,287],"qs":[{"q":"What problem are the writers discussing?","o":["A meeting has been canceled","A technician arrived late","A report contains mistakes","A machine is not working properly"],"a":3,"k":"主旨題：'photocopier ... has malfunctioned again'","n":[["會議被取消","","3:00 meeting 沒被取消"],["技術人員遲到","","技術人員 'will come tomorrow'，還沒來"],["報告有錯誤","","文中沒提報告有錯"],["機器運作不正常","","photocopier 'has malfunctioned'，紙一直卡住"]]},{"q":"When will the technician come?","o":["Tomorrow morning","In one hour","At 3:00 P.M. today","Tomorrow afternoon"],"a":0,"k":"細節題：找 technician → 'will come tomorrow morning'","n":[["明天早上","","文中 'A technician will come tomorrow morning'"],["一小時後","","文中沒說一小時後"],["今天下午 3 點","","3:00 是 Davis 先生的會議時間"],["明天下午","","文中是 morning，不是 afternoon"]]},{"q":"What will Mr. Davis most likely do next?","o":["Call the maintenance company","Wait for the technician","Cancel the 3:00 meeting","Go to the second floor"],"a":3,"k":"推論題：'The accounting division on the second floor has one'","n":[["打給維修公司","","'I already called'，是 Wang 小姐已打過"],["等技術人員","","他說 'too late for me'，不會等"],["取消 3:00 會議","","他要去借機器影印，不是取消會議"],["去二樓","","文中 'I'll go down there right now'"]]}]},
{"id":"r600-15","lv":600,"p":6,"k":"advertisement","ti":"Business English at Summit Language Center","tx":"Improve Your Business English at Summit Language Center!\n\nDo you need better English for your career? Summit Language Center offers evening and weekend courses for busy professionals. Our class times are [1] -------, so you can study around your work schedule.\n\nAll courses are taught by experienced instructors in small groups of eight students or fewer. Students who complete a twelve-week course [2] ------- an official certificate.\n\nOur prices are affordable, and new students can try one lesson for free. To [3] -------, visit our website or call us before the next term begins on March 3.","zh":"到 Summit Language Center 提升您的商務英語！\n\n您的職涯需要更好的英語能力嗎？Summit Language Center 為忙碌的專業人士提供晚間和週末課程。我們的上課時間很有彈性，您可以配合自己的工作時間來學習。\n\n所有課程都由經驗豐富的講師以八人以下的小班方式授課。完成十二週課程的學員會拿到一張正式的證書。\n\n我們的價格實惠，新學員還可以免費試上一堂課。如要註冊，請在 3 月 3 日下一期開課前上我們的網站或來電。","w":[415,382,267,256,381,427,297],"qs":[{"q":"[1]","o":["medical","domestic","anonymous","flexible"],"a":3,"k":"單字：配合工作時間來上課 → 時段有彈性 flexible","n":[["(adj.) 醫療的","","文法可以，但語意不通：與上課時間無關"],["(adj.) 國內的","","文法可以，但語意不通：不能形容上課時間"],["(adj.) 匿名的","","文法可以，但語意不通：時間不會匿名"],["(adj.) 有彈性的","flexible hours / schedule","後句 'study around your work schedule'"]]},{"q":"[2]","o":["to receive","receives","receive","receiving"],"a":2,"k":"時態／語態：複數主詞 Students → 複數動詞 receive","n":[["(不定詞) 收到","","不定詞不能當主要動詞"],["(v.) 收到（第三人稱單數）","","主詞 Students 是複數，不能加 s"],["(v.) 收到（複數）","Students who ... receive + N","who 子句是修飾語，主詞 Students 為複數"],["(V-ing) 收到","","沒有 be 動詞，不能當主要動詞"]]},{"q":"[3]","o":["enroll","occur","shrink","commute"],"a":0,"k":"單字：To ___, visit our website or call → 報名 enroll","n":[["(v.) 報名、註冊","To enroll, visit / call ...","後面說上網站或打電話，是報名方式"],["(v.) 發生","","文法可以，但語意不通：occur 是「發生」，不是報名"],["(v.) 縮小","","文法可以，但語意不通：與報名無關"],["(v.) 通勤","","文法可以，但語意不通：不是上網能做的事"]]}]},
{"id":"r600-16","lv":600,"p":7,"k":"article","ti":"New express bus to serve Riverside commuters","tx":"New Express Bus to Serve Riverside Commuters\n\nRIVERSIDE — The city's transportation office announced on Monday that a new express bus will begin service on September 2. The bus will run between Riverside Station and the downtown business district, with only three stops along the way.\n\nOfficials predict that the trip will take approximately 25 minutes, about half the time of the current route. The fare will be $2.50, the same as on regular buses.\n\n\"Many people in our community commute downtown every day,\" said office director Laura Kim. \"We hope this service will persuade more of them to leave their cars at home.\"","zh":"新快捷公車將服務 Riverside 通勤族\n\n【Riverside 訊】市政府交通局星期一宣布，新的快捷公車將於 9 月 2 日開始營運。這班公車行駛於 Riverside 車站和市中心商業區之間，沿途只停靠三站。\n\n官員預測車程大約 25 分鐘，約為現有路線所需時間的一半。票價為 2.5 美元，和一般公車相同。\n\n交通局局長 Laura Kim 表示：「我們社區有很多人每天通勤到市中心。希望這項服務能說服更多人把車子留在家裡。」","w":[343,279,426,420,378,271,428,441],"qs":[{"q":"What is the article mainly about?","o":["The closing of a train station","A new parking area downtown","An increase in bus fares","A new bus service"],"a":3,"k":"主旨題：'new express bus will begin service' → 新公車服務","n":[["火車站關閉","","Riverside Station 只是公車起點，沒說關閉"],["市中心新停車區","","文中沒提新停車場"],["公車票價上漲","","文中 'same as on regular buses'，票價沒變"],["新的公車服務","","文中 'new express bus will begin service'"]]},{"q":"About how long does the current route take?","o":["12 minutes","25 minutes","75 minutes","50 minutes"],"a":3,"k":"細節題＋計算：新車 25 分鐘 'about half' → 現有約 50 分鐘","n":[["12 分鐘","","那是 25 分鐘的一半，把倍數看反了"],["25 分鐘","","那是新快速公車的車程"],["75 分鐘","","文中沒有這個數字，也不符合 half"],["50 分鐘","","新車 25 分鐘是 'about half the time'，所以現有約 50"]]},{"q":"What does Ms. Kim hope the new bus will do?","o":["Get more people to travel without their cars","Lower the price of parking","Create jobs for bus drivers","Bring more tourists to Riverside"],"a":0,"k":"細節題：找 Ms. Kim 的話 → 'persuade ... leave their cars at home'","n":[["讓更多人不開車出行","","文中 'persuade ... to leave their cars at home'"],["降低停車費","","文中沒提停車費"],["為公車司機創造工作","","文中沒提司機職缺"],["吸引更多觀光客到 Riverside","","文中談的是通勤族，沒提觀光客"]]}]},
{"id":"r600-17","lv":600,"p":7,"k":"article","ti":"Harlow Foods to build new plant in Easton","tx":"Harlow Foods to Build New Plant in Easton\n\nEASTON — Harlow Foods, a firm known for its frozen meals, plans to build a new plant in Easton. Construction will begin in March and is expected to take about one year.\n\nThe company will invest $20 million in the project and employ approximately 300 local workers when the plant opens. \"Demand for our products has grown every quarter,\" said company president Rosa Diaz. \"We need more space to keep up.\"\n\nCity leaders welcomed the news. They believe the plant will have a positive impact on the local economy, particularly on small shops and restaurants near the site.","zh":"Harlow Foods 將在 Easton 興建新工廠\n\n【Easton 訊】以冷凍餐點聞名的 Harlow Foods 公司，計劃在 Easton 興建一座新工廠。工程將於三月動工，預計需要大約一年。\n\n該公司將在這項計畫中投資 2,000 萬美元，工廠啟用時將雇用大約 300 名當地員工。公司總裁 Rosa Diaz 表示：「我們產品的需求每一季都在成長。我們需要更多空間才能跟上。」\n\n市府官員對這個消息表示歡迎。他們相信這座工廠會對當地經濟帶來正面影響，尤其是工廠附近的小商店和餐廳。","w":[305,299,251,464,447,420,344,375,328,419],"qs":[{"q":"What is the article mainly about?","o":["A food company's new building project","A change of company president","A drop in sales of frozen meals","A new restaurant opening in Easton"],"a":0,"k":"主旨題：'plans to build a new plant' → 公司蓋新廠","n":[["食品公司的新建工程","","文中 'plans to build a new plant'，是蓋新廠"],["更換公司總裁","","Diaz 只是受訪的總裁，沒提換人"],["冷凍餐銷售下滑","","文中 'Demand ... has grown every quarter'，是成長"],["Easton 新餐廳開幕","","文中是蓋工廠，餐廳只是受惠對象"]]},{"q":"According to Ms. Diaz, why does the company need the new plant?","o":["Workers asked for a new site","Costs are lower in Easton","Demand for its products keeps growing","Its old plant was damaged"],"a":2,"k":"細節題：找 Ms. Diaz 的話 → 'Demand ... has grown'","n":[["員工要求新廠址","","文中沒提員工要求"],["Easton 成本較低","","文中沒比較成本"],["產品需求持續成長","","文中 'Demand ... has grown'，需要更多空間"],["舊廠受損","","文中沒提舊廠受損"]]},{"q":"The word \"plant\" in the passage is closest in meaning to","o":["market","office","factory","flower"],"a":2,"k":"字義題：'build a new plant' 雇 300 人 → 工廠 factory","n":[["(n.) 市場","","build a market 文法可以，但做冷凍餐要蓋的是工廠"],["(n.) 辦公室","","公司做冷凍餐，需要生產設施，不是辦公室"],["(n.) 工廠","","'plant' 在此指生產冷凍餐的工廠"],["(n.) 花","","plant 另有植物義，但這裡是工廠"]]}]},
{"id":"r600-18","lv":600,"p":6,"k":"letter","ti":"Thank you for your donation","tx":"Riverton Youth Sports Club\n12 Park Road\n\nJune 20\n\nDear Mr. Walker,\n\nOn behalf of the Riverton Youth Sports Club, I would like to express our [1] ------- for your kind donation of $2,000. Your company has sponsored our summer program for three years, and your support makes a real difference in our community.\n\nLast month, the money [2] ------- to buy new soccer balls and uniforms for more than 60 children. We have enclosed some photos from our first practice.\n\nWe would be pleased if you could join us at our closing ceremony on August 15. [3] -------\n\nSincerely,\nAngela Price\nClub Director","zh":"Riverton Youth Sports Club\n12 Park Road\n\n6 月 20 日\n\nWalker 先生您好：\n\n我謹代表 Riverton Youth Sports Club，對您善心捐贈的 2,000 美元表達我們的感謝。貴公司已經贊助我們的夏季活動三年了，您的支持為我們的社區帶來了實質的改變。\n\n上個月，這筆錢被用來為 60 多名孩子購買新的足球和制服。隨信附上幾張我們第一次練習時的照片。\n\n如果您能來參加我們 8 月 15 日的閉幕典禮，我們會非常高興。正式的邀請函將在下個月寄給您。\n\n社長\nAngela Price 敬上","w":[330,268,498,271,273],"qs":[{"q":"[1]","o":["appreciated","appreciation","appreciative","appreciate"],"a":1,"k":"詞性：所有格 our 後接名詞 → appreciation","n":[["(v. 過去式／p.p.) 感激了；受重視的","","appreciated 是分詞，our 後缺名詞當 express 的受詞"],["(n.) 感謝","express our appreciation for + N","our 後接名詞，作 express 的受詞"],["(adj.) 感激的","","形容詞，our 後面要接名詞"],["(v.) 感激","","動詞，our 後面不能接動詞原形"]]},{"q":"[2]","o":["has used","is using","was used","uses"],"a":2,"k":"時態／語態：Last month + 錢被用來買 → 被動 was used","n":[["(完成式) 已使用","","主動式，錢不會自己用東西；Last month 也不配完成式"],["(進行式) 正在使用","","主動式，且與 Last month 時態不合"],["(被動過去式) 被用來","be used to + V","錢是被使用；Last month 用過去式"],["(現在式) 使用","","主動式，且與 Last month 時態不合"]]},{"q":"[3]","o":["Your application for the position has been received.","A formal invitation will be mailed to you next month.","The program was canceled because of low interest.","Please pay the balance by the end of the week."],"a":1,"k":"句子插入：前句邀請參加 August 15 典禮 → 後續邀請函","n":[["已收到您的職位申請","","Walker 是贊助人，不是求職者"],["正式邀請函下個月寄出","","承接前句邀請，補充邀請函的寄送"],["活動因興趣低而取消","","文中活動正常進行，且 closing ceremony 將舉行"],["請在本週結束前付清餘額","","這是感謝函，沒有任何款項待付"]]}]},
{"id":"r600-19","lv":600,"p":7,"k":"letter","ti":"A change to your savings account","tx":"Harbor Bank\n45 Dock Street\n\nMarch 3\n\nDear Mr. Tanaka,\n\nThank you for being a customer of Harbor Bank. I am writing regarding your savings account.\n\nBeginning April 1, the interest rate on your account will rise from 1.2 percent to 1.5 percent. To receive the new rate, you must maintain a balance of at least $1,000. If your balance falls below this amount, the current rate will apply.\n\nYou do not need to do anything to accept this change. Your monthly statement will show the new rate starting in April. As always, you may withdraw or deposit money at any time without a charge.\n\nSincerely,\nEmily Stone\nCustomer Service Manager","zh":"Harbor Bank\n45 Dock Street\n\n3 月 3 日\n\nTanaka 先生您好：\n\n感謝您成為 Harbor Bank 的客戶。這封信是關於您的儲蓄帳戶。\n\n自 4 月 1 日起，您帳戶的利率將從 1.2% 調升為 1.5%。若要享有新利率，您的帳戶餘額必須維持在至少 1,000 美元。如果餘額低於這個金額，將適用目前的利率。\n\n您不需要做任何事就能接受這項變更。從四月開始，您每月的對帳單上會顯示新利率。和以往一樣，您可以隨時提款或存款，不收任何費用。\n\n客戶服務經理\nEmily Stone 敬上","w":[250,270,368,446,258,378,337,469,373,486],"qs":[{"q":"What is the purpose of the letter?","o":["To tell a customer about a higher interest rate","To report a problem with an account","To announce a new bank fee","To ask a customer to open an account"],"a":0,"k":"主旨題：'interest rate ... will rise from 1.2 percent'","n":[["告知客戶利率調高","","文中 'will rise ... to 1.5 percent'，利率調升"],["通報帳戶問題","","文中沒提帳戶有問題"],["宣布新手續費","","文中 'without a charge'，存提款不收費"],["請客戶開戶","","他已有帳戶，信中談的是 'your savings account'"]]},{"q":"What must Mr. Tanaka do to receive the new rate?","o":["Have at least $1,000 in his account","Sign and return a form","Open a second savings account","Visit the bank before April 1"],"a":0,"k":"細節題：找 To receive the new rate → 'balance of at least $1,000'","n":[["帳戶至少有 1,000 美元","","文中 'maintain a balance of at least $1,000'"],["簽名並寄回表格","","文中 'do not need to do anything'"],["再開第二個儲蓄帳戶","","文中沒有這個條件"],["4 月 1 日前到銀行","","文中說不需要採取任何動作"]]},{"q":"The word \"regarding\" in the passage is closest in meaning to","o":["about","without","against","after"],"a":0,"k":"字義題：'writing regarding your account' → 關於 about","n":[["(prep.) 關於","regarding = about / concerning","'writing regarding your account' = 關於帳戶"],["(prep.) 沒有","","'without your account' 語意不通"],["(prep.) 反對","","信中沒有反對帳戶的意思"],["(prep.) 在…之後","","'after your account' 語意不通"]]}]},
{"id":"r600-20","lv":600,"p":7,"k":"letter","ti":"Your lease for Apartment 5C","tx":"Greenfield Apartments\nManagement Office\n\nNovember 10\n\nDear Ms. Novak,\n\nYour lease for Apartment 5C will end on December 31. We would be happy to have you stay as our tenant. If you wish to extend your lease for another year, please sign the attached contract and return it to our office by December 1.\n\nThe monthly rent will remain $900. However, starting in January, utilities will no longer be included, so tenants will pay for their own water and electricity. Your current deposit will be kept for the new term, and no additional payment is required now.\n\nPlease call me if you have any concerns.\n\nSincerely,\nRobert Hayes\nProperty Manager","zh":"Greenfield Apartments\n管理室\n\n11 月 10 日\n\nNovak 小姐您好：\n\n您 5C 公寓的租約將於 12 月 31 日到期。我們很樂意您繼續當我們的房客。如果您想把租約再延長一年，請在隨信附上的合約上簽名，並在 12 月 1 日前交回我們的辦公室。\n\n每月租金維持 900 美元不變。不過，從一月開始，租金將不再包含水電費，所以房客要自行支付水費和電費。您目前的押金會保留到新的租期，現在不需要另外付款。\n\n如果您有任何疑慮，請打電話給我。\n\n物業經理\nRobert Hayes 敬上","w":[495,339,435,367,346,378,373,297,405,490],"qs":[{"q":"Why did Mr. Hayes write to Ms. Novak?","o":["To return her deposit","To announce a rent increase","To invite her to extend her lease","To ask her to move out"],"a":2,"k":"主旨題：'If you wish to extend your lease' → 邀請續約","n":[["退還她的押金","","文中 'deposit will be kept'，押金保留"],["宣布租金調漲","","文中 'rent will remain $900'，租金不變"],["邀請她續約","","文中 'extend your lease'，並請簽附上的合約"],["要求她搬走","","文中 'happy to have you stay'，歡迎她繼續住"]]},{"q":"What will change in January?","o":["Tenants will pay for water and electricity","The rent will go up","The management office will move","A new deposit will be required"],"a":0,"k":"細節題：找 starting in January → utilities no longer included","n":[["房客要自付水電","","文中 'utilities will no longer be included'，一月起"],["租金會漲","","文中 'will remain $900'"],["管理處會搬家","","文中沒提管理處搬遷"],["需要新的押金","","文中 'no additional payment is required'，不用額外付款"]]},{"q":"The word \"term\" in the passage is closest in meaning to","o":["price","period","rule","word"],"a":1,"k":"字義題：'the new term' 指新的租約期間 → period","n":[["(n.) 價格","","租金已寫 rent，term 是租期"],["(n.) 期間","","'new term' = 新的租期，與 'another year' 呼應"],["(n.) 規則","","'new rule' 與續約一年的語境不合"],["(n.) 字詞","","term 有術語義，但這裡指租期"]]}]},
{"id":"r600-21","lv":600,"p":6,"k":"announcement","ti":"Bella Home opens its third outlet","tx":"Grand Opening: Bella Home Opens Its Third Outlet\n\nBella Home is pleased to announce the opening of its newest outlet in the Westgate Shopping Center on Saturday, November 8. The store will [1] ------- furniture, kitchen goods, and a wide selection of home decorations.\n\nTo celebrate, the first 100 customers will receive a [2] ------- gift bag. In addition, all merchandise will be 20 percent off during the opening weekend.\n\nThe new store is easily [3] ------- by bus and subway, and free parking is available for shoppers. Store hours are 10:00 A.M. to 9:00 P.M. every day. We hope to see you there!","zh":"盛大開幕：Bella Home 第三家門市開張\n\nBella Home 很高興宣布，位於 Westgate Shopping Center 的最新門市將於 11 月 8 日星期六開幕。這家店主打家具、廚房用品，以及種類豐富的居家裝飾品。\n\n為了慶祝開幕，前 100 位顧客將獲得一個免費的禮物袋。此外，開幕週末期間全店商品一律八折。\n\n新門市搭公車和地鐵都很容易到達，也為購物的顧客提供免費停車位。營業時間為每天上午 10 點至晚上 9 點。期待您的光臨！","w":[300,496,393,331,404],"qs":[{"q":"[1]","o":["postpone","feature","persuade","predict"],"a":1,"k":"單字：The store will ___ furniture, kitchen goods → 主打 feature","n":[["(v.) 延後","","文法可以，但語意不通：不能延後家具"],["(v.) 以…為特色、主打","The store will feature + 商品","店面主打家具、廚房用品等商品"],["(v.) 說服","","persuade 要接人，不能接家具，語意不通"],["(v.) 預測","","文法可以，但語意不通：店不會預測商品"]]},{"q":"[2]","o":["punctual","verbal","cautious","complimentary"],"a":3,"k":"單字：前 100 名顧客收到 ___ gift bag → 免費的 complimentary","n":[["(adj.) 準時的","","文法可以，但語意不通：禮物袋不會準時"],["(adj.) 口頭的","","文法可以，但語意不通：禮物袋不是口頭的"],["(adj.) 謹慎的","","文法可以，但語意不通：不能形容禮物袋"],["(adj.) 免費贈送的","complimentary gift / drink / delivery","慶祝開幕贈送給前 100 位顧客，免費"]]},{"q":"[3]","o":["access","accessible","accessibility","accessibly"],"a":1,"k":"詞性：is easily ___ 副詞後接形容詞 → accessible","n":[["(n./v.) 進入、取得","","is easily 後要形容詞，access 不是形容詞"],["(adj.) 容易到達的","be accessible by bus","is 後接形容詞，easily 修飾它"],["(n.) 可及性","","名詞，且 easily 是副詞，不能修飾名詞"],["(adv.) 容易到達地","","副詞，is 後面缺形容詞作補語"]]}]},
{"id":"r600-22","lv":600,"p":7,"k":"announcement","ti":"Employee of the Year award ceremony","tx":"Employee of the Year Award Ceremony\n\nWestbrook Electronics is pleased to announce that this year's award ceremony will be held on Friday, December 12, at 6:00 P.M. in the Grand Hall of the Parkside Hotel.\n\nThe committee has nominated three employees for their excellent performance. The winner will receive a $1,000 prize and two additional days of paid vacation. A reception with food and drinks will follow the ceremony.\n\nAll employees are invited. To help us plan, please register on the company website by December 5. Transportation from the office to the hotel will be provided at 5:15 P.M.","zh":"年度最佳員工頒獎典禮\n\nWestbrook Electronics 很高興宣布，今年的頒獎典禮將於 12 月 12 日星期五下午 6 點，在 Parkside Hotel 的 Grand Hall 舉行。\n\n委員會已提名三位表現優異的員工。得獎者將獲得 1,000 美元獎金，以及額外兩天的有薪假。典禮結束後會有提供餐點和飲料的招待會。\n\n歡迎所有員工參加。為了方便我們安排，請在 12 月 5 日前到公司網站報名。下午 5 點 15 分將提供從辦公室到飯店的交通接送。","w":[273,298,481,263,405,325,494,279],"qs":[{"q":"What event is being announced?","o":["A retirement party","A company award ceremony","A staff training day","A hotel opening"],"a":1,"k":"主旨題：'award ceremony will be held on Friday, December 12'","n":[["退休歡送會","","文中是頒獎典禮，沒提退休"],["公司頒獎典禮","","文中 'award ceremony will be held'，主辦是 Westbrook"],["員工訓練日","","文中沒提訓練"],["飯店開幕","","Parkside Hotel 只是活動地點"]]},{"q":"What will the winner receive?","o":["A free hotel stay","Dinner for two","Money and extra vacation days","A promotion to manager"],"a":2,"k":"細節題：找 winner will receive → $1,000 + 兩天有薪假","n":[["免費住宿","","文中飯店只是舉辦典禮的地點，不是獎品"],["雙人晚餐","","文中沒提雙人晚餐"],["獎金和額外假期","","文中 'a $1,000 prize' 加兩天有薪假"],["升為經理","","文中沒提升職"]]},{"q":"What is NOT mentioned in the announcement?","o":["The names of the nominated employees","The way employees can get to the hotel","The place where the event will be held","The deadline for signing up"],"a":0,"k":"NOT 題：另三項都有寫 → 沒寫提名者姓名","n":[["被提名員工的姓名","","只說 'three employees'，沒寫姓名，所以是答案"],["員工前往飯店的方式","","文中 'Transportation ... will be provided'，有提到"],["活動舉辦的地點","","文中 'Grand Hall of the Parkside Hotel'，有提到"],["報名截止日","","文中 'register ... by December 5'，有提到"]]}]},
{"id":"r600-23","lv":600,"p":7,"k":"announcement","ti":"Book donation week at Oakdale Shopping Center","tx":"Help Us Support the Oakdale Community Library\n\nOakdale Shopping Center will host a book donation event from May 5 to May 11. We invite everyone in the community to donate used books in good condition. All books will go to the Oakdale Community Library, which is opening a new reading room for children.\n\nDonation boxes will be located near the main entrance and beside the food court. Every person who contributes five or more books will receive a complimentary drink ticket as a sign of our appreciation.\n\nThe event is sponsored by Page One Bookstore. For details, please visit the information desk on the first floor.","zh":"一起支持 Oakdale 社區圖書館\n\nOakdale Shopping Center 將於 5 月 5 日至 5 月 11 日舉辦捐書活動。我們邀請社區的每一位朋友捐出狀況良好的二手書。所有書籍都會送到 Oakdale 社區圖書館，圖書館即將啟用一間新的兒童閱覽室。\n\n捐書箱將設在正門附近和美食街旁邊。每位捐出五本以上書籍的民眾，都可以得到一張免費飲料券，以表達我們的感謝。\n\n本活動由 Page One Bookstore 贊助。詳情請洽一樓的服務台。","w":[271,363,268,431,465,434,393,330,498],"qs":[{"q":"What is the purpose of the announcement?","o":["To advertise a bookstore sale","To invite people to a food festival","To announce new library hours","To ask people to give books"],"a":3,"k":"主旨題：'We invite everyone ... to donate used books'","n":[["宣傳書店特賣","","Page One 只是贊助商，沒提特賣"],["邀請參加美食節","","food court 只是捐書箱的位置"],["宣布圖書館新開放時間","","文中沒提開放時間，圖書館只是受贈單位"],["請大家捐書","","文中 'invite everyone ... to donate used books'"]]},{"q":"Where can people leave their books?","o":["Near the main entrance","At the community library","At Page One Bookstore","At the information desk"],"a":0,"k":"細節題：找 boxes 位置 → 'near the main entrance'","n":[["正門附近","","文中 'Donation boxes ... near the main entrance'"],["社區圖書館","","書最後送到圖書館，但不在那裡收"],["Page One 書店","","書店只是活動贊助商，不是收書地點"],["服務台","","服務台是詢問詳情的地方，不是收書處"]]},{"q":"The word \"host\" in the passage is closest in meaning to","o":["watch","attend","cancel","hold"],"a":3,"k":"字義題：'will host a ... event' 舉辦活動 → hold","n":[["(v.) 觀看","","購物中心是主辦方，不是觀看活動"],["(v.) 參加","","host 是主辦，attend 是出席，語意不同"],["(v.) 取消","","文中是要舉辦活動，不是取消"],["(v.) 舉行","host / hold an event","'will host a ... event' = 舉辦，同 hold"]]}]},
{"id":"r600-24","lv":600,"p":6,"k":"article","ti":"Norvale Motors reports strong third quarter","tx":"Norvale Motors Reports Strong Third Quarter\n\nNorvale Motors announced on Tuesday that its profit for the third quarter rose 12 percent compared with the same period last year. The result [1] ------- the company's own forecast of 8 percent.\n\nCompany president Alan Pierce said that sales of small cars were [2] ------- strong in overseas markets. \"Consumers want vehicles that use less fuel, and we are ready to meet that demand,\" he said.\n\n[3] ------- the good news, Mr. Pierce remains cautious. He noted that competitors plan to launch several new models next year, which could affect the firm's future sales.","zh":"Norvale Motors 第三季表現亮眼\n\nNorvale Motors 星期二宣布，第三季的獲利比去年同期成長了 12%。這個結果超過了公司自己預測的 8%。\n\n公司總裁 Alan Pierce 表示，小型車在海外市場的銷售特別強勁。他說：「消費者想要更省油的車輛，而我們已經準備好滿足這個需求。」\n\n儘管有這個好消息，Pierce 先生仍然保持謹慎。他指出，競爭對手計劃明年推出幾款新車，這可能會影響公司未來的銷售。","w":[370,344,376,474,419,417,313,398,255,425,305],"qs":[{"q":"[1]","o":["enrolled","exceeded","persuaded","postponed"],"a":1,"k":"單字：獲利 12% vs 預測 8% → 超過 exceeded","n":[["(v.) 註冊（過去式）","","文法可以，但語意不通：不能註冊預測"],["(v.) 超過","exceed + 預期／預測","12% 高於預測的 8%，'exceeded ... forecast'"],["(v.) 說服（過去式）","","persuade 要接人，不能接 forecast"],["(v.) 延後（過去式）","","文法可以，但語意不通：不是延後預測"]]},{"q":"[2]","o":["particularly","approximately","verbally","punctually"],"a":0,"k":"單字：___ strong 修飾形容詞 → 特別強勁 particularly","n":[["(adv.) 特別地","particularly + adj.","'particularly strong' = 特別強勁，修飾形容詞"],["(adv.) 大約","","文法可以，但語意不通：approximately 用於數字"],["(adv.) 口頭地","","文法可以，但語意不通：銷售不會口頭強勁"],["(adv.) 準時地","","文法可以，但語意不通：不是準時強勁"]]},{"q":"[3]","o":["Although","Instead","Despite","Because of"],"a":2,"k":"連接詞：空格後接名詞 the good news、後句轉折 → Despite","n":[["(conj.) 雖然","Although + 完整子句","語意可以，但後面接名詞片語，不是子句"],["(adv.) 反而","","副詞，後面不能直接接名詞，語意也不合"],["(prep.) 儘管","Despite + N, 句子","後接名詞 the good news，且後句轉折"],["(prep.) 因為","","因果關係與後面的 cautious 轉折矛盾"]]}]},
{"id":"r600-25","lv":600,"p":7,"k":"review","ti":"Review of Seaside Garden Hotel","tx":"Seaside Garden Hotel\nRating: 4 out of 5\nReviewed by Linda Moore\n\nI stayed at the Seaside Garden Hotel for three nights during a business conference. My room was spacious and very clean, and the rate was reasonable for a hotel so close to the beach. I particularly liked the complimentary breakfast, which had a wide variety of fresh food.\n\nThe staff at the reception desk were friendly and gave me useful advice about local transportation. My only complaint is that the Internet was slow in the evenings, so it was hard to send large files.\n\nMy overall experience was good, and I would recommend this hotel to other business travelers.","zh":"Seaside Garden Hotel\n評分：4 分（滿分 5 分）\n評論者：Linda Moore\n\n我在參加商務研討會期間，在 Seaside Garden Hotel 住了三晚。我的房間寬敞又非常乾淨，而且以離海灘這麼近的飯店來說，房價很合理。我特別喜歡免費的早餐，有各式各樣的新鮮食物。\n\n接待櫃台的員工很親切，還給了我關於當地交通的實用建議。我唯一的抱怨是晚上的網路很慢，很難傳送大型檔案。\n\n我的整體體驗很好，我會把這家飯店推薦給其他商務旅客。","w":[262,397,368,406,419,393,325,279,489,400],"qs":[{"q":"Why was Ms. Moore staying at the hotel?","o":["She was visiting relatives","She was attending a conference","She was interviewing for a job","She was on a family vacation"],"a":1,"k":"細節題：找入住原因 → 'during a business conference'","n":[["她來探親","","文中沒提親戚"],["她來參加研討會","","文中 'during a business conference'"],["她來求職面試","","文中沒提面試"],["她來家庭旅遊","","文中是商務研討會，不是家庭度假"]]},{"q":"What problem does Ms. Moore mention?","o":["The Internet was slow at night","The staff were unfriendly","The room was too small","The breakfast was expensive"],"a":0,"k":"細節題：找 complaint → 'Internet was slow in the evenings'","n":[["晚上網路很慢","","文中 'only complaint ... Internet was slow'，晚上"],["員工不友善","","文中說員工 'friendly'，是讚美"],["房間太小","","文中 'spacious'，房間寬敞"],["早餐很貴","","文中 'complimentary breakfast'，是免費的"]]},{"q":"What is suggested about the hotel?","o":["It has no reception desk","It is only for business travelers","It is located near the beach","It charges extra for breakfast"],"a":2,"k":"推論題：'so close to the beach' → 飯店靠近海灘","n":[["沒有櫃台","","文中有 'staff at the reception desk'"],["只供商務旅客","","她只是推薦給商務旅客，沒說限定"],["位在海灘附近","","文中 'a hotel so close to the beach'"],["早餐要另外收費","","文中 'complimentary breakfast'，是免費的"]]}]},
{"id":"r600-26","lv":600,"p":7,"k":"review","ti":"Review of the TaskPilot app","tx":"Product Review: TaskPilot\nRating: 4 out of 5\nBy Sam Carter, small business owner\n\nI started using TaskPilot three months ago to track my team's assignments. The interface is simple, and it took me only a few minutes to learn. My favorite feature is the dashboard, which shows every project deadline on one screen. You can also customize the colors and categories.\n\nThe 30-day trial is free. After that, the subscription costs $9 a month, which is affordable for a small firm like mine. However, the phone application sometimes closes without warning. I hope the company fixes this soon.\n\nOverall, TaskPilot is a useful tool, and I recommend it.","zh":"產品評論：TaskPilot\n評分：4 分（滿分 5 分）\n評論者：小型企業老闆 Sam Carter\n\n三個月前，我開始用 TaskPilot 來追蹤團隊的工作任務。它的介面很簡單，我只花了幾分鐘就學會了。我最喜歡的功能是儀表板，它可以在一個畫面上顯示每個專案的截止日。你還可以自訂顏色和類別。\n\n30 天的試用是免費的。之後訂閱費是每月 9 美元，對我這種小公司來說負擔得起。不過，手機版的應用程式有時候會無預警關閉。希望公司能盡快修正。\n\n總而言之，TaskPilot 是很實用的工具，我推薦它。","w":[485,264,355,496,310,260,476,274,327,253,381,305,276,400],"qs":[{"q":"What is Mr. Carter reviewing?","o":["A new mobile phone","A computer repair service","A tool for managing team tasks","An online business course"],"a":2,"k":"主旨題：'track my team's assignments'，有 dashboard → 管理工作的軟體","n":[["新手機","","phone application 只是 App，評論對象不是手機"],["電腦維修服務","","文中沒提維修"],["管理團隊工作的工具","","文中 'track my team's assignments'，有 dashboard"],["線上商業課程","","文中沒提課程"]]},{"q":"How much does TaskPilot cost after the trial?","o":["$9 a year","$3 a month","$30 a month","$9 a month"],"a":3,"k":"細節題：找 After that → 'subscription costs $9 a month'","n":[["每年 9 美元","","文中是 'a month'，不是 a year"],["每月 3 美元","","文中沒有 $3 這個價格"],["每月 30 美元","","30 是 '30-day trial' 的天數，不是價格"],["每月 9 美元","","文中 'After that, the subscription costs $9 a month'"]]},{"q":"What is NOT mentioned as a feature of TaskPilot?","o":["Colors that users can change","A chat tool for team members","An interface that is easy to learn","A screen that shows deadlines"],"a":1,"k":"NOT 題：另三項在文中都有 → 沒提團隊聊天功能","n":[["可更改的顏色","","文中 'customize the colors'，有提到"],["團隊成員聊天工具","","全文沒提聊天功能，所以是答案"],["容易學會的介面","","文中 'took me only a few minutes to learn'，有提到"],["顯示截止日的畫面","","文中 dashboard 'shows every project deadline'，有提到"]]}]},
{"id":"r600-27","lv":600,"p":6,"k":"message","ti":"Reminder from Harbor View Hotel","tx":"Message from Harbor View Hotel\n\nHello, Ms. Kim. This is a reminder that your reservation at Harbor View Hotel begins tomorrow, July 22. Check-in starts at 3:00 P.M. [1] ------- you plan to arrive after 10:00 P.M., please let us know in advance.\n\nYour room rate includes breakfast and [2] ------- to the fitness center. Our airport shuttle bus runs every 30 minutes and is complimentary for hotel guests.\n\nAt check-in, please show [3] ------- photo identification and the credit card used for your booking. We look forward to welcoming you!","zh":"Harbor View Hotel 的訊息\n\nKim 小姐您好。提醒您，您在 Harbor View Hotel 的訂房從明天 7 月 22 日開始。下午 3 點開始辦理入住。如果您打算晚上 10 點以後才抵達，請事先告訴我們。\n\n您的房價包含早餐和健身中心的使用權。我們的機場接駁車每 30 分鐘一班，飯店房客可免費搭乘。\n\n辦理入住時，請出示有效的附照片身分證明，以及訂房時使用的信用卡。期待您的光臨！","w":[368,371,393,401,269,366],"qs":[{"q":"[1]","o":["Although","If","Unless","Until"],"a":1,"k":"連接詞：If you plan to arrive after 10 P.M. → 條件 If","n":[["(conj.) 雖然","","文法可以，但語意不通：前後不是讓步"],["(conj.) 如果","If + 子句, please + V","晚到才需通知，是條件關係"],["(conj.) 除非","","文法可以，但語意變成「不晚到才要通知」，相反"],["(conj.) 直到","","文法可以，但語意不通：不是時間上的持續"]]},{"q":"[2]","o":["evidence","priority","access","balance"],"a":2,"k":"單字：includes breakfast and ___ to the fitness center → access","n":[["(n.) 證據","","evidence 不和 to + 場所搭配，語意不通"],["(n.) 優先事項","","文法可以，但語意不通：房價不含優先事項"],["(n.) 使用權、進入","access to + 場所","固定搭配 access to the fitness center"],["(n.) 餘額","","文法可以，但語意不通：房價不含餘額"]]},{"q":"[3]","o":["spacious","valid","verbal","punctual"],"a":1,"k":"單字：show ___ photo identification → 有效的 valid","n":[["(adj.) 寬敞的","","文法可以，但語意不通：不能形容證件"],["(adj.) 有效的","valid photo identification","入住要出示有效的附照片證件"],["(adj.) 口頭的","","文法可以，但語意不通：證件不是口頭的"],["(adj.) 準時的","","文法可以，但語意不通：不能形容證件"]]}]},
{"id":"r600-28","lv":600,"p":7,"k":"form","ti":"Order confirmation 58213","tx":"ORDER CONFIRMATION\nBrightway Office Supplies\n\nOrder number: 58213\nOrder date: June 3\nCustomer: Ms. Karen Hsu, Delta Accounting Firm\n\nItems purchased:\n2 office chairs (black), $90 each\n1 standing desk, $240\n5 boxes of copy paper, $6 each\n\nMerchandise total: $450\nShipping charge: $0 (complimentary for orders over $300)\nTotal paid by credit card: $450\n\nEstimated delivery: June 7 by Swift Courier\n\nNotes: The chairs must be assembled by the customer. Instructions are in the box. Unused items may be returned within 14 days. To track your shipment, enter your order number on our website.","zh":"訂單確認\nBrightway Office Supplies\n\n訂單編號：58213\n訂購日期：6 月 3 日\n顧客：Delta Accounting Firm 的 Karen Hsu 小姐\n\n購買品項：\n辦公椅（黑色）2 張，每張 90 美元\n站立式辦公桌 1 張，240 美元\n影印紙 5 箱，每箱 6 美元\n\n商品總計：450 美元\n運費：0 美元（訂單超過 300 美元免運費）\n信用卡付款總額：450 美元\n\n預計送達：6 月 7 日，由 Swift Courier 配送\n\n備註：椅子須由顧客自行組裝，說明書在箱子裡。未使用的商品可在 14 天內退貨。如要追蹤貨件，請在我們的網站上輸入訂單編號。","w":[329,305,492,331,486,393,366,341,448,485,316],"qs":[{"q":"Why was Ms. Hsu not charged for shipping?","o":["She picked up the items herself","She is a new customer","She used a discount coupon","Her order was over $300"],"a":3,"k":"細節題：找 Shipping → 'complimentary for orders over $300'","n":[["她自己取貨","","文中 'Estimated delivery ... by Swift Courier'，是配送"],["她是新客戶","","文中沒提新客戶優惠"],["她用了折價券","","文中沒提折價券"],["她的訂單超過 300 美元","","文中 'complimentary for orders over $300'，她是 $450"]]},{"q":"What must Ms. Hsu do with the chairs?","o":["Pick them up at a store","Pay for them on delivery","Return them within 7 days","Put them together"],"a":3,"k":"細節題：找 chairs → 'must be assembled by the customer'","n":[["到門市取貨","","文中是 courier 配送，不用取貨"],["貨到付款","","文中 'paid by credit card'，已付款"],["7 天內退回","","文中退貨期是 14 天，且非必須退貨"],["自行組裝","put together = assemble","文中 'must be assembled by the customer'"]]},{"q":"What information is NOT included in the form?","o":["The date of the order","The price of each item","The name of the delivery company","The customer's street address"],"a":3,"k":"NOT 題：逐項對照表單 → 沒有顧客的街道地址","n":[["訂購日期","","文中 'Order date: June 3'，有提到"],["各商品價格","","文中 '$90 each'、'$240'、'$6 each'，有提到"],["配送公司名稱","","文中 'by Swift Courier'，有提到"],["顧客的街道地址","","只有姓名和公司，沒有地址，所以是答案"]]}]},
{"id":"r600-29","lv":600,"p":7,"k":"form","ti":"Travel itinerary for Mr. Reyes","tx":"TRAVEL ITINERARY\nPrepared for: Mr. David Reyes, Sales Division\n\nMonday, October 6\n8:40 A.M. Depart Dallas on Flight 302\n11:05 A.M. Arrive in Chicago (layover: 1 hour 30 minutes)\n12:35 P.M. Depart Chicago on Flight 518\n2:05 P.M. Arrive in Minneapolis\nTransportation to hotel: complimentary shuttle bus\nHotel: Pinecrest Inn (two nights)\n\nTuesday, October 7\n9:00 A.M. to 4:00 P.M. Retail Industry Conference, City Convention Center\n6:30 P.M. Evening reception\n\nWednesday, October 8\n10:05 A.M. Depart Minneapolis on Flight 177 (direct flight to Dallas)\n\nNote: Please bring your conference registration number and photo identification.","zh":"出差行程表\n出差人：業務部 David Reyes 先生\n\n10 月 6 日星期一\n上午 8:40　搭乘 302 號班機從達拉斯出發\n上午 11:05　抵達芝加哥（轉機停留：1 小時 30 分鐘）\n下午 12:35　搭乘 518 號班機從芝加哥出發\n下午 2:05　抵達明尼亞波利斯\n前往飯店的交通：免費接駁車\n飯店：Pinecrest Inn（兩晚）\n\n10 月 7 日星期二\n上午 9:00 至下午 4:00　零售產業研討會，City Convention Center\n下午 6:30　晚間招待會\n\n10 月 8 日星期三\n上午 10:05　搭乘 177 號班機從明尼亞波利斯出發（直飛達拉斯）\n\n備註：請攜帶您的研討會報名編號和附照片的身分證明文件。","w":[352,287,347,279,393,364,266,262,325,278,269],"qs":[{"q":"What is the main reason for Mr. Reyes's trip?","o":["To attend a conference","To open a new store","To interview job applicants","To take a vacation"],"a":0,"k":"主旨題：週二 'Retail Industry Conference' + 要帶註冊編號","n":[["參加研討會","","週二 'Retail Industry Conference'，要帶報名編號"],["開新店","","行程沒提開店"],["面試應徵者","","行程沒提面試"],["度假","","行程是研討會，不是度假"]]},{"q":"Where will Mr. Reyes wait between flights on Monday?","o":["At the Pinecrest Inn","In Minneapolis","In Chicago","In Dallas"],"a":2,"k":"細節題：找週一轉機 → 'layover: 1 hour 30 minutes'","n":[["在 Pinecrest 旅館","","旅館是抵達 Minneapolis 後才住的"],["在明尼亞波利斯","","Minneapolis 是終點，不是轉機地"],["在芝加哥","","文中 'Arrive in Chicago (layover'，轉機"],["在達拉斯","","Dallas 是出發地，不是轉機地"]]},{"q":"What is indicated about the shuttle bus to the hotel?","o":["It is free of charge","It goes to the convention center","It must be booked in advance","It leaves at 2:05 P.M."],"a":0,"k":"細節題：找 shuttle bus → 'complimentary shuttle bus'","n":[["免費","","文中 'complimentary shuttle bus'，complimentary = 免費"],["開往會議中心","","文中 'Transportation to hotel'，是去旅館"],["必須事先預約","","文中沒提預約"],["下午 2:05 發車","","2:05 是班機抵達 Minneapolis 的時間"]]}]},
{"id":"r600-30","lv":600,"p":6,"k":"review","ti":"Review of Olive Tree Kitchen","tx":"Olive Tree Kitchen\nRating: 5 out of 5\nReviewed by Hannah Fisher\n\nLast Saturday, my family and I had dinner at Olive Tree Kitchen, a small restaurant that opened in March. The chef uses fresh [1] ------- from local farms, and you can really taste the difference. I ordered the grilled fish, which [2] ------- with rice and vegetables.\n\nThe prices were [3] ------- for the quality. Our meal for four people cost only $70. The servers were particularly friendly and brought our food quickly.\n\nThe restaurant already has a strong reputation, so I suggest booking a table in advance. We will certainly go back.","zh":"Olive Tree Kitchen\n評分：5 分（滿分 5 分）\n評論者：Hannah Fisher\n\n上週六，我和家人到 Olive Tree Kitchen 吃晚餐，這是一家三月才開幕的小餐廳。主廚使用來自當地農場的新鮮食材，真的吃得出差別。我點了烤魚，搭配白飯和蔬菜一起上桌。\n\n以這樣的品質來說，價格很合理。我們四個人這一餐只花了 70 美元。服務生特別親切，上菜也很快。\n\n這家餐廳已經有很好的名聲，所以我建議事先訂位。我們一定會再去。","w":[254,406,419,351,451],"qs":[{"q":"[1]","o":["ingredients","statements","appliances","utilities"],"a":0,"k":"單字：fresh ___ from local farms → 食材 ingredients","n":[["(n.) 食材","fresh ingredients","主廚用來自農場的新鮮食材做菜"],["(n.) 聲明、對帳單","","文法可以，但語意不通：農場不產出對帳單"],["(n.) 家電","","文法可以，但語意不通：農場不產家電"],["(n.) 水電瓦斯費","","文法可以，但語意不通：不是 fresh 的東西"]]},{"q":"[2]","o":["serving","has served","was served","serves"],"a":2,"k":"時態／語態：which 指 the grilled fish、Last Saturday → was served","n":[["(V-ing) 上菜","","前面沒有 be 動詞，不能當子句動詞"],["(完成式) 已上菜","","主動式，魚不會自己上菜；Last Saturday 也不配完成式"],["(被動過去式) 被端上","be served with + N","魚是被端上桌；Last Saturday 是過去"],["(現在式) 上菜","","主動式，且與 Last Saturday 時態不合"]]},{"q":"[3]","o":["reasonable","spacious","punctual","anonymous"],"a":0,"k":"單字：prices were ___ for the quality；四人只花 $70","n":[["(adj.) 合理的","reasonable for + N","四人只花 $70，價格合理"],["(adj.) 寬敞的","","文法可以，但語意不通：不能形容價格"],["(adj.) 準時的","","文法可以，但語意不通：價格不會準時"],["(adj.) 匿名的","","文法可以，但語意不通：價格不會匿名"]]}]},
{"id":"r800-01","lv":800,"p":7,"k":"email","ti":"Delay in your office chair order","tx":"To: Karen Wu\nFrom: Daniel Ortiz, Brightline Office Supply\nSubject: Delay in your office chair order\n\nDear Ms. Wu,\n\nThank you for your recent order of 40 office chairs (invoice #5821). I am writing to notify you that the shipment will not arrive on March 4 as scheduled. During a routine inspection at our warehouse, we detected a defect in the wheels of several chairs. To ensure that every chair you receive is reliable, we have asked the manufacturer to replace the entire batch.\n\nOur current estimate is that the chairs will be delivered on March 18. To compensate you for the inconvenience, we will deduct 10 percent from your invoice, and you will not be charged for delivery.\n\nIf the new date does not suit you, an alternative model is in stock and can be shipped within two days. Please let me know by Friday how you would like to proceed.\n\nSincerely,\nDaniel Ortiz\nCustomer Representative","zh":"收件人：Karen Wu\n寄件人：Daniel Ortiz，Brightline Office Supply\n主旨：您的辦公椅訂單延遲\n\n吳小姐您好：\n\n感謝您最近訂購 40 張辦公椅（發票號碼 5821）。來信是要通知您，這批貨無法如期在 3 月 4 日送達。我們在倉庫進行例行檢查時，發現其中幾張椅子的輪子有瑕疵。為了確保您收到的每一張椅子都可靠耐用，我們已請製造商更換整批貨。\n\n我們目前估計椅子會在 3 月 18 日送達。為了補償造成您的不便，我們會從您的發票金額中扣除 10%，而且不收運費。\n\n如果新的日期對您不方便，我們另有一款替代型號有現貨，可以在兩天內出貨。請在星期五之前告訴我您希望如何處理。\n\n敬上\nDaniel Ortiz\n客戶服務代表","w":[725,531,685,514,702,674,580,691],"qs":[{"q":"What is the main purpose of the e-mail?","o":["To request payment of an overdue invoice","To confirm that an order has arrived","To advertise a new chair model","To explain why a delivery will be late"],"a":3,"k":"主旨題：首句 'will not arrive on March 4' → 說明延遲與原因","n":[["要求支付逾期發票款項","","文中沒有催款，只談折扣與運費"],["確認訂單已送達","","文中說貨「不會」如期送達，尚未到貨"],["宣傳新椅款","","替代型號只是備案，不是廣告"],["說明交貨為何延遲","","'will not arrive on March 4' 加上輪子瑕疵的原因"]]},{"q":"What was found during the inspection?","o":["An error in the invoice total","Damage to the delivery truck","A shortage of warehouse staff","A problem with some chair wheels"],"a":3,"k":"細節題：找 inspection → 'detected a defect in the wheels'","n":[["發票總額有誤","","文中沒提到發票金額錯誤"],["送貨卡車受損","","文中沒提到卡車"],["倉庫人手不足","","文中沒提到人力問題"],["部分椅子輪子有問題","","文中 'a defect in the wheels of several chairs'"]]},{"q":"What is NOT offered to Ms. Wu?","o":["A lower price on her order","Free delivery","A different chair model","A full refund"],"a":3,"k":"NOT 題：逐項對照 → 折扣、免運、替代型號都有，退款沒有","n":[["訂單降價","","有提到：'deduct 10 percent from your invoice'"],["免運費","","有提到：'you will not be charged for delivery'"],["不同的椅子型號","","有提到：'an alternative model is in stock'"],["全額退款","","其他三項都有，文中完全沒提退款"]]}]},
{"id":"r800-02","lv":800,"p":7,"k":"notice","ti":"Elevator inspection on Thursday","tx":"NOTICE TO ALL TENANTS\nElevator Inspection: Thursday, June 12\n\nThe annual safety inspection of the elevators in Parkview Tower is mandatory under city regulations. It will be conducted this Thursday from 9:00 A.M. to 1:00 P.M.\n\nOnly one passenger elevator will be taken out of operation at a time, so the other two will remain available. However, waiting times may be longer than usual. As a precaution, use of the freight elevator will be restricted to building personnel during the inspection. Tenants who are expecting large deliveries should reschedule them for the afternoon.\n\nAnyone who needs assistance while the elevators are being checked may ask at the security desk in the lobby.\n\nWe apologize for any inconvenience. For further information, please contact the management office at extension 204.\n\nParkview Tower Management","zh":"致全體承租戶公告\n電梯檢查：6 月 12 日星期四\n\n依照市政法規，Parkview Tower 的電梯每年都必須進行安全檢查。這次檢查將於本週四上午 9 點至下午 1 點進行。\n\n每次只會停用一部客用電梯，其他兩部仍可正常使用，不過等候時間可能會比平常久。為了預防萬一，檢查期間貨梯僅限大樓工作人員使用。預計有大型貨物送達的承租戶，請將送貨時間改到下午。\n\n電梯檢查期間如需協助，可洽大廳的保全櫃檯。\n\n造成不便，敬請見諒。如需進一步資訊，請撥分機 204 與管理室聯絡。\n\nParkview Tower 管理處","w":[531,639,710,533,532,670,528,580],"qs":[{"q":"Why is the inspection being carried out?","o":["New elevators are being installed","An elevator broke down last week","Tenants complained about long waits","It is required by city rules"],"a":3,"k":"細節題：找檢查原因 → 'mandatory under city regulations'","n":[["正在安裝新電梯","","文中是年度安全檢查，沒提安裝新電梯"],["上週有電梯故障","","文中沒提到故障"],["住戶抱怨等候太久","","文中只預告等候可能變長，沒提抱怨"],["市府規定必須進行","","文中 'mandatory under city regulations'"]]},{"q":"What are tenants expecting large deliveries advised to do?","o":["Pay a fee to use the freight elevator","Have them left in the lobby","Postpone them until next week","Move them to the afternoon"],"a":3,"k":"細節題：找 large deliveries → 'reschedule them for the afternoon'","n":[["付費使用貨梯","","文中貨梯只限大樓人員使用，沒提收費"],["把貨放在大廳","","文中沒提到放大廳"],["延到下週","","文中說改到當天下午，不是延到下週"],["改到下午","","文中 'reschedule them for the afternoon'"]]},{"q":"The word \"restricted\" in the notice is closest in meaning to","o":["extended","limited","repaired","offered"],"a":1,"k":"字義題：'restricted to building personnel' → 只限，即 limited","n":[["(v.) 延長","","語意相反：文中是限制使用，不是延長"],["(adj.) 受限的","","'restricted to building personnel' 即只限大樓人員"],["(v.) 修理","","貨梯沒有要修理，語意不符"],["(v.) 提供","","文中是限定使用者，不是提供貨梯"]]}]},
{"id":"r800-03","lv":800,"p":7,"k":"memo","ti":"New procedure for travel expenses","tx":"MEMO\nTo: All sales personnel\nFrom: Linda Park, Finance Department\nDate: September 2\nSubject: New procedure for travel expenses\n\nBeginning October 1, the company will implement a new procedure for travel expense claims. The objective is to streamline the process and reduce the time employees wait for payment.\n\nInstead of filling out paper forms, you will upload a photo of each receipt or invoice to the online expense system. Your supervisor will then validate the claim, and the amount will be transferred to your bank account. Claims that follow the guidelines should be paid within five working days, rather than the current three weeks.\n\nPlease note that claims submitted more than 30 days after a trip will be declined.\n\nA 20-minute webinar outlining the new system will be held on September 15 and again on September 17. Attendance at one of these sessions is compulsory.","zh":"備忘錄\n收件人：全體業務人員\n寄件人：Linda Park，財務部\n日期：9 月 2 日\n主旨：差旅費申請新流程\n\n自 10 月 1 日起，公司將實施新的差旅費申請流程，目的是簡化作業，縮短員工等待款項的時間。\n\n以後不必再填寫紙本表單，只要把每張收據或發票拍照，上傳到線上費用系統即可。接著由您的主管審核確認，款項就會匯入您的銀行帳戶。符合規範的申請應可在五個工作天內付款，不必像現在要等三個星期。\n\n請注意，出差結束超過 30 天才提出的申請將不予受理。\n\n說明新系統的 20 分鐘網路研討會將於 9 月 15 日舉行，9 月 17 日再辦一場。兩場之中必須參加一場。","w":[564,676,541,732,694,544,746,610],"qs":[{"q":"What is the memo mainly about?","o":["A new schedule for paychecks","A change in how expenses are claimed","A training course for supervisors","A reduction in the travel budget"],"a":1,"k":"主旨題：首句 'new procedure for travel expense claims'","n":[["新的薪資發放時程","","文中談差旅費申請，不是薪水"],["費用申請方式的改變","","首句 'new procedure for travel expense claims'"],["主管的訓練課程","","研討會只是細節，且寄給全體業務人員"],["縮減差旅預算","","文中沒提到預算削減"]]},{"q":"How quickly should claims be paid under the new procedure?","o":["Within 30 days of the trip","Within three weeks","Within five working days","On the same day"],"a":2,"k":"細節題：找 paid within → 'within five working days'","n":[["出差後 30 天內","","30 天是申請期限，不是付款時間"],["三週內","","'the current three weeks' 是舊制"],["五個工作天內","","文中 'paid within five working days'"],["當天","","文中沒提到當天付款"]]},{"q":"What is indicated about the webinar?","o":["It lasts for one hour","It is only for supervisors","It will be held once, on October 1","Attending one session is required"],"a":3,"k":"細節題：找 webinar → 'Attendance ... is compulsory'","n":[["長達一小時","","文中是 '20-minute webinar'"],["只給主管參加","","備忘錄寄給 all sales personnel，沒限主管"],["只辦一次，10 月 1 日","","文中是 9/15 與 9/17 兩場；10/1 是新制起始日"],["必須參加其中一場","","文中 'Attendance ... is compulsory'"]]}]},
{"id":"r800-04","lv":800,"p":7,"k":"advertisement","ti":"Harbor Crest Hotel: Made for Business Travelers","tx":"Harbor Crest Hotel: Made for Business Travelers\n\nLocated five minutes from Lakeside Convention Center, the newly renovated Harbor Crest Hotel offers everything a business traveler needs. Every room has a large desk, reliable high-speed Internet, and a coffee machine. Our amenities include a 24-hour fitness center, an indoor pool, and a business lounge with free printing.\n\nPlanning an event? Our three meeting rooms can accommodate groups of 10 to 120 people, and our onsite catering team will prepare a menu to suit your budget.\n\nExclusive corporate offer: Companies that book ten or more nights before November 30 qualify for a 15 percent discount and a free shuttle service to the airport.\n\nTo obtain an estimate for your group, call our sales representative at 555-0142.","zh":"Harbor Crest Hotel：專為商務旅客打造\n\n全新整修的 Harbor Crest Hotel 距離 Lakeside 會議中心只要五分鐘，商務旅客需要的一切這裡都有。每間客房都有大書桌、穩定的高速網路和咖啡機。飯店設施包括 24 小時健身中心、室內游泳池，以及可免費列印的商務交誼廳。\n\n要辦活動嗎？我們的三間會議室可容納 10 到 120 人的團體，飯店內的外燴團隊也會依照您的預算設計菜單。\n\n企業專屬優惠：凡在 11 月 30 日前預訂十晚以上的公司，即可享有八五折優惠及免費機場接駁服務。\n\n如需為您的團體索取報價，請撥 555-0142 與我們的業務代表聯絡。","w":[686,617,539,711,576,630,631,659],"qs":[{"q":"Who is the advertisement mainly intended for?","o":["Families on vacation","People traveling for work","Hotel employees seeking jobs","Students looking for cheap rooms"],"a":1,"k":"主旨題：標題 'Made for Business Travelers'","n":[["度假的家庭","","文中針對 business traveler，沒提家庭"],["出差的人","","文中 'everything a business traveler needs'"],["求職的飯店員工","","文中沒有徵才訊息"],["找便宜房間的學生","","文中沒提學生或低價房"]]},{"q":"How can a company get the 15 percent discount?","o":["By booking ten or more nights","By joining the fitness center","By paying for the airport shuttle","By holding an event for 120 people"],"a":0,"k":"細節題：找 15 percent → 'book ten or more nights'","n":[["訂房十晚以上","","文中 'book ten or more nights'"],["加入健身中心","","健身中心只是設施，不是折扣條件"],["付費搭機場接駁","","接駁是 'free'，是折扣之外的贈送"],["舉辦 120 人的活動","","120 人只是會議室容量上限，非折扣條件"]]},{"q":"What is NOT mentioned as a feature of the hotel?","o":["A rooftop restaurant","Meeting rooms","An indoor pool","A fitness center"],"a":0,"k":"NOT 題：逐項找設施 → 健身中心、泳池、會議室都有","n":[["頂樓餐廳","","其他三項都有，文中沒有頂樓餐廳"],["會議室","","有提到：'three meeting rooms'"],["室內游泳池","","有提到：'an indoor pool'"],["健身中心","","有提到：'a 24-hour fitness center'"]]}]},
{"id":"r800-05","lv":800,"p":7,"k":"message","ti":"Lunch order for Thursday's seminar","tx":"Mei Tanaka (10:12 A.M.): Hi Robert. I just received the final headcount for Thursday's seminar. It's 64, not 50.\nRobert Diaz (10:14 A.M.): That's a significant increase. Our catering order only covers 50 lunches.\nMei Tanaka (10:15 A.M.): Can the vendor handle 14 more?\nRobert Diaz (10:21 A.M.): I just called them. They can, but they have run out of the chicken dish. They suggested vegetable pasta as a substitute for the additional meals.\nMei Tanaka (10:22 A.M.): That's fine. What about the cost?\nRobert Diaz (10:24 A.M.): The revised estimate is $896, which is still within our budget of $950.\nMei Tanaka (10:25 A.M.): Great. Please go ahead and confirm it. I'll notify the venue that we need more tables.\nRobert Diaz (10:26 A.M.): Will do. I'll forward you the new invoice this afternoon.","zh":"Mei Tanaka（上午 10:12）：嗨，Robert。我剛收到星期四研討會的最終人數，是 64 人，不是 50 人。\nRobert Diaz（上午 10:14）：增加得不少。我們訂的外燴只有 50 份午餐。\nMei Tanaka（上午 10:15）：廠商有辦法多做 14 份嗎？\nRobert Diaz（上午 10:21）：我剛打電話問過了。可以，但雞肉餐點已經沒有了。他們建議多出來的餐點改用蔬菜義大利麵代替。\nMei Tanaka（上午 10:22）：沒問題。費用呢？\nRobert Diaz（上午 10:24）：修改後的報價是 896 美元，還在我們 950 美元的預算內。\nMei Tanaka（上午 10:25）：太好了，請直接跟他們確認。我會通知場地我們需要更多桌子。\nRobert Diaz（上午 10:26）：好的。我下午把新的發票轉寄給你。","w":[569,538,576,540,743,740,725,573],"qs":[{"q":"Why did Ms. Tanaka contact Mr. Diaz?","o":["To report a new number of attendees","To cancel a catering order","To ask for a larger budget","To complain about a vendor's poor service"],"a":0,"k":"主旨題：開頭 'final headcount ... 64, not 50' → 通知人數變動","n":[["通知新的出席人數","","文中 'It's 64, not 50'，人數改變"],["取消餐飲訂單","","文中是增加餐點，不是取消"],["要求更多預算","","'still within our budget of $950'，預算夠用"],["抱怨廠商服務不佳","","廠商願意多供 14 份，文中沒有抱怨"]]},{"q":"What will the vendor provide for the additional meals?","o":["A beef sandwich","Vegetable pasta","A chicken dish","A fruit dessert"],"a":1,"k":"細節題：找 additional meals → 'vegetable pasta as a substitute'","n":[["牛肉三明治","","文中沒提到"],["蔬菜義大利麵","","文中 'suggested vegetable pasta'"],["雞肉餐點","","文中說 'run out of the chicken dish'，已售完"],["水果甜點","","文中沒提到甜點"]]},{"q":"What will Ms. Tanaka most likely do next?","o":["Reduce the number of attendees","Send an invoice to Mr. Diaz","Call the catering vendor","Contact the seminar venue"],"a":3,"k":"推論題：找 Tanaka 的承諾 → 'I'll notify the venue'","n":[["減少出席人數","","人數是增加到 64，不是減少"],["寄發票給 Diaz","","是 Diaz 說 'forward you the new invoice'"],["打給餐飲廠商","","打給廠商的是 Diaz：'I just called them'"],["聯絡研討會場地","","文中 'I'll notify the venue'"]]}]},
{"id":"r800-06","lv":800,"p":7,"k":"article","ti":"Maple & Rye to Open Three New Branches","tx":"Maple & Rye to Open Three New Branches\n\nRIVERTON — Maple & Rye, the bakery chain founded in Riverton twelve years ago, announced an ambitious expansion plan on Monday. The company will open three new branches in the neighboring cities of Dalton and Westfield by the end of next year.\n\nFounder Helen Brooks said that revenue has grown for five consecutive years, primarily because of strong demand for the company's whole-grain bread. \"Our customers have been very loyal,\" she remarked. \"This is the right moment to broaden our reach.\"\n\nTo support the new stores, Maple & Rye intends to recruit about 60 employees and relocate its headquarters to a larger building on Canal Street. The current headquarters will be transformed into a training center for new bakers.\n\nThe first of the new branches, in Dalton, is scheduled to open in March.","zh":"Maple & Rye 將新開三家分店\n\nRIVERTON 訊 — 十二年前在 Riverton 創立的連鎖麵包店 Maple & Rye，星期一宣布了一項企圖心十足的擴張計畫。該公司將在明年年底前，於鄰近的 Dalton 和 Westfield 兩個城市新開三家分店。\n\n創辦人 Helen Brooks 表示，公司營收已連續五年成長，主要是因為全穀麵包的需求強勁。她說：「我們的顧客一直非常忠實，現在正是擴大版圖的好時機。」\n\n為了支援新門市，Maple & Rye 打算招募約 60 名員工，並把總部遷到 Canal Street 上一棟更大的建築。現在的總部將改造成新進麵包師傅的訓練中心。\n\n第一家新分店位於 Dalton，預定三月開幕。","w":[623,560,590,625,664,717,566,690],"qs":[{"q":"What is the article mainly about?","o":["A company's plan to grow","A bakery that is closing","A new type of bread","The retirement of a company founder"],"a":0,"k":"主旨題：標題與首段 'expansion plan' → 公司擴張","n":[["公司的擴張計畫","","文中 'expansion plan'，將開三家新分店"],["即將歇業的麵包店","","文中是增加分店，不是關店"],["新種類的麵包","","全穀麵包只是營收成長的原因"],["創辦人退休","","創辦人只是受訪，文中沒提退休"]]},{"q":"What will happen to the current headquarters?","o":["It will be closed in March","It will become a training center","It will be sold to another company","It will be turned into a new branch"],"a":1,"k":"細節題：找 headquarters → 'transformed into a training center'","n":[["三月關閉","","March 是 Dalton 新分店的開幕時間"],["將變成訓練中心","","文中 'transformed into a training center'"],["將賣給其他公司","","文中沒提到出售"],["將改成新分店","","文中說改成訓練中心，不是分店"]]},{"q":"What is suggested about Maple & Rye?","o":["Its revenue fell last year","It will stop selling whole-grain bread","It plans to reduce its staff","It has operated for over ten years"],"a":3,"k":"推論題：'founded ... twelve years ago' → 營業超過十年","n":[["去年營收下滑","","文中是 'grown for five consecutive years'"],["將停售全穀麵包","","全穀麵包需求強勁，沒提停售"],["打算裁員","","文中是 'recruit about 60 employees'，要增員"],["已營業超過十年","","文中 'founded ... twelve years ago'"]]}]},
{"id":"r800-07","lv":800,"p":7,"k":"letter","ti":"Your mortgage application","tx":"Northgate Bank\n18 Fulton Street\n\nApril 9\n\nMr. Samuel Reyes\n52 Orchard Lane\n\nDear Mr. Reyes,\n\nWe are pleased to inform you that your mortgage application has been approved. Based on our analysis of your financial records, Northgate Bank can offer you a loan of $240,000 over a span of 20 years.\n\nBefore we can proceed, we need two further documents: a copy of your most recent tax return and a signed copy of the enclosed agreement. Please read clause 7 carefully, as it specifies the fee for late payments. Monthly installments will be taken automatically from your Northgate checking account on the fifth day of each month.\n\nThis offer is valid until May 9. To clarify any details, please visit your local branch or call our mortgage representative, Ms. Julia Novak, at 555-0178.\n\nSincerely,\nPeter Lang\nLoan Department","zh":"Northgate Bank\nFulton Street 18 號\n\n4 月 9 日\n\nSamuel Reyes 先生\nOrchard Lane 52 號\n\nReyes 先生您好：\n\n很高興通知您，您的房屋貸款申請已經核准。根據我們對您財務紀錄的分析，Northgate Bank 可以提供您 24 萬美元的貸款，還款期間為 20 年。\n\n在進行下一步之前，我們還需要兩份文件：您最近一期的報稅單影本，以及隨信附上的合約簽名本。請仔細閱讀第 7 條，其中載明了逾期付款的費用。每月的分期款項將於每月 5 日自動從您的 Northgate 支票存款帳戶扣款。\n\n本貸款方案的有效期限至 5 月 9 日。如需釐清任何細節，請親臨您附近的分行，或撥 555-0178 與我們的房貸專員 Julia Novak 小姐聯絡。\n\n敬上\nPeter Lang\n貸款部","w":[519,543,644,601,672,586,680,542],"qs":[{"q":"Why was the letter sent?","o":["To report a late payment","To advertise a new branch","To close a checking account","To announce that a loan was approved"],"a":3,"k":"主旨題：首句 'mortgage application has been approved'","n":[["通報遲繳","","遲繳只是合約第 7 條的罰款規定"],["宣傳新分行","","文中沒提新分行"],["關閉活期帳戶","","支票帳戶是用來自動扣款，沒要關閉"],["通知貸款已核准","","文中 'has been approved'"]]},{"q":"What must Mr. Reyes provide before the bank can proceed?","o":["A tax return and a signed agreement","A list of his monthly expenses","A copy of his passport and a recent photo","A letter from his employer"],"a":0,"k":"細節題：找 two further documents → 稅單與簽名合約","n":[["報稅單與簽名的合約","","文中 'tax return' 與 'signed copy' 兩項"],["每月支出清單","","文中沒要求這項文件"],["護照影本與近照","","文中沒要求護照或照片"],["雇主的信函","","文中沒要求雇主信函"]]},{"q":"The word \"span\" in the letter is closest in meaning to","o":["rate","amount","distance","period"],"a":3,"k":"字義題：'over a span of 20 years' → 一段期間，即 period","n":[["(n.) 比率；利率","","20 years 是時間長度，不是利率"],["(n.) 金額","","金額已寫 $240,000，20 years 指時間"],["(n.) 距離","","與年數搭配，距離語意不通"],["(n.) 期間","","文中 'span of 20 years' 即 20 年期間"]]}]},
{"id":"r800-08","lv":800,"p":7,"k":"announcement","ti":"Leadership Workshop for New Supervisors","tx":"Leadership Workshop for New Supervisors\n\nThe Personnel Department is pleased to announce a two-day workshop, \"Leading Your Team,\" on May 21 and 22 in Training Room 2 at headquarters.\n\nThe workshop is designed for employees who have been promoted to a supervisory position within the past twelve months. For this group, attendance is compulsory. Other staff members who wish to pursue a management career are also eligible, provided that their manager gives written approval.\n\nTopics include how to delegate tasks, evaluate performance fairly, and resolve disputes between team members. The sessions will be conducted by Angela Moreno, an external consultant who specializes in workplace communication.\n\nBecause the room has a capacity of 24, the remaining places will be allocated in the order that requests are received. To register, e-mail the Personnel Department by May 9.","zh":"新任主管領導力工作坊\n\n人事部很高興宣布，將於 5 月 21 日和 22 日在總部第 2 訓練室舉辦為期兩天的工作坊「帶領你的團隊」。\n\n本工作坊是為過去十二個月內升任主管職的員工所設計，這些人員一律必須參加。其他有志往管理職發展的同仁，只要取得主管的書面同意，也有資格報名。\n\n課程主題包括如何分派工作、公平地評估績效，以及化解團隊成員之間的爭執。課程將由專攻職場溝通的外部顧問 Angela Moreno 主講。\n\n由於教室只能容納 24 人，剩餘名額將依照收到申請的先後順序分配。報名請在 5 月 9 日前寄電子郵件給人事部。","w":[524,610,608,749,679,678,598,729],"qs":[{"q":"What is the purpose of the announcement?","o":["To advertise a job opening for a supervisor","To report the results of a staff survey","To introduce a new department head","To give details of a training event"],"a":3,"k":"主旨題：首句 'pleased to announce a two-day workshop'","n":[["刊登主管職缺","","對象是已升任者，不是徵人"],["報告員工問卷結果","","文中沒提問卷"],["介紹新部門主管","","文中沒提新主管就任"],["提供訓練活動細節","","文中 'workshop'，含日期、對象、主題、報名"]]},{"q":"What do staff members who are not new supervisors need in order to attend?","o":["An invitation from Ms. Moreno","Written approval from their manager","Twelve months of experience","A certificate in communication"],"a":1,"k":"細節題：找 Other staff → 'manager gives written approval'","n":[["Moreno 女士的邀請","","Moreno 是講師，文中沒提邀請函"],["主管的書面同意","","文中 'manager gives written approval'"],["十二個月的經驗","","12 個月是新主管升職的時間範圍"],["溝通證書","","文中沒提到證書"]]},{"q":"What is NOT listed as a workshop topic?","o":["Settling disagreements","Assigning work to others","Judging employees' performance","Preparing a department budget"],"a":3,"k":"NOT 題：逐項對照 topics → 分派、評估、化解爭執都有","n":[["化解歧見","","有提到：'resolve disputes'"],["分派工作給他人","","有提到：'delegate tasks'"],["評估員工績效","","有提到：'evaluate performance fairly'"],["編列部門預算","","其他三項都有，文中沒提預算"]]}]},
{"id":"r800-09","lv":800,"p":7,"k":"review","ti":"A durable bag with one weak point","tx":"Product: Trekline Pro 15 Laptop Backpack\nReviewer: Marcus Hall\nRating: 4 out of 5 stars\n\nA durable bag with one weak point\n\nI travel by train every day, so I need a bag that can bear a heavy load. After six months of daily use, my Trekline Pro still looks almost new. The fabric is very strong, and the padded pocket has protected my laptop on numerous crowded journeys. The bag is also compatible with most suitcase handles, which is a tremendous help at airports.\n\nMy only complaint concerns the zipper on the front pocket, which broke after about three months. Because the bag comes with a two-year warranty, I contacted the company. A representative acknowledged the defect immediately and sent me a new bag within a week at no charge.\n\nAt $89, it is not the most economical choice, but the quality and the service justify the price.","zh":"產品：Trekline Pro 15 筆電後背包\n評論者：Marcus Hall\n評分：5 顆星中的 4 顆星\n\n耐用的包包，但有一個弱點\n\n我每天都搭火車，所以需要一個能承受重物的包包。每天使用了六個月之後，我的 Trekline Pro 看起來還是幾乎全新。布料非常堅固，有襯墊的夾層在無數次擁擠的路程中保護了我的筆電。這個包包還能套在大多數行李箱的拉桿上，在機場時幫了大忙。\n\n我唯一不滿意的地方是前袋的拉鍊，用了大約三個月就壞了。因為包包有兩年保固，我就聯絡了公司。客服代表馬上承認這是瑕疵，並在一週內免費寄了一個新包包給我。\n\n售價 89 美元，不算是最划算的選擇，但以它的品質和服務來說，這個價錢很合理。","w":[646,695,571,620,522,703,629,684],"qs":[{"q":"What is the reviewer's overall opinion of the backpack?","o":["It is too heavy to carry on a train every day","It is the cheapest bag available","It is worth the price despite a flaw","It does not protect a laptop well"],"a":2,"k":"主旨題：結尾 'quality and the service justify the price'","n":[["太重，不適合每天搭車背","","文中說能 'bear a heavy load'，沒嫌太重"],["是市面上最便宜的包","","文中 'not the most economical choice'"],["有瑕疵但仍物有所值","","文中 'justify the price'，瑕疵是拉鍊"],["無法妥善保護筆電","","文中 'has protected my laptop'，相反"]]},{"q":"What happened after the reviewer reported the broken zipper?","o":["He paid to have the zipper repaired","He was told the warranty had ended","He received a new bag for free","He was given a refund of $89"],"a":2,"k":"細節題：找拉鍊後續 → 'sent me a new bag ... at no charge'","n":[["他付費修理拉鍊","","公司寄新包且免費，沒提修理"],["被告知保固已結束","","文中有 'two-year warranty'，仍在保固內"],["他免費收到新包","","文中 'a new bag ... at no charge'"],["獲得 89 美元退款","","文中是寄新包，不是退款"]]},{"q":"The word \"bear\" in the review is closest in meaning to","o":["avoid","support","measure","reduce"],"a":1,"k":"字義題：'bear a heavy load' → 承受，即 support","n":[["(v.) 避免","","需求是承重，不是避開重物"],["(v.) 承受；支撐","","'bear a heavy load' 即承受重量"],["(v.) 測量","","包包不是用來量重物，語意不通"],["(v.) 減少","","包包無法減少重量，語意不通"]]}]},
{"id":"r800-10","lv":800,"p":7,"k":"form","ti":"Order confirmation CK-30977","tx":"Corwin Kitchen Supply\nORDER CONFIRMATION\n\nOrder number: CK-30977\nOrder date: August 14\nCustomer: Sunrise Café (wholesale account)\nContact: Ms. Priya Nair\n\nItems:\n1 commercial dishwasher, model D-400: $2,150\n2 steel work tables at $190 each: $380\nInstallation service: $120\nTotal: $2,650\n\nPayment: An invoice will be sent after delivery and is due within 30 days.\nEstimated delivery: August 21, between 8:00 A.M. and noon\n\nNotes:\nThe dishwasher is covered by a three-year warranty on all components. Installation will be carried out on the day of delivery by one of our technicians and takes about two hours. Please ensure that a staff member is onsite to sign for the goods. To modify this order, notify us at least 48 hours prior to delivery.","zh":"Corwin Kitchen Supply\n訂單確認單\n\n訂單編號：CK-30977\n訂購日期：8 月 14 日\n客戶：Sunrise Café（批發帳戶）\n聯絡人：Priya Nair 小姐\n\n品項：\n商用洗碗機 D-400 型 1 台：2,150 美元\n鋼製工作桌 2 張，每張 190 美元：380 美元\n安裝服務：120 美元\n合計：2,650 美元\n\n付款方式：發票將於送貨後寄出，請於 30 天內付款。\n預計送貨時間：8 月 21 日上午 8 點至中午 12 點之間\n\n備註：\n洗碗機的所有零件享有三年保固。安裝將於送貨當天由本公司技師進行，大約需要兩小時。請確保現場有員工可以簽收貨品。如需修改訂單，請在送貨前至少 48 小時通知我們。","w":[652,578,573,522,506,702,723,624],"qs":[{"q":"What is the purpose of this document?","o":["To confirm the details of a purchase","To request the repair of a dishwasher","To cancel a delivery","To advertise kitchen equipment"],"a":0,"k":"主旨題：標題 'ORDER CONFIRMATION' + 品項、金額、送貨","n":[["確認購買細節","","標題 'ORDER CONFIRMATION'，列出訂單內容"],["要求維修洗碗機","","只有保固說明，沒有維修請求"],["取消送貨","","文中是預定 August 21 送貨"],["宣傳廚房設備","","這是訂單確認，不是廣告"]]},{"q":"What should Sunrise Café make sure of on August 21?","o":["That the invoice has already been paid","That the café is closed all day","That it has hired its own technician","That an employee is there to sign"],"a":3,"k":"細節題：找送貨日 → 'ensure that a staff member is onsite'","n":[["發票已付清","","文中發票 'after delivery'，30 天內付款"],["咖啡廳整天休業","","只要求有人簽收，沒要求休業"],["已自行聘請技師","","安裝由 'one of our technicians' 負責"],["有員工在場簽收","","文中 'staff member is onsite to sign'"]]},{"q":"What is indicated about the installation?","o":["It will take place on the delivery day","It is free of charge","It must be done by café staff","It takes about 48 hours"],"a":0,"k":"細節題：找 Installation → 'on the day of delivery'","n":[["在送貨當天進行","","文中 'on the day of delivery'"],["免費","","文中 'Installation service: $120'，要收費"],["必須由咖啡廳員工安裝","","文中是 'one of our technicians'"],["約需 48 小時","","文中 'about two hours'；48 小時是改單期限"]]}]},
{"id":"r800-11","lv":800,"p":7,"k":"email","ti":"Interview for Operations Analyst position","tx":"To: Jason Kim\nFrom: Olivia Grant, Personnel Department, Vantor Logistics\nSubject: Interview for Operations Analyst position\n\nDear Mr. Kim,\n\nThank you for applying for the position of Operations Analyst. After reviewing more than 80 applications, we have determined that your background meets our criteria, and we would like to invite you to an interview at our headquarters on Tuesday, July 8, at 10:00 A.M.\n\nThe interview will last about one hour. You will meet Mr. Alan Ford, who supervises the distribution team, and you will be asked to analyze a short set of delivery data. No prior preparation is needed for this task.\n\nPlease bring a photo ID and the contact details of two references. If the date is not convenient, let me know by Friday and I will arrange an alternative time.\n\nWe look forward to meeting you.\n\nBest regards,\nOlivia Grant","zh":"收件人：Jason Kim\n寄件人：Olivia Grant，Vantor Logistics 人事部\n主旨：營運分析師職位面試\n\nKim 先生您好：\n\n感謝您應徵營運分析師一職。在審閱超過 80 份申請之後，我們認定您的背景符合我們的標準，因此想邀請您於 7 月 8 日星期二上午 10 點到本公司總部面試。\n\n面試時間大約一小時。您將與負責管理配送團隊的 Alan Ford 先生見面，並且需要分析一小組配送資料。這項作業不需要事先準備。\n\n請攜帶附照片的身分證件，以及兩位推薦人的聯絡資料。如果這個日期不方便，請在星期五之前告訴我，我會另外安排時間。\n\n期待與您見面。\n\n謹致問候\nOlivia Grant","w":[697,505,566,669,504,682,624,525],"qs":[{"q":"Why did Ms. Grant write to Mr. Kim?","o":["To invite him to a job interview","To offer him a position","To ask him to review applications","To tell him his application was rejected"],"a":0,"k":"主旨題：首段 'would like to invite you to an interview'","n":[["邀請他來面試","","文中 'invite you to an interview'"],["提供他職位","","目前只是邀請面試，尚未錄取"],["請他審閱申請書","","審閱申請書的是公司 'we'，不是他"],["通知他申請被拒","","文中 'meets our criteria'，條件符合"]]},{"q":"What will Mr. Kim be asked to do during the interview?","o":["Examine some delivery data","Tour the distribution center","Give a presentation about his background","Take a written language test"],"a":0,"k":"細節題：找面試內容 → 'analyze a short set of delivery data'","n":[["檢視一些配送資料","","文中 'analyze a short set of delivery data'"],["參觀配送中心","","文中沒提到參觀"],["簡報自己的背景","","文中沒要求簡報"],["參加書面語言測驗","","文中沒提語言測驗，任務是分析資料"]]},{"q":"What is suggested about the Operations Analyst position?","o":["Many people applied for it","It is a temporary job","It requires frequent travel","It is based overseas"],"a":0,"k":"推論題：'reviewing more than 80 applications' → 應徵者眾","n":[["很多人應徵","","文中 'more than 80 applications'"],["是臨時工作","","文中沒提任期或臨時性質"],["需要經常出差","","文中沒提出差"],["工作地點在海外","","面試在 headquarters，文中沒提海外"]]}]},
{"id":"r800-12","lv":800,"p":7,"k":"notice","ti":"Scheduled System Maintenance","tx":"IT NOTICE: Scheduled System Maintenance\n\nTo enhance network security, the IT Department will install a major software update this weekend. The work will begin at 10:00 P.M. on Saturday, March 14, and is expected to finish by 6:00 A.M. on Sunday.\n\nDuring this period, e-mail, the shared file server, and the customer database will not be available. Remote login to the company network will also be suspended. The telephone system will not be affected.\n\nPlease save your work and log out before you leave the office on Friday. It may not be possible to retrieve files that are left open during the update.\n\nWe chose these hours to keep downtime to a minimum and to avoid disrupting normal operations. If you detect any problems on Monday morning, notify the help desk at extension 310.","zh":"資訊部公告：系統定期維護\n\n為了加強網路安全，資訊部將於本週末安裝一項重大的軟體更新。作業將於 3 月 14 日星期六晚上 10 點開始，預計在星期日早上 6 點前完成。\n\n在這段期間，電子郵件、共用檔案伺服器和客戶資料庫都無法使用，遠端登入公司網路的功能也會暫停。電話系統不受影響。\n\n星期五離開辦公室之前，請先儲存您的工作並登出。更新期間仍開啟的檔案可能無法救回。\n\n我們選擇這個時段，是為了盡量縮短停機時間，避免打亂正常營運。如果您在星期一早上發現任何問題，請撥分機 310 通知服務台。","w":[708,575,683,735,585,728,685,725],"qs":[{"q":"What is the main purpose of the notice?","o":["To introduce a new e-mail program","To warn staff of a planned system outage","To report a recent security problem","To announce new office hours for the IT Department"],"a":1,"k":"主旨題：標題 'Scheduled System Maintenance' + 服務將中斷","n":[["介紹新的電子郵件程式","","e-mail 只是暫停服務之一，不是新程式"],["預告系統將按計畫中斷","","文中 'will not be available' 並事先提醒存檔"],["通報近期資安問題","","'enhance network security' 是更新目的，非事件"],["公布資訊部門新辦公時間","","文中沒提辦公時間"]]},{"q":"Which service will continue to work during the maintenance?","o":["The telephone system","E-mail","The shared file server","Remote login"],"a":0,"k":"細節題：找 not affected → 電話系統 'will not be affected'","n":[["電話系統","","文中 'will not be affected'"],["電子郵件","","文中 'will not be available'，無法使用"],["共用檔案伺服器","","文中 'will not be available'，無法使用"],["遠端登入","","文中 'will also be suspended'，暫停"]]},{"q":"Why did the IT Department choose these hours for the work?","o":["To reduce the cost of the software","To limit the effect on daily business","To allow staff to attend training","To meet a customer's request"],"a":1,"k":"細節題：找 'We chose these hours' → 'avoid disrupting'","n":[["降低軟體成本","","文中沒提成本"],["減少對日常業務的影響","","文中 'avoid disrupting normal operations'"],["讓員工參加訓練","","文中沒提訓練"],["配合客戶要求","","文中沒提客戶要求"]]}]},
{"id":"r800-13","lv":800,"p":7,"k":"memo","ti":"Fourth-floor renovation","tx":"MEMO\nTo: All fourth-floor staff\nFrom: George Whitman, Facilities Manager\nDate: January 6\nSubject: Fourth-floor renovation\n\nAs announced last month, the renovation of the fourth floor will be carried out in two phases.\n\nPhase 1 (January 20 to February 14): The east side will be closed. The marketing team will relocate temporarily to the conference rooms on the second floor.\n\nPhase 2 (February 17 to March 13): The west side will be closed, and the accounting team will move into the finished east side.\n\nThe old cubicles will be replaced with open desks, and two small meeting rooms will be added. Storage space will be limited during the transition, so please discard any documents you no longer need. Confidential papers must be placed in the locked bins beside the photocopier, not in the regular recycling.\n\nMoving boxes will be distributed on January 15. A detailed timeline is attached.","zh":"備忘錄\n收件人：四樓全體同仁\n寄件人：George Whitman，總務經理\n日期：1 月 6 日\n主旨：四樓整修\n\n如上個月所公告，四樓的整修工程將分兩個階段進行。\n\n第一階段（1 月 20 日至 2 月 14 日）：東側將關閉。行銷團隊將暫時搬到二樓的會議室。\n\n第二階段（2 月 17 日至 3 月 13 日）：西側將關閉，會計團隊將搬進已完工的東側。\n\n舊的辦公隔間將改為開放式辦公桌，並增設兩間小型會議室。過渡期間收納空間有限，請把不再需要的文件丟掉。機密文件必須放進影印機旁上鎖的回收箱，不可丟進一般的資源回收桶。\n\n搬家用的紙箱將於 1 月 15 日發放。詳細時程表如附件。","w":[563,549,717,568,548,701,643,583],"qs":[{"q":"What is the memo mainly about?","o":["The hiring of a facilities manager","A change in company ownership","New rules for booking conference rooms","A plan for remodeling part of an office"],"a":3,"k":"主旨題：主旨 'Fourth-floor renovation' + 'two phases'","n":[["聘任設施經理","","Whitman 只是寄件人，文中沒提徵人"],["公司易主","","文中沒提到所有權"],["會議室預約新規定","","會議室只是行銷團隊暫時借用"],["部分辦公室的整修計畫","","文中 'renovation ... in two phases'"]]},{"q":"Where will the marketing team work during Phase 1?","o":["On the east side of the fourth floor","On the second floor","On the west side of the fourth floor","In a building across the street"],"a":1,"k":"細節題：找 Phase 1 的 marketing team → 'second floor'","n":[["四樓東側","","文中第一階段東側關閉，不能待在那"],["二樓","","文中 'relocate temporarily to the ... second floor'"],["四樓西側","","文中說搬到二樓；西側是第二階段才關"],["對街的大樓","","文中沒提到別棟大樓"]]},{"q":"The word \"discard\" in the memo is closest in meaning to","o":["put in order","print out","sign","throw away"],"a":3,"k":"字義題：'discard any documents you no longer need' → 丟棄","n":[["整理好","","文中是不再需要的文件，不是整理"],["列印","","不需要的文件不會再列印，語意不通"],["簽名","","與「不再需要的文件」語意不通"],["丟棄","","文中 'discard documents you no longer need'"]]}]},
{"id":"r800-14","lv":800,"p":7,"k":"advertisement","ti":"Now Hiring: Sales Associate","tx":"NOW HIRING: Sales Associate\nDelmar Home Furnishings\n\nDelmar Home Furnishings, a family-owned corporation with 14 stores, is recruiting a full-time Sales Associate for its Kingsport branch.\n\nResponsibilities:\n- Help customers choose furniture that fits their needs and budget\n- Process transactions and arrange deliveries\n- Check showroom inventory every week\n\nRequirements:\n- An enthusiastic and reliable personality\n- Availability to work two Saturdays per month\n- Prior retail experience is beneficial but not essential. All new staff receive a one-week orientation.\n\nWe offer a competitive salary plus commission on every sale, as well as paid vacation and a staff discount. Associates become eligible for health insurance coverage after three months.\n\nTo apply, send your résumé and the names of two references to our Personnel Department by October 31.","zh":"徵才：銷售人員\nDelmar Home Furnishings\n\nDelmar Home Furnishings 是一家擁有 14 家門市的家族企業，現正為 Kingsport 分店招募一名全職銷售人員。\n\n工作內容：\n- 協助顧客挑選符合需求和預算的家具\n- 處理交易並安排送貨\n- 每週清點展示間的庫存\n\n應徵條件：\n- 個性熱忱、可靠\n- 每個月可配合兩個星期六上班\n- 有零售業經驗者佳，但並非必要。所有新進員工都會接受為期一週的新進人員訓練。\n\n我們提供具競爭力的薪資，每筆銷售另有佣金，並享有有薪假和員工折扣。到職滿三個月後即可享有健康保險。\n\n意者請於 10 月 31 日前，將履歷及兩位推薦人的姓名寄至本公司人事部。","w":[559,664,507,632,633,516,530,608],"qs":[{"q":"What position is being advertised?","o":["A furniture designer","A store manager","A delivery driver","A salesperson at a furniture store"],"a":3,"k":"主旨題：標題 'Sales Associate' + 'Help customers choose furniture'","n":[["家具設計師","","文中沒徵設計師，工作是協助顧客選購"],["店長","","文中徵的是 Sales Associate，不是店長"],["送貨司機","","只是 'arrange deliveries'，安排送貨而非開車"],["家具店銷售人員","","文中 'Sales Associate'，協助顧客選家具"]]},{"q":"What is stated about previous retail experience?","o":["It is helpful but not required","It replaces the orientation","It is required for all applicants","It must be at least one year long"],"a":0,"k":"細節題：找 retail experience → 'beneficial but not essential'","n":[["有幫助但非必要","","文中 'beneficial but not essential'"],["可取代新進訓練","","文中 'All new staff receive' 一週訓練"],["所有應徵者都必須有","","文中 'not essential'，並非必要"],["至少要一年","","文中沒規定經驗年資"]]},{"q":"What is NOT mentioned as a benefit of the job?","o":["A discount for staff","A company car","Paid vacation","Commission on sales"],"a":1,"k":"NOT 題：逐項找福利 → 佣金、休假、折扣都有，公司車沒有","n":[["員工折扣","","有提到：'a staff discount'"],["公司配車","","其他三項都有，文中沒提公司車"],["有薪假","","有提到：'paid vacation'"],["銷售佣金","","有提到：'commission on every sale'"]]}]},
{"id":"r800-15","lv":800,"p":7,"k":"message","ti":"Flight delay and the Ellis meeting","tx":"Nina Petrov (2:05 P.M.): Bad news, Tom. My flight to Denver has been delayed three hours because of a safety inspection. I won't reach the client's office before 6:00.\nTom Becker (2:08 P.M.): That's a problem. The contract review with Ellis Corporation is at 4:30.\nNina Petrov (2:09 P.M.): Could you conduct the meeting without me? You know the proposal as well as I do.\nTom Becker (2:12 P.M.): I can outline the pricing, but they will want you to clarify the warranty clause. What if I ask them to move the meeting to tomorrow morning?\nNina Petrov (2:13 P.M.): Good idea. I'm free until 11:00.\nTom Becker (2:25 P.M.): Done. Their representative agreed to 9:00 A.M. tomorrow. She says that time actually suits them better.\nNina Petrov (2:26 P.M.): I'm so relieved. Thanks for resolving that so quickly.","zh":"Nina Petrov（下午 2:05）：Tom，壞消息。我飛往丹佛的班機因為安全檢查延誤了三個小時，6 點以前到不了客戶的辦公室。\nTom Becker（下午 2:08）：這下麻煩了。和 Ellis Corporation 的合約審閱會議是 4 點半。\nNina Petrov（下午 2:09）：你可以自己主持會議嗎？這份提案你跟我一樣熟。\nTom Becker（下午 2:12）：價格的部分我可以大致說明，但他們會希望由你來把保固條款講清楚。我請他們把會議改到明天早上怎麼樣？\nNina Petrov（下午 2:13）：好主意。我 11 點以前都有空。\nTom Becker（下午 2:25）：搞定了。對方的代表同意改到明天早上 9 點。她說那個時間其實對他們更方便。\nNina Petrov（下午 2:26）：我鬆了一口氣。謝謝你這麼快就解決了。","w":[738,710,602,671,522,586,722,678],"qs":[{"q":"What problem does Ms. Petrov report?","o":["She lost a contract","Her flight is behind schedule","A client rejected a proposal","Her hotel reservation was canceled"],"a":1,"k":"細節題：Petrov 首句 'flight ... has been delayed three hours'","n":[["她丟了合約","","合約審閱會議只是改期，沒說丟掉"],["她的班機延誤","","文中 'flight ... has been delayed three hours'"],["客戶拒絕了提案","","文中沒提拒絕"],["她的飯店訂房被取消","","文中沒提飯店"]]},{"q":"When will the meeting with Ellis Corporation now take place?","o":["At 4:30 P.M. today","At 6:00 P.M. today","At 9:00 A.M. tomorrow","At 11:00 A.M. tomorrow"],"a":2,"k":"細節題：找最後改期 → 'agreed to 9:00 A.M. tomorrow'","n":[["今天下午 4:30","","4:30 是原定時間，已改期"],["今天下午 6:00","","6:00 是她最快抵達客戶辦公室的時間"],["明天上午 9:00","","文中 'agreed to 9:00 A.M. tomorrow'"],["明天上午 11:00","","11:00 是她明早有空到幾點，非開會時間"]]},{"q":"Why does Mr. Becker suggest changing the meeting time?","o":["He is unable to describe the pricing","He has another meeting at 4:30","The client will want Ms. Petrov to explain a clause","He has not had enough time to read the whole proposal"],"a":2,"k":"細節題：Becker 說 'they will want you to clarify'","n":[["他無法說明價格","","他說 'I can outline the pricing'，能說明"],["他 4:30 另有會議","","文中沒提他另有會議"],["客戶會要 Petrov 說明條款","","文中 'want you to clarify the warranty clause'"],["他沒時間讀完提案","","Petrov 說 'You know the proposal'，沒提時間不足"]]}]},
{"id":"r800-16","lv":800,"p":7,"k":"article","ti":"Factory Cuts Electricity Use by a Fifth","tx":"Factory Cuts Electricity Use by a Fifth\n\nGREENFIELD — Halden Plastics, which manufactures food containers, has reduced its electricity consumption by 20 percent in one year, the company revealed on Tuesday.\n\nThe savings came from three measures. First, the firm replaced its old lighting with LED lamps. Second, it installed sensors that monitor each machine and switch it off automatically when it is not in use. Finally, solar panels on the roof now generate about a tenth of the plant's power.\n\nOperations manager Rita Collins acknowledged that the initial investment of $400,000 was significant. \"It was hard to justify at first,\" she said, \"but the project will pay for itself in four years.\"\n\nHalden intends to implement the same strategy at its second plant next spring. Ms. Collins added that greater efficiency has also enhanced the company's reputation among its customers.","zh":"工廠用電量減少五分之一\n\nGREENFIELD 訊 — 生產食品容器的 Halden Plastics 星期二透露，該公司在一年內把用電量減少了 20%。\n\n節省下來的電力來自三項措施。第一，公司把舊的照明設備換成 LED 燈。第二，安裝感應器監控每一台機器，機器沒有使用時會自動關閉。最後，屋頂上的太陽能板現在可以產生工廠大約十分之一的電力。\n\n營運經理 Rita Collins 坦承，40 萬美元的初期投資金額相當可觀。她說：「一開始很難說明這筆錢為什麼值得花，但這項計畫四年就能回本。」\n\nHalden 打算明年春天在第二座工廠實施同樣的策略。Collins 女士還說，效率提升也提高了公司在顧客心中的聲譽。","w":[739,535,687,599,736,668,684,676],"qs":[{"q":"What is the article mainly about?","o":["The opening of a new factory","A rise in the price of plastic containers","A shortage of solar panels","A company's cut in electricity use"],"a":3,"k":"主旨題：標題 'Cuts Electricity Use by a Fifth' + 首段","n":[["新工廠開幕","","文中是既有工廠省電，第二廠只是未來計畫"],["塑膠容器價格上漲","","文中沒提價格"],["太陽能板短缺","","文中沒提短缺，太陽能板已裝設"],["公司減少用電","","文中 'reduced its electricity consumption'"]]},{"q":"How much of the plant's power comes from the solar panels?","o":["About one-half","About one-fifth","About one-tenth","Nearly all of it"],"a":2,"k":"細節題：找 solar panels → 'about a tenth of the plant's power'","n":[["約二分之一","","文中是 a tenth，不是一半"],["約五分之一","","20% 是整體節電幅度，不是太陽能占比"],["約十分之一","","文中 'about a tenth of the plant's power'"],["幾乎全部","","文中只占十分之一"]]},{"q":"What is NOT one of the measures the company took?","o":["Buying new production machines","Installing sensors on machines","Changing the lighting","Adding solar panels"],"a":0,"k":"NOT 題：三項措施 → LED、感應器、太陽能；沒有買新機器","n":[["購買新的生產機器","","三項措施中沒有這一項"],["在機器上裝感應器","","有提到：'installed sensors'"],["更換照明","","有提到：'replaced its old lighting with LED'"],["增設太陽能板","","有提到：'solar panels on the roof'"]]}]},
{"id":"r800-17","lv":800,"p":7,"k":"letter","ti":"Replacement for your AirPure 200","tx":"Solvane Appliances\nCustomer Care Department\n\nNovember 3\n\nMs. Grace Huang\n77 Cedar Avenue\n\nDear Ms. Huang,\n\nThank you for returning your Solvane AirPure 200 air purifier to us. Our technicians have completed their inspection and determined that the fan motor was defective when it left the factory. We sincerely apologize.\n\nAs your purchase is still under warranty, you will not bear any cost. Unfortunately, the AirPure 200 is no longer manufactured, so we cannot send you an identical unit. As a substitute, we will ship you the AirPure 300, a newer model of equivalent size with a quieter motor. It should reach you within five business days.\n\nTo compensate you for the inconvenience, we have enclosed a voucher for two free filters, which can be redeemed at any Solvane store.\n\nSincerely,\nVictor Almeida\nCustomer Care Manager","zh":"Solvane Appliances\n客戶服務部\n\n11 月 3 日\n\nGrace Huang 小姐\nCedar Avenue 77 號\n\n黃小姐您好：\n\n感謝您將 Solvane AirPure 200 空氣清淨機寄回給我們。我們的技術人員已完成檢查，確定風扇馬達在出廠時就有瑕疵。我們誠摯地向您致歉。\n\n由於您購買的產品仍在保固期內，您不需要負擔任何費用。可惜 AirPure 200 已經停產，我們無法寄給您一模一樣的機型。作為替代，我們會寄給您 AirPure 300，這是比較新的機型，大小相同，馬達更安靜。應該會在五個工作天內送達。\n\n為了補償造成您的不便，我們隨信附上一張可兌換兩個免費濾網的兌換券，在任何一家 Solvane 門市都可以兌換。\n\n敬上\nVictor Almeida\n客戶服務部經理","w":[697,616,522,695,743,651,674,693],"qs":[{"q":"What is the purpose of the letter?","o":["To promote a new line of filters","To explain how a problem will be fixed","To refuse a warranty claim","To ask a customer to send back a broken item"],"a":1,"k":"主旨題：'we will ship you the AirPure 300' → 說明處理方式","n":[["推銷新系列濾網","","濾網券只是補償，不是推銷"],["說明問題如何解決","","文中 'we will ship you the AirPure 300'"],["拒絕保固申請","","文中 'still under warranty'，不收費"],["請顧客寄回壞掉的商品","","她已寄回：'Thank you for returning'"]]},{"q":"Why will Ms. Huang receive a different model?","o":["She asked for a quieter machine","Her warranty has expired","The original model is no longer made","The newer model costs less"],"a":2,"k":"細節題：找換機型的原因 → 'no longer manufactured'","n":[["她要求更安靜的機器","","更安靜是新機型特點，不是她的要求"],["她的保固已過期","","文中 'still under warranty'"],["原機型已停產","","文中 'no longer manufactured'"],["新機型比較便宜","","文中沒提價格比較"]]},{"q":"What is suggested about the AirPure 300?","o":["Ms. Huang must pay extra for it","It is much larger than the AirPure 200","It is quieter than the AirPure 200","It will arrive the next day"],"a":2,"k":"推論題：找 AirPure 300 → 'newer model ... with a quieter motor'","n":[["Huang 女士須補差額","","文中 'you will not bear any cost'"],["比 AirPure 200 大很多","","文中 'equivalent size'，尺寸相當"],["比 AirPure 200 安靜","","文中 'a quieter motor'"],["隔天送達","","文中是 'within five business days'"]]}]},
{"id":"r800-18","lv":800,"p":7,"k":"announcement","ti":"Lakeshore Small Business Expo: Call for Vendors","tx":"Lakeshore Small Business Expo: Call for Vendors\n\nThe Lakeshore Business Association will hold its tenth annual Small Business Expo on Saturday, September 19, at Pier Hall. Last year's event attracted more than 3,000 visitors, and we expect an even larger crowd this year thanks to a publicity campaign on local radio.\n\nLocal vendors are invited to reserve a booth to display their products and distribute samples. A booth costs $150, which includes a table, two chairs, electricity, and a listing in the printed event directory. Because space is limited to 80 booths, applications will be accepted in the order they arrive.\n\nNew this year: three free seminars on topics such as online marketing and financial planning.\n\nTo apply, submit the form on our website with your payment by August 15. No refunds will be granted after September 1.","zh":"Lakeshore 小型企業博覽會：攤商招募\n\nLakeshore 商業協會將於 9 月 19 日星期六在 Pier Hall 舉辦第十屆年度小型企業博覽會。去年的活動吸引了超過 3,000 名訪客，今年由於在地方電台進行宣傳活動，我們預期人潮會更多。\n\n歡迎在地商家預訂攤位，展示產品並發送試用品。每個攤位 150 美元，包含一張桌子、兩張椅子、電力，以及在活動紙本名錄上刊登資訊。由於場地僅能容納 80 個攤位，將依照申請送達的先後順序受理。\n\n今年新增：三場免費研討會，主題包括網路行銷和財務規劃等。\n\n報名請於 8 月 15 日前，在我們的網站上提交表單並完成付款。9 月 1 日之後恕不退費。","w":[540,512,577,720,584,538,644,737],"qs":[{"q":"What is the purpose of the announcement?","o":["To report a change of venue","To invite businesses to join an event","To find speakers for seminars","To thank visitors who came last year"],"a":1,"k":"主旨題：標題 'Call for Vendors' → 邀請商家參展","n":[["通知場地變更","","文中沒提場地變更"],["邀請業者參加活動","","文中 'Local vendors are invited to reserve a booth'"],["徵求研討會講者","","文中只預告三場研討會，沒徵講者"],["感謝去年的訪客","","去年人數只是背景資訊"]]},{"q":"What is included in the booth fee?","o":["A listing in the event directory","A parking space","Lunch for two people at the booth","Advertising on local radio"],"a":0,"k":"細節題：找 booth fee → 'a listing in the printed event directory'","n":[["活動名錄中的刊登","","文中 'a listing in the printed event directory'"],["一個停車位","","攤位費只含桌椅、電力、名錄"],["兩人的午餐","","文中沒提午餐"],["當地廣播廣告","","廣播是主辦方的宣傳，不含在攤位費"]]},{"q":"What is suggested about booth applications?","o":["They must include product samples","They are accepted until the day of the expo, September 19","They cost nothing before August 15","Early applicants are more likely to get a booth"],"a":3,"k":"推論題：'accepted in the order they arrive' + 名額有限","n":[["申請須附產品樣品","","文中申請要填表單並付款，沒要樣品"],["受理到 9 月 19 日當天","","文中申請截止是 August 15"],["8 月 15 日前免費","","申請時要 'with your payment'"],["早申請者較可能拿到攤位","","'limited to 80 booths'，依 'order they arrive'"]]}]},
{"id":"r800-19","lv":800,"p":7,"k":"review","ti":"Venue Review: Elmwood Conference Center","tx":"Venue Review: Elmwood Conference Center\nPosted by: Sandra Kowalski, Event Coordinator\nRating: 3 out of 5\n\nWe held our annual sales seminar at Elmwood last month for 150 employees. The main hall was spacious and well equipped, and the onsite technician resolved a projector problem within minutes. The catering was excellent too. The lunch buffet offered numerous choices, and nothing ran out.\n\nHowever, there were two significant problems. Parking was insufficient. The lot has only 60 spaces, so many of our staff had to park several blocks away. In addition, the air conditioning in the smaller workshop rooms was not adequate for a hot afternoon, and several participants complained.\n\nThe manager apologized and deducted 10 percent from our invoice, which I appreciated. I would consider Elmwood again for a smaller group, but it is not suitable for an event of our scale.","zh":"場地評論：Elmwood Conference Center\n發文者：Sandra Kowalski，活動統籌\n評分：5 分中的 3 分\n\n上個月我們在 Elmwood 為 150 名員工舉辦了年度業務研討會。主廳寬敞、設備齊全，駐場的技術人員幾分鐘內就解決了投影機的問題。外燴也很出色，午餐自助餐的選擇很多，而且沒有任何一道菜不夠。\n\n不過，有兩個重大的問題。停車位不足，停車場只有 60 個車位，所以我們很多同仁必須把車停在好幾個街區之外。此外，較小的幾間研習教室冷氣不夠強，應付不了炎熱的下午，有好幾位參加者抱怨。\n\n經理向我們道歉，並從發票金額中扣除了 10%，這一點我很感謝。如果是人數比較少的團體，我會考慮再選 Elmwood，但它並不適合我們這種規模的活動。","w":[655,678,576,612,636,613,691,527],"qs":[{"q":"What does the reviewer conclude about the venue?","o":["It is ideal for large companies","It should change its catering company","It is better suited to smaller events","It charges too much for parking"],"a":2,"k":"推論題：結尾 'for a smaller group, but ... not suitable'","n":[["很適合大公司","","文中 'not suitable for an event of our scale'"],["應該換餐飲業者","","文中 'The catering was excellent'"],["較適合小型活動","","文中 'consider Elmwood again for a smaller group'"],["停車費太貴","","問題是車位不足，文中沒提收費"]]},{"q":"What problem did the group have with parking?","o":["The fee was too high","The entrance was hard to find","There were too few spaces","The lot was closed for repairs"],"a":2,"k":"細節題：找 Parking → 'only 60 spaces'","n":[["費用太高","","文中沒提停車費"],["入口難找","","文中沒提入口"],["車位太少","","文中 'Parking was insufficient' 與 'only 60 spaces'"],["停車場因維修關閉","","文中沒提維修，停車場有開放"]]},{"q":"What does the reviewer NOT praise?","o":["The main hall","The food","The technical support","The air conditioning"],"a":3,"k":"NOT 題：稱讚的有大廳、技術人員、餐點；冷氣是抱怨","n":[["主廳","","有稱讚：'spacious and well equipped'"],["餐點","","有稱讚：'The catering was excellent'"],["技術支援","","有稱讚：技師 'within minutes' 解決投影機問題"],["空調","","文中 'not adequate'，是抱怨不是稱讚"]]}]},
{"id":"r800-20","lv":800,"p":7,"k":"form","ti":"Staff Development Day: Schedule","tx":"Northfield Retail Group\nStaff Development Day: Schedule\nFriday, October 9, Head Office, Room 3\n\n8:30 Registration and coffee\n9:00 Overview of this year's results (Diane Foster, Operations Director)\n9:30 Workshop: Resolving customer disputes (Paul Jensen)\n11:00 Break\n11:15 Seminar: Our online sales strategy (Maria Santos)\n12:30 Lunch (catering provided)\n1:30 Workshop: Keeping accurate inventory records (Paul Jensen)\n3:00 Closing remarks (Diane Foster)\n\nNotes:\nAttendance is mandatory for all branch managers. Assistant managers are welcome to attend if their branch has adequate staff coverage on that day. If you have special meal requirements, please notify Ms. Foster's office by October 2. Handouts will be distributed at registration. Parking is available behind the building, but spaces are limited, so please share a car if possible.","zh":"Northfield Retail Group\n員工進修日：議程表\n10 月 9 日星期五，總公司 3 號會議室\n\n8:30 報到及咖啡時間\n9:00 本年度業績概述（營運總監 Diane Foster）\n9:30 工作坊：化解顧客糾紛（Paul Jensen）\n11:00 休息\n11:15 研討會：我們的線上銷售策略（Maria Santos）\n12:30 午餐（提供外燴）\n1:30 工作坊：維持正確的庫存紀錄（Paul Jensen）\n3:00 結語（Diane Foster）\n\n備註：\n所有分店經理都必須出席。副理若所屬分店當天人手充足，也歡迎參加。如有特殊餐點需求，請於 10 月 2 日前通知 Foster 女士的辦公室。講義將在報到時發放。大樓後方可以停車，但車位有限，請盡量共乘。","w":[567,598,534,642,587,639,613,515],"qs":[{"q":"What kind of document is this?","o":["A program for a training day","A list of job openings","A report on sales results","A menu for a company lunch"],"a":0,"k":"主旨題：標題 'Staff Development Day: Schedule' + 時間表","n":[["培訓日的活動議程","","標題 'Staff Development Day: Schedule'"],["職缺清單","","文中沒有徵才"],["銷售成果報告","","成果概述只是議程中的一個時段"],["公司午餐菜單","","午餐只有一行 'catering provided'"]]},{"q":"Who will lead the session on inventory records?","o":["Maria Santos","Paul Jensen","Diane Foster","A branch manager"],"a":1,"k":"細節題：查時間表 1:30 → 'inventory records (Paul Jensen)'","n":[["人名：Maria Santos","","她主講的是線上銷售策略研討會"],["人名：Paul Jensen","","1:30 場次寫 'inventory records (Paul Jensen)'"],["人名：Diane Foster","","她負責成果概述與閉幕致詞"],["分店經理","","分店經理是與會者，不是講者"]]},{"q":"What is suggested about assistant managers?","o":["They must bring their own lunch","They will lead a workshop","They can come if their store has enough staff","They are required to attend both workshops and the seminar"],"a":2,"k":"推論題：找 Assistant managers → 'welcome to attend if ...'","n":[["必須自備午餐","","文中 'catering provided'，有供餐"],["他們將主持工作坊","","兩場工作坊都由 Paul Jensen 主持"],["店內人手足夠就可參加","","文中 'welcome ... adequate staff coverage'"],["必須參加所有場次","","只有 branch managers 是 mandatory"]]}]},
{"id":"r800-21","lv":800,"p":6,"k":"email","ti":"Your subscription ends soon","tx":"To: Henry Clark\nFrom: Member Services, Business Insight Weekly\nSubject: Your subscription ends soon\n\nDear Mr. Clark,\n\nYour subscription to Business Insight Weekly will end on June 30. To continue receiving the publication without interruption, please [1] ------- your subscription before that date.\n\nAs a loyal reader, you are [2] ------- for an exclusive rate of $79 per year, 20 percent off the regular price. You will also keep full access to our online library, which contains more than ten years of articles and market analysis.\n\nThe process is simple. Visit our website, enter the customer number shown above, and choose a payment method. [3] -------, you may call a customer representative at 555-0199 on weekdays between 9:00 A.M. and 5:00 P.M.\n\nThank you for your continued support.\n\nMember Services","zh":"收件人：Henry Clark\n寄件人：Business Insight Weekly 會員服務部\n主旨：您的訂閱即將到期\n客戶編號：20417\n\nClark 先生您好：\n\n您訂閱的 Business Insight Weekly 將於 6 月 30 日到期。為了讓您不間斷地收到本刊，請在該日期之前續訂。\n\n身為忠實讀者，您有資格享有每年 79 美元的專屬優惠價，比原價省下 20%。您也可以繼續完整使用我們的線上資料庫，裡面收錄了十多年來的文章和市場分析。\n\n手續很簡單：請上我們的網站，輸入上方所示的客戶編號，再選擇付款方式即可。或者，您也可以在週一至週五上午 9 點至下午 5 點之間，撥 555-0199 與客服代表聯絡。\n\n感謝您長期的支持。\n\n會員服務部","w":[565,724,608,630,543,511],"qs":[{"q":"[1]","o":["renew","duplicate","suspend","decline"],"a":0,"k":"單字：目的是 continue receiving → 到期前續訂 renew","n":[["(v.) 續訂；更新","renew a subscription","訂閱將到期，要繼續收到就得續訂"],["(v.) 複製","","語意不通：訂閱不能被複製"],["(v.) 暫停","","與 'continue receiving' 的目的相反"],["(v.) 拒絕；下降","","語意不通：與要繼續收到相反"]]},{"q":"[2]","o":["capable","available","eligible","mandatory"],"a":2,"k":"單字：are ___ for an exclusive rate → be eligible for","n":[["(adj.) 有能力的","be capable of + V-ing","搭配的是 of，不是 for；語意也不合"],["(adj.) 可取得的；有空的","","文法可以，但「你有空享優惠價」語意不通"],["(adj.) 有資格的","be eligible for + N","忠實讀者有資格享有優惠價"],["(adj.) 強制的","","語意不通：優惠價不是強制的"]]},{"q":"[3]","o":["Alternatively","Nevertheless","Therefore","For example"],"a":0,"k":"連接詞：前句上網辦理、後句改打電話 → 另一種方式 Alternatively","n":[["(adv.) 或者","Alternatively, + 句子","在上網辦理之外，提供電話這另一種方式"],["(adv.) 然而","","前後沒有讓步轉折，語意不合"],["(adv.) 因此","","打電話不是上網辦理的結果，不是因果"],["例如","","打電話不是上網辦理的例子"]]}]},
{"id":"r800-22","lv":800,"p":6,"k":"notice","ti":"Parking Lot B closed August 3 to 7","tx":"NOTICE: Parking Lot B Closed August 3 to 7\nPosted July 27\n\nParking Lot B, behind the main building, [1] ------- from Monday, August 3, to Friday, August 7, while the surface is repaired and new lines are painted. For safety reasons, entry to the area will be restricted to construction personnel.\n\nDuring this period, employees who normally use Lot B should park in Lot D on Franklin Street. A free shuttle bus will run between Lot D and the main entrance every fifteen minutes from 7:00 A.M. to 7:00 P.M. [2] -------\n\nPlease ensure that your vehicle is moved by 8:00 P.M. on Sunday, August 2. Any vehicles remaining after that time will be removed at the owner's expense.\n\nWe apologize for the [3] ------- and thank you for your cooperation. For further information, call extension 250.\n\nFacilities Department","zh":"公告：B 停車場 8 月 3 日至 7 日關閉\n公告日期：7 月 27 日\n\n主大樓後方的 B 停車場將於 8 月 3 日星期一至 8 月 7 日星期五關閉，以便修補路面並重新劃線。基於安全考量，該區域僅限施工人員進入。\n\n在這段期間，平常使用 B 停車場的員工請改停 Franklin Street 上的 D 停車場。免費接駁車將於上午 7 點至晚上 7 點之間，每十五分鐘一班，往返 D 停車場和大門口。或者，從 D 停車場走路過來大約十分鐘。\n\n請確保在 8 月 2 日星期日晚上 8 點前把車移走。逾時仍未移走的車輛將予以拖吊，費用由車主負擔。\n\n造成不便，敬請見諒，並感謝您的配合。如需進一步資訊，請撥分機 250。\n\n總務部","w":[670,528,702,580,653],"qs":[{"q":"[1]","o":["has been closed","was closing","will be closed","closing"],"a":2,"k":"時態／語態：公告 July 27、關閉在 8/3 → 未來被動","n":[["已經被關閉（現在完成式）","","時態不合：關閉在 8/3 才開始，尚未發生"],["當時正在關閉（過去進行式）","","時態不合：關閉是未來的事"],["將被關閉","will be + p.p.","未來事件，停車場是被關閉，用未來被動"],["關閉中","","缺助動詞，不能單獨當述語"]]},{"q":"[2]","o":["As a result, Lot D will also be closed that week.","Therefore, employees must pay the bus fare in cash.","Thank you for attending the opening ceremony.","Alternatively, the walk from Lot D takes about ten minutes."],"a":3,"k":"句子插入：前句提供免費接駁 → 補充另一種到達方式","n":[["因此，Lot D 當週也會關閉。","","矛盾：Lot D 是要員工改停的替代停車場"],["因此，員工須以現金付車資。","","矛盾：前句說接駁車是免費的"],["感謝您參加開幕典禮。","","與停車場公告無關"],["或者，從 Lot D 步行約十分鐘。","","接在接駁車之後，補充另一種方式"]]},{"q":"[3]","o":["precaution","inconvenience","compensation","circumstance"],"a":1,"k":"單字：apologize for the ___ → inconvenience","n":[["(n.) 預防措施","","道歉是為造成的麻煩，不是為預防措施"],["(n.) 不便","apologize for the inconvenience","公告常用的固定說法"],["(n.) 補償","","語意不通：不會為「補償」道歉"],["(n.) 情況","","文法可以，但道歉針對造成的麻煩，非泛指「情況」"]]}]},
{"id":"r800-23","lv":800,"p":6,"k":"memo","ti":"Annual performance reviews","tx":"MEMO\nTo: All department managers\nFrom: Susan Miller, Personnel Director\nSubject: Annual performance reviews\n\nThis year's performance reviews will be [1] ------- between November 2 and November 20. Each manager is expected to meet individually with every member of his or her team for about 45 minutes.\n\nBefore the meeting, ask each employee to complete the self-evaluation form, which is available on the company intranet. During the meeting, discuss the past year's results and agree on three [2] ------- objectives for next year, such as a sales figure or a completion date. Goals that are too general are difficult to measure.\n\nAll completed forms must reach my office by November 27. [3] ------- salary increases are based on these reviews, late forms may delay the changes to your team's pay.\n\nThank you for your cooperation.","zh":"備忘錄\n收件人：各部門經理\n寄件人：Susan Miller，人事總監\n主旨：年度績效考核\n\n今年的績效考核將於 11 月 2 日至 11 月 20 日之間進行。每位經理都應該和團隊的每一位成員個別面談，每次大約 45 分鐘。\n\n面談之前，請每位員工先填寫自我評量表，表單可在公司內部網路取得。面談時，請討論過去一年的成果，並共同訂出明年的三個具體目標，例如業績數字或完成日期。太籠統的目標很難衡量。\n\n所有填妥的表單必須在 11 月 27 日前送達我的辦公室。由於調薪是以這些考核為依據，表單遲交可能會延誤貴團隊的薪資調整。\n\n感謝您的配合。","w":[528,738,710,645,541,599],"qs":[{"q":"[1]","o":["conducted","consulted","conveyed","consumed"],"a":0,"k":"單字：reviews 為主詞 + 期間內 → conduct 進行","n":[["(v.) 進行；實施","conduct a review / survey","reviews 被進行，固定搭配"],["(v.) 諮詢","","考核不是被「諮詢」，語意不通"],["(v.) 傳達","","考核不是被「傳達」，語意不通"],["(v.) 消耗","","語意不通：考核不能被消耗"]]},{"q":"[2]","o":["concrete","artificial","defective","overdue"],"a":0,"k":"單字：後文 too general 難衡量 → 要 concrete 具體的目標","n":[["(adj.) 具體的","concrete objectives","如 sales figure，與 'too general' 相對"],["(adj.) 人造的","","語意不通：目標不是人造的"],["(adj.) 有缺陷的","","語意不通：用於瑕疵產品，不是目標"],["(adj.) 逾期的","","明年的目標還沒到期，語意矛盾"]]},{"q":"[3]","o":["Although","Whether","Because","Unless"],"a":2,"k":"連接詞：前半是原因、後半是結果 → 因果，用 Because","n":[["(conj.) 雖然","","前後不是讓步：薪資依考核，所以逾期會延誤"],["(conj.) 是否","","Whether 是「是否／不論」，放句首語意不通"],["(conj.) 因為","Because + 子句, 主要子句","薪資依考核調整，所以表格逾期會延誤"],["(conj.) 除非","","語意不通：沒有「除非…」的條件關係"]]}]},
{"id":"r800-24","lv":800,"p":6,"k":"letter","ti":"Grant for the Riverside Youth Music Program","tx":"Clearwater Community Foundation\n45 Bridge Street\n\nFebruary 10\n\nMs. Elena Vargas\nDirector, Riverside Youth Music Program\n\nDear Ms. Vargas,\n\nOn behalf of the Clearwater Community Foundation, I am delighted to inform you that your program [1] ------- a grant of $15,000 for the coming year.\n\nOur committee received 62 applications and evaluated each one against strict criteria. Your proposal stood out because of its clear budget and its strong [2] ------- to offering free lessons to local children.\n\nThe funds will be transferred in two installments, in March and September. [3] ------- the second payment, we ask that you submit a short report by August 15 describing how the first half of the grant was used.\n\nCongratulations. We look forward to hearing about your progress.\n\nSincerely,\nThomas Reed\nChair, Grants Committee","zh":"Clearwater Community Foundation\nBridge Street 45 號\n\n2 月 10 日\n\nElena Vargas 女士\nRiverside Youth Music Program 主任\n\nVargas 女士您好：\n\n謹代表 Clearwater Community Foundation 很高興地通知您，貴計畫已獲得下一年度 15,000 美元的補助金。\n\n本會委員會共收到 62 份申請，並依照嚴格的標準逐一評估。您的提案之所以脫穎而出，是因為預算清楚，而且對於為在地兒童提供免費課程有很深的投入。\n\n補助款將分兩期撥付，分別在三月和九月。在撥付第二期款項之前，請您於 8 月 15 日前提交一份簡短的報告，說明前半筆補助金的使用情形。\n\n恭喜您。期待聽到您的進展。\n\n敬上\nThomas Reed\n補助委員會主席","w":[508,737,679,505,500,542,624],"qs":[{"q":"[1]","o":["awarding","has been awarded","has awarded","will award"],"a":1,"k":"時態／語態：program 是接受補助者 → 被動 has been awarded","n":[["(V-ing) 授予","","缺助動詞，不能單獨當述語"],["已被授予（現在完成式被動）","be awarded + N","program 是接受補助的一方，用被動"],["已授予（主動）","","主動表示 program 頒發補助，語意顛倒"],["將授予（主動）","","主動語意顛倒；信中也是已決定的事"]]},{"q":"[2]","o":["commit","committed","commitment","commits"],"a":2,"k":"詞性：its strong 後要名詞 → commitment to + V-ing","n":[["(v.) 承諾","","strong 後要名詞，動詞不能放這裡"],["(adj.) 盡心的","","形容詞，strong 後要接名詞"],["(n.) 承諾；投入","commitment to + V-ing","名詞，且 to 後接 offering"],["(v.) 承諾（第三人稱單數）","","動詞，strong 後要名詞"]]},{"q":"[3]","o":["In spite of","According to","As a result of","Prior to"],"a":3,"k":"連接詞：後句 submit report by August 15 → 付款「之前」，用 Prior to","n":[["(prep.) 儘管","in spite of + N","語意不通：報告與付款不是讓步關係"],["(prep.) 根據","according to + N","語意不通：不是「根據」第二筆款"],["(prep.) 由於","as a result of + N","報告在付款前繳，不是付款的結果"],["(prep.) 在…之前","prior to + N","報告要在第二筆款之前繳交"]]}]},
{"id":"r800-25","lv":800,"p":6,"k":"advertisement","ti":"Bennett & Shaw Accounting","tx":"Bennett & Shaw Accounting: Let Us Handle the Numbers\n\nRunning a small business leaves little time for paperwork. If you are looking for a reliable partner, Bennett & Shaw can help. Our firm [1] ------- in accounting services for companies with fewer than 50 employees, from restaurants to design studios.\n\nOur team will prepare your invoices, process your payroll, and produce clear financial reports every month. Every client is assigned a [2] ------- accountant, so you will always speak with someone who knows your business well.\n\nOur fees are fixed and agreed upon in advance. [3] ------- That means no surprises when our invoice arrives.\n\nCall 555-0164 today to arrange a free one-hour meeting, or visit one of our three branches downtown.","zh":"Bennett & Shaw Accounting：數字的事交給我們\n\n經營小公司，實在沒有多少時間處理文書作業。如果您正在找一個可靠的夥伴，Bennett & Shaw 可以幫上忙。本事務所專門為員工少於 50 人的公司提供會計服務，客戶從餐廳到設計工作室都有。\n\n我們的團隊會為您開立發票、處理薪資，並且每個月製作清楚的財務報表。每位客戶都有一位專屬的會計師，所以您每次聯絡的都是熟悉貴公司業務的人。\n\n我們的收費固定，並且事先談定。絕不會另外收取超時費用。這表示您收到我們的帳單時不會有任何意外。\n\n今天就撥 555-0164 預約一小時的免費會談，或親臨我們在市中心的三家分所。","w":[617,661,573,644,635,582],"qs":[{"q":"[1]","o":["provides","specializes","generates","supervises"],"a":1,"k":"單字：後接 in accounting services → specialize in","n":[["(v.) 提供","provide + 受詞","provide 直接接受詞，不接 in"],["(v.) 專精於","specialize in + N","後面接 in accounting services"],["(v.) 產生","","generate 直接接受詞，不接 in"],["(v.) 監督","","supervise 直接接受詞，不接 in"]]},{"q":"[2]","o":["compulsory","temporary","consecutive","dedicated"],"a":3,"k":"單字：每位客戶指派 + always speak with 同一人 → dedicated","n":[["(adj.) 強制的","","語意不通：會計師不是「強制的」"],["(adj.) 臨時的","","與 'always ... knows your business' 矛盾"],["(adj.) 連續的","","語意不通：不能修飾一位會計師"],["(adj.) 專屬的","a dedicated + N","每位客戶有專屬會計師，呼應後句"]]},{"q":"[3]","o":["Our office is closed on public holidays.","You will never be charged for extra hours.","We are currently recruiting two junior accountants.","Prices may change at any time without notice."],"a":1,"k":"句子插入：前句費用固定 + 後句 no surprises → 不會額外收費","n":[["本所國定假日休息。","","與費用無關，也接不上 'no surprises'"],["您絕不會被額外收取工時費。","","呼應 'fixed' 費用，接得上 'no surprises'"],["我們正在徵求兩名初級會計。","","與費用無關"],["價格可能隨時變動，恕不另行通知。","","矛盾：前句說費用固定，事先約定"]]}]},
{"id":"r800-26","lv":800,"p":6,"k":"announcement","ti":"Orbis Freight Appoints New Managing Director","tx":"Orbis Freight Appoints New Managing Director\n\nOrbis Freight announced today that Laura Jennings will [1] ------- the role of managing director on January 1. She replaces Richard Dunn, who is retiring after 22 years with the corporation.\n\nMs. Jennings joined Orbis eight years ago as a regional sales manager and [2] ------- the company's European operations since 2021. Under her leadership, revenue in that region has risen by 35 percent.\n\n\"Laura understands both our customers and our personnel,\" said Mr. Dunn. \"I am confident that the company will continue to thrive.\"\n\nIn her new role, Ms. Jennings intends to place greater [3] ------- on digital tracking services, which allow clients to follow their shipments at every stage of the journey.\n\nMs. Jennings will address employees at headquarters on January 4.","zh":"Orbis Freight 任命新任總經理\n\nOrbis Freight 今天宣布，Laura Jennings 將於 1 月 1 日接任總經理一職。她接替的是 Richard Dunn，他在公司服務 22 年後即將退休。\n\nJennings 女士八年前加入 Orbis，擔任區域業務經理，並自 2021 年起掌管公司的歐洲業務。在她的帶領下，該地區的營收成長了 35%。\n\nDunn 先生表示：「Laura 既了解我們的客戶，也了解我們的員工。我有信心公司會繼續蓬勃發展。」\n\n上任後，Jennings 女士打算更加重視數位追蹤服務，這項服務讓客戶能掌握貨物在運送過程中每個階段的狀況。\n\nJennings 女士將於 1 月 4 日在總部對員工發表談話。","w":[731,561,669,533,590,730,529,744],"qs":[{"q":"[1]","o":["convey","assume","deduct","dismiss"],"a":1,"k":"單字：搭配 the role of managing director → assume 擔任","n":[["(v.) 傳達","","語意不通：職位不是用來「傳達」"],["(v.) 擔任；承擔","assume the role / position of","接任新職務的固定用法"],["(v.) 扣除","","語意不通：不能「扣除」職務"],["(v.) 解僱","","語意相反：她是接任，不是被解僱"]]},{"q":"[2]","o":["has supervised","supervises","will supervise","was supervised"],"a":0,"k":"時態／語態：since 2021 → 從過去持續到現在，用現在完成式","n":[["一直在管理（現在完成式）","since + 過去時間 → has + p.p.","since 2021 持續至今，Jennings 是主管者"],["管理（現在簡單式）","","since 2021 要搭配完成式，不用現在簡單式"],["將管理（未來式）","","since 2021 的起點在過去，不是未來"],["被管理（過去式被動）","","語態錯：她是管理者，不是被管理"]]},{"q":"[3]","o":["exposure","efficiency","capacity","emphasis"],"a":3,"k":"單字：place greater ___ on → emphasis 重視","n":[["(n.) 曝光","","不搭 place ... on，語意也不合"],["(n.) 效率","","不搭 place ... on，語意不通"],["(n.) 容量；能力","","不搭 place ... on，語意不通"],["(n.) 強調；重視","place emphasis on + N","固定搭配：把重心放在數位追蹤服務"]]}]},
{"id":"r800-27","lv":800,"p":6,"k":"email","ti":"Inventory count this Sunday","tx":"To: All store staff\nFrom: Kevin Brandt, Store Manager\nSubject: Inventory count this Sunday\n\nHello everyone,\n\nOur twice-yearly inventory count will take place this Sunday, April 26, after the store closes at 6:00 P.M. Attendance is mandatory for everyone scheduled to work that evening. Please [1] ------- to the stockroom at 6:15 for instructions.\n\nCount carefully. Last time, the totals in several categories did not match our computer records, and it took three days to find the errors. [2] ------- figures help us order the right quantities and avoid running out of popular items.\n\nAny damaged or defective products that you find should be placed in the red bins near the back door. They [3] ------- on Monday morning after I have recorded them.\n\nDinner will be provided, and everyone will be paid at the overtime rate.\n\nThanks,\nKevin","zh":"收件人：全體門市同仁\n寄件人：Kevin Brandt，店長\n主旨：本週日庫存盤點\n\n大家好：\n\n我們半年一次的庫存盤點將在本週日 4 月 26 日晚上 6 點打烊後進行。當晚排班的同仁一律必須參加。請在 6 點 15 分前往倉庫聽取說明。\n\n請仔細清點。上一次有好幾個類別的總數和電腦紀錄對不上，花了三天才找出錯誤。正確的數字能幫助我們訂購適當的數量，避免熱門商品缺貨。\n\n如果發現任何損壞或有瑕疵的商品，請放進後門附近的紅色箱子裡。等我登記之後，這些商品會在星期一早上丟棄。\n\n當天會提供晚餐，所有人都會以加班費率計薪。\n\n謝謝\nKevin","w":[587,639,672,642,616,701],"qs":[{"q":"[1]","o":["proceed","determine","obtain","notify"],"a":0,"k":"單字：to the stockroom 為地點 → proceed to 前往","n":[["(v.) 前往；繼續進行","proceed to + 地點","後接 to the stockroom，指前往倉庫"],["(v.) 決定","","determine 直接接受詞，不接 to + 地點"],["(v.) 取得","","obtain 直接接受詞，不接 to + 地點"],["(v.) 通知","notify + 人","notify 的受詞是人，不接 to + 地點"]]},{"q":"[2]","o":["Apprehensive","Accurate","Confidential","Controversial"],"a":1,"k":"單字：前句 Count carefully → Accurate figures 正確的數字","n":[["(adj.) 憂慮的","","用來形容人，不能修飾 figures"],["(adj.) 正確的","accurate figures / data","呼應 'Count carefully'，數字準才能正確訂貨"],["(adj.) 機密的","","文法可以，但「機密」無法幫助訂貨"],["(adj.) 有爭議的","","文法可以，但「有爭議」語意不通"]]},{"q":"[3]","o":["have discarded","will discard","will be discarded","were discarded"],"a":2,"k":"時態／語態：products 被處理 + on Monday 未來 → will be discarded","n":[["已經丟棄（現在完成式）","","時態與語態都錯：Monday 是未來，產品不會自己丟"],["將丟棄（主動）","","語態錯：產品是被丟棄的對象"],["將被丟棄","will be + p.p.","on Monday 未來，產品被丟棄，用未來被動"],["被丟棄了（過去式被動）","","時態錯：Monday 還沒到"]]}]},
{"id":"r800-28","lv":800,"p":6,"k":"article","ti":"Tavero Releases Lightweight Travel Monitor","tx":"Tavero Releases Lightweight Travel Monitor\n\nElectronics maker Tavero Systems has released a portable computer monitor designed for business travelers. The Tavero Slim 14 weighs just 600 grams and is [1] ------- with most laptops and tablets through a single cable.\n\nAccording to product manager Irene Costa, the idea came from a customer [2] ------- conducted last year. More than half of the people who answered said that working on one small screen in a hotel room reduced their efficiency.\n\nThe Slim 14 costs $249 and comes with a protective cover and a two-year warranty. Tavero expects the product to boost its revenue in the portable device segment, where sales [3] ------- for the past two quarters.\n\nThe monitor is available now on the company's website and at major electronics stores.","zh":"Tavero 推出輕量型旅用螢幕\n\n電子產品製造商 Tavero Systems 推出了一款專為商務旅客設計的可攜式電腦螢幕。Tavero Slim 14 只有 600 公克重，用一條線就能與大多數筆電和平板電腦相容。\n\n產品經理 Irene Costa 表示，這個構想來自去年進行的一項顧客意見調查。超過半數的受訪者說，在飯店房間裡只用一個小螢幕工作會降低他們的效率。\n\nSlim 14 售價 249 美元，附保護套及兩年保固。可攜式裝置這個類別的銷售量在過去兩季持續下滑，Tavero 期望這款產品能提升該類別的營收。\n\n這款螢幕現在已經可以在該公司網站和各大電子產品賣場買到。","w":[748,620,594,536,747,590,502,746],"qs":[{"q":"[1]","o":["compatible","exclusive","durable","eligible"],"a":0,"k":"單字：be ___ with laptops through a cable → compatible with","n":[["(adj.) 相容的","be compatible with + N","與筆電、平板相容，搭配 with"],["(adj.) 獨家的","exclusive to + N","搭配是 to，不接 with；語意也不合"],["(adj.) 耐用的","","durable 不接 with，語意也不合"],["(adj.) 有資格的","eligible for / to","搭配是 for/to，不接 with，語意不合"]]},{"q":"[2]","o":["poll","clause","warranty","hazard"],"a":0,"k":"單字：conducted last year + people who answered → poll","n":[["(n.) 意見調查；民調","conduct a poll / survey","後文 'people who answered' 指問卷調查"],["(n.) 條款","","語意不通：條款不是被「進行」的調查"],["(n.) 保固","","語意不通：保固不會有人回答"],["(n.) 危險","","語意不通：與回答的人無關"]]},{"q":"[3]","o":["have declined","declining","will decline","are declined"],"a":0,"k":"時態／語態：for the past two quarters → 現在完成式","n":[["已經下滑（現在完成式）","for the past + 期間 → have + p.p.","sales 為複數，for the past two quarters 持續至今"],["下滑中","","缺助動詞，不能單獨當述語"],["將下滑（未來式）","","for the past 指過去到現在，不用未來式"],["被拒絕","","此處 decline 是「下滑」，不及物，不用被動"]]}]},
{"id":"r800-29","lv":800,"p":6,"k":"notice","ti":"Safety Notice: Storage of Cleaning Products","tx":"SAFETY NOTICE: Storage of Cleaning Products\n\nFollowing last week's safety inspection, all staff are reminded that cleaning products containing strong chemicals can be a serious [1] ------- if they are stored incorrectly.\n\nFrom now on, these products must be kept in the locked cabinet in the supply room, not under sinks or on open shelves. Each container must [2] ------- with its contents and the date it was opened. Never pour a product into an unmarked bottle.\n\nAs a further precaution, gloves and safety glasses are now available in the supply room. They must be worn [3] ------- you handle these products.\n\nIf a spill occurs, open the windows and notify the facilities supervisor immediately at extension 118. These measures will be enforced starting Monday, and supervisors will monitor each area regularly.","zh":"安全公告：清潔用品的存放\n\n上週安全檢查之後，在此提醒全體同仁：含有強烈化學物質的清潔用品如果存放不當，可能造成嚴重的危險。\n\n即日起，這類用品必須放在備品室上鎖的櫃子裡，不可放在水槽下方或開放式的架子上。每個容器都必須標示內容物和開封日期。絕對不要把清潔用品倒進沒有標示的瓶子裡。\n\n為了進一步預防意外，備品室現在備有手套和護目鏡。每次使用這些清潔用品時都必須配戴。\n\n萬一打翻，請打開窗戶，並立刻撥分機 118 通知總務主管。這些措施將自星期一起嚴格執行，各主管也會定期檢查各區域。","w":[531,579,554,532,725,599,699,736],"qs":[{"q":"[1]","o":["merit","asset","prospect","hazard"],"a":3,"k":"單字：a serious ___ if stored incorrectly → hazard 危險","n":[["(n.) 優點","","語意相反：存放不當不會是「優點」"],["(n.) 資產","","語意相反：不當存放不是資產"],["(n.) 前景","","語意不通：與安全提醒無關"],["(n.) 危險","a serious hazard","強烈化學品存放不當會有危險"]]},{"q":"[2]","o":["label","have labeled","labeling","be labeled"],"a":3,"k":"時態／語態：must 後接原形 + container 被標示 → be labeled","n":[["(v.) 標示（原形）","","語態錯：容器是被標示的對象，要用被動"],["已標示（完成式主動）","","must have + p.p. 是推測過去；且容器是被標示，要被動"],["標示中（V-ing）","","must 之後不能接 V-ing"],["被標示","must + be + p.p.","助動詞後用原形 be，容器被標示 with contents"]]},{"q":"[3]","o":["although","unless","whereas","whenever"],"a":3,"k":"連接詞：前句必須戴手套 → 每當處理產品時，用 whenever","n":[["(conj.) 雖然","","語意相反：不是「雖然處理仍要戴」的讓步"],["(conj.) 除非","","語意相反：unless = if not，變成「不處理時才要戴」"],["(conj.) 然而","","前後不是對比，語意不通"],["(conj.) 每當","whenever + 子句","每次處理這些產品時都必須戴"]]}]},
{"id":"r800-30","lv":800,"p":6,"k":"message","ti":"Reminder about the travel guidelines","tx":"From: Rachel Owens, Travel Coordinator\nTo: Sales team group chat\n\nHi everyone. Here is a quick reminder about the travel guidelines that we implemented on May 1.\n\n1. All flights and hotels must be booked through Skyway Travel, our official agency. It offers corporate rates that are not available on public websites.\n2. You need to [1] ------- written approval from your manager prior to booking any trip that costs more than $1,000.\n3. Keep every receipt. Any expense that is not supported by a receipt [2] ------- from your claim.\n\nThe agency's help line is open 24 hours a day, so you can get assistance even if a flight is canceled at night. The number is 555-0131.\n\n[3] ------- you have any questions about these rules, please message me directly. Have a safe trip!","zh":"寄件人：Rachel Owens，差旅統籌\n收件人：業務團隊群組\n\n大家好。在此簡單提醒各位我們 5 月 1 日開始實施的差旅規範。\n\n1. 所有機票和飯店都必須透過我們的指定旅行社 Skyway Travel 預訂。該旅行社提供一般網站上沒有的企業優惠價。\n2. 任何費用超過 1,000 美元的出差，訂票之前都必須先取得主管的書面核准。\n3. 請保留每一張收據。沒有收據佐證的費用，將從您的申請金額中扣除。\n\n旅行社的服務專線 24 小時開放，所以即使班機在半夜取消，您也能得到協助。電話是 555-0131。\n\n如果對這些規定有任何問題，請直接傳訊息給我。祝各位一路平安！","w":[544,676,572,631,709,624,691],"qs":[{"q":"[1]","o":["qualify","restrict","notify","obtain"],"a":3,"k":"單字：written approval 為受詞 → obtain 取得","n":[["(v.) 取得資格","qualify for + N","不及物，不直接接 approval"],["(v.) 限制","","語意不通：不是要「限制」核准"],["(v.) 通知","notify + 人","受詞應是人，不能直接接 approval"],["(v.) 取得","obtain approval","出差前須取得主管的書面核准"]]},{"q":"[2]","o":["deducting","has deducted","will deduct","will be deducted"],"a":3,"k":"時態／語態：expense 被扣除 + 未來規定 → will be deducted","n":[["扣除（V-ing）","","缺助動詞，不能單獨當述語"],["已扣除（主動）","","語態錯：expense 是被扣除的對象"],["將扣除（主動）","","語態錯：主詞 expense 不會自己扣除"],["將被扣除","be deducted from + N","expense 被從 claim 扣除，用被動"]]},{"q":"[3]","o":["Should","Would","Could","Might"],"a":0,"k":"連接詞：句首無 If、後接 you have → 倒裝 Should you have","n":[["(助動詞) 萬一","Should you have ... = If you have ...","倒裝省略 if，表「萬一有問題」"],["(助動詞) 會","","Would you have 是疑問句，不能引導條件句"],["(助動詞) 能","","Could you have 是疑問句，不能引導條件句"],["(助動詞) 可能","","Might you have 不能當條件倒裝，不通"]]}]},
{"id":"r990-01","lv":990,"p":7,"k":"email","ti":"Discrepancy on invoice 4471","tx":"To: Daniel Ortiz, Brightway Office Supply\nFrom: Mei-Ling Chen, Accounts Payable, Norland Freight\nSubject: Discrepancy on invoice 4471\n\nDear Mr. Ortiz,\n\nWhile reconciling our ledger for the third quarter, I noticed a discrepancy between invoice 4471 and the purchase order we issued on September 3. The purchase order authorized 40 ergonomic chairs at $185 each, whereas the invoice bills us for 48 chairs. Our warehouse records confirm that only 40 were delivered.\n\nI assume this is a simple oversight rather than a deliberate charge. Nevertheless, our internal policy obliges us to withhold payment on any invoice that deviates from the underlying purchase order. Accordingly, the outstanding balance of $8,880 will remain on hold until we receive a corrected invoice.\n\nOur external auditors begin their annual review on October 20, so a prompt reply would be appreciated. If a revised invoice reaches me by October 13, I can expedite the payment so that it is released within three business days instead of the usual thirty.\n\nPlease direct any further correspondence on this matter to me rather than to our procurement team.\n\nSincerely,\nMei-Ling Chen","zh":"收件人：Daniel Ortiz，Brightway Office Supply\n寄件人：Mei-Ling Chen，Norland Freight 應付帳款部\n主旨：第 4471 號發票金額不符\n\nOrtiz 先生您好：\n\n我在核對本公司第三季的總帳時，發現第 4471 號發票與我們 9 月 3 日開出的採購單有出入。採購單核准的是 40 張人體工學椅，每張 185 美元，但發票卻向我們請款 48 張。我們的倉庫紀錄確認只收到 40 張。\n\n我想這只是單純的疏忽，而不是刻意多收費用。不過，依照本公司內部規定，凡是與原始採購單不符的發票，我們都必須暫緩付款。因此，這筆 8,880 美元的未付款項將暫時保留，直到我們收到更正後的發票為止。\n\n本公司的外部稽核人員將於 10 月 20 日開始年度查核，因此希望您能盡快回覆。如果修正後的發票能在 10 月 13 日前寄達，我可以加速處理付款，讓款項在三個工作天內撥付，而不必等一般的三十天。\n\n關於此事的後續聯繫，請直接寄給我，不要寄給我們的採購團隊。\n\nMei-Ling Chen 敬上","w":[810,937,836,935,875,837,932,765],"qs":[{"q":"Why did Ms. Chen write the e-mail?","o":["To order additional chairs","To request a corrected invoice","To announce a new payment policy","To report damaged merchandise"],"a":1,"k":"主旨題：結論句 'until we receive a corrected invoice' → 要求更正發票","n":[["要訂購更多椅子","","她指出多開了 8 張，並非要加訂"],["要求提供更正後的發票","","文中 'on hold until we receive a corrected invoice'"],["宣布新的付款政策","","policy 是既有的 'our internal policy'，不是新宣布"],["通報商品受損","","只說數量不符、'only 40 were delivered'，沒提受損"]]},{"q":"What will happen if a revised invoice arrives by October 13?","o":["The purchase order will be canceled","Payment will be released within three business days","The auditors will postpone their review","Eight more chairs will be delivered"],"a":1,"k":"細節題：找 October 13 → 第三段 'released within three business days'","n":[["採購單會被取消","","文中沒提取消採購單"],["款項將在三個工作天內撥付","","文中 'released within three business days'"],["稽核人員會延後查帳","","稽核 October 20 開始，沒說會延後"],["會再送來八張椅子","","8 張是多開的差額，且 40 張已送達，不會補送"]]},{"q":"The word \"outstanding\" in paragraph 2 is closest in meaning to","o":["unpaid","excellent","estimated","noticeable"],"a":0,"k":"字義題：outstanding balance → 未付餘額，呼應 withhold payment","n":[["(adj.) 未付清的","","'outstanding balance' 指未付餘額，款項仍 on hold"],["(adj.) 傑出的","","outstanding 另一義項，但不能形容 balance"],["(adj.) 估計的","","$8,880 是發票明列的確定金額，不是估計"],["(adj.) 明顯的","","『明顯』也是義項，但套進 balance 語意不通"]]}]},
{"id":"r990-02","lv":990,"p":7,"k":"memo","ti":"Revised travel reimbursement rules","tx":"MEMO\n\nTo: All sales staff\nFrom: Karen Whitfield, Finance Director\nDate: March 2\nSubject: Revised travel reimbursement rules\n\nTravel expenditure rose 22 percent in the last fiscal year, far more than our budget can sustain. To curtail these costs without impeding client visits, the following rules will take effect on April 1.\n\nFirst, any trip expected to cost more than $1,500 must be authorized by your regional manager before tickets are purchased. Expenses incurred without prior approval will not be reimbursed. Second, claims must be submitted with itemized receipts within 14 days of your return; late claims will be paid only at the discretion of the finance department. Third, employees are expected to book economy fares on flights shorter than six hours. Staff traveling together with clients are exempt from this requirement.\n\nA recent audit found that nearly one in five claims lacked adequate documentation, so compliance with these rules will be monitored closely. Managers will be held accountable for every claim they approve.\n\nQuestions about the new rules should be directed to the finance department.","zh":"備忘錄\n\n收件人：全體業務人員\n寄件人：財務長 Karen Whitfield\n日期：3 月 2 日\n主旨：差旅費報帳規定修訂\n\n上一個會計年度的差旅支出增加了 22%，遠超過預算所能負擔的範圍。為了削減這些成本，同時又不妨礙拜訪客戶，以下規定將自 4 月 1 日起生效。\n\n第一，任何預估費用超過 1,500 美元的出差，都必須在購票前取得區域經理的核准。未經事先核准而產生的費用，一律不予報銷。第二，報帳申請必須在返回後 14 天內連同明細收據一併提出；逾期的申請是否給付，由財務部全權決定。第三，飛行時間少於六小時的航班，員工應訂經濟艙。與客戶同行的員工不受此項規定限制。\n\n最近一次稽核發現，將近五分之一的報帳申請缺少足夠的證明文件，因此公司將嚴格監督這些規定的遵守情況。主管必須為自己核准的每一筆申請負責。\n\n對新規定有任何疑問，請洽財務部。","w":[821,892,961,954,981,799,912,770],"qs":[{"q":"What is the main purpose of the memo?","o":["To announce a reduction in sales staff","To report the results of a client survey","To invite employees to a budget meeting","To explain new rules for travel expenses"],"a":3,"k":"主旨題：開頭 'the following rules will take effect' → 新差旅規定","n":[["宣布裁減業務人員","","文中沒提裁員，只談差旅費用規則"],["報告客戶調查結果","","文中沒提任何客戶調查"],["邀請員工參加預算會議","","只說預算撐不住，沒有任何會議邀請"],["說明新的差旅費用規定","","文中 'rules will take effect on April 1'，後列三項規定"]]},{"q":"Who does NOT have to book economy fares on flights under six hours?","o":["Employees traveling with clients","Finance department staff","Regional managers","Employees whose trips cost over $1,500"],"a":0,"k":"細節題：找 exempt → 'Staff traveling together with clients'","n":[["與客戶同行的員工","","文中 'traveling together with clients are exempt'"],["財務部員工","","財務部只負責受理疑問，沒說可免訂經濟艙"],["區域經理","","區域經理負責核准出差，沒說他們可免訂經濟艙"],["出差費用超過 $1,500 的員工","","超過 $1,500 只是須事先核准，不是免訂經濟艙"]]},{"q":"What is suggested about some past reimbursement claims?","o":["They lacked enough supporting documents","They were rejected by external auditors","They involved flights longer than six hours","They were paid twice by mistake"],"a":0,"k":"推論題：對應稽核結果 → 'lacked adequate documentation'","n":[["缺少足夠的佐證文件","","文中 'claims lacked adequate documentation'"],["被外部稽核人員駁回","","audit 只發現文件不足，沒說被駁回，也沒說外部"],["涉及超過六小時的航班","","六小時是新規定的條件，與過去報帳問題無關"],["被誤付了兩次","","文中沒提重複付款"]]}]},
{"id":"r990-03","lv":990,"p":7,"k":"article","ti":"Shareholders back Castell–Rhine merger","tx":"Shareholders Back Castell–Rhine Merger\n\nHARBOR CITY — Shareholders of Castell Logistics voted on Tuesday to approve a merger with Rhine Cargo, a smaller rival that specializes in refrigerated transport. The board had unanimously endorsed the deal in May, and more than 80 percent of the votes cast were in favor.\n\nUnder the terms disclosed last month, Rhine Cargo will become a subsidiary of Castell and will keep its own name for the foreseeable future. Castell's chairperson, Helen Navarro, said the two firms' networks are complementary: Castell is strong in long-distance road freight, while Rhine leads in cold-storage delivery within the region. She expects the resulting synergy to yield annual savings of about $12 million, chiefly by consolidating warehouses.\n\nNot everyone is convinced. Some analysts warn that integrating two separate tracking systems will entail considerable expense and could offset much of the projected savings during the first two years.\n\nThe transaction still requires clearance from regulators and is expected to close in early December. Rhine's chief executive, Paul Derrick, will remain in his post.","zh":"股東支持 Castell 與 Rhine 合併案\n\nHARBOR CITY 訊 — Castell Logistics 的股東週二投票通過與 Rhine Cargo 的合併案。Rhine Cargo 是規模較小的同業對手，專營冷藏運輸。董事會已在五月一致表態支持這項交易，而這次投票有超過八成的票數贊成。\n\n根據上個月公布的條件，Rhine Cargo 將成為 Castell 的子公司，並在可預見的未來保留原有名稱。Castell 董事長 Helen Navarro 表示，兩家公司的運輸網具有互補性：Castell 的強項是長途公路貨運，Rhine 則在區域內的低溫倉儲配送居於領先地位。她預期由此產生的綜效每年可省下約 1,200 萬美元，主要來自整併倉庫。\n\n不過，並非所有人都看好。部分分析師提醒，整合兩套各自獨立的貨物追蹤系統將需要可觀的費用，可能會抵銷頭兩年大部分的預期節省金額。\n\n這筆交易仍須取得主管機關核准，預計在十二月初完成。Rhine 執行長 Paul Derrick 將留任原職。","w":[834,761,917,964,805,841,942,990],"qs":[{"q":"What is the article mainly about?","o":["The opening of a new cold-storage warehouse","A dispute between regulators and a logistics firm","The resignation of a company's chairperson","The approval of a merger between two transport firms"],"a":3,"k":"主旨題：首句 'voted on Tuesday to approve a merger' → 合併案獲准","n":[["一座新冷藏倉庫啟用","","文中沒提新倉庫，只提 consolidating warehouses"],["主管機關與物流公司的爭議","","regulators 只是尚須核准，沒說有爭議"],["一位公司董事長請辭","","Navarro 只是發言說明綜效，沒有請辭"],["兩家運輸公司合併案獲得通過","","文中 'voted ... to approve a merger'"]]},{"q":"According to Ms. Navarro, how will most of the savings be achieved?","o":["By reducing the number of drivers","By changing Rhine Cargo's name","By replacing the tracking systems","By combining warehouses"],"a":3,"k":"細節題：找 savings → 'chiefly by consolidating warehouses'","n":[["減少司機人數","","文中沒提減少司機"],["更改 Rhine Cargo 的名稱","","Rhine 會 'keep its own name'，與節省無關"],["汰換追蹤系統","","整合追蹤系統是分析師說的開銷，不是省錢來源"],["合併倉庫","","文中 'chiefly by consolidating warehouses'"]]},{"q":"What is NOT stated about Rhine Cargo?","o":["It will keep its current name","It will relocate its headquarters","Its chief executive will stay on","It specializes in refrigerated transport"],"a":1,"k":"NOT 題：逐項對照，三項都有寫，只有搬遷總部沒提","n":[["會保留現有名稱","","文中有：'keep its own name'"],["會遷移總部","","全文沒提搬遷總部，故為答案"],["執行長會留任","","文中有：'Paul Derrick, will remain in his post'"],["專營冷藏運輸","","文中有：'specializes in refrigerated transport'"]]}]},
{"id":"r990-04","lv":990,"p":7,"k":"notice","ti":"Elevator modernization at Kessler Tower","tx":"NOTICE TO ALL TENANTS OF KESSLER TOWER\n\nElevator Modernization\n\nBuilding management has engaged a licensed contractor to replace the control systems of all four passenger elevators. Work will commence on Monday, June 9, and is scheduled to finish by Friday, July 18.\n\nTo mitigate disruption, only one elevator will be taken out of service at a time. Tenants should nevertheless anticipate longer waits, particularly between 8:30 and 9:30 A.M. Intermittent noise is inevitable while the old equipment is being removed; the noisiest tasks have accordingly been restricted to the hours between 7:00 P.M. and 6:00 A.M.\n\nThe freight elevator at the rear of the premises will remain in operation throughout the project. In the interest of accessibility, it has been designated for visitors with limited mobility as well as for deliveries, so we ask other tenants to refrain from using it.\n\nCompanies planning to move furniture or large equipment during this period must notify the management office at least 48 hours in advance.\n\nThe new systems comply with the latest safety code and are expected to cut energy consumption by roughly 30 percent. We appreciate your patience.","zh":"KESSLER TOWER 全體租戶公告\n\n電梯更新工程\n\n大樓管理處已委託合格的承包商，更換全部四部客用電梯的控制系統。工程將於 6 月 9 日星期一開始，預定在 7 月 18 日星期五前完工。\n\n為了減輕對各位造成的不便，每次只會停用一部電梯。不過仍請租戶預期等候時間會拉長，尤其是上午 8:30 到 9:30 之間。拆除舊設備期間，難免會有斷斷續續的噪音；因此，最吵的作業已限定在晚上 7:00 到清晨 6:00 之間進行。\n\n位於大樓後方的貨梯在工程期間將照常運作。為了維持無障礙通行，除了送貨之外，這部貨梯也已指定供行動不便的訪客使用，因此請其他租戶不要搭乘。\n\n在此期間打算搬運家具或大型設備的公司，必須至少提前 48 小時通知管理處。\n\n新系統符合最新的安全規範，預計可減少約 30% 的耗電量。感謝您的耐心配合。","w":[766,974,966,904,865,758,977,926],"qs":[{"q":"What is the purpose of the notice?","o":["To introduce a new building manager","To announce an increase in rent","To inform tenants about upcoming elevator work","To report a recent safety violation"],"a":2,"k":"主旨題：開頭 'replace the control systems' + 日期 → 電梯工程通知","n":[["介紹新的大樓經理","","'Building management' 只是發出通知，沒介紹新經理"],["宣布調漲租金","","文中沒提租金"],["通知租戶即將進行電梯工程","","文中 'replace the control systems' of elevators"],["通報最近的安全違規","","只說新系統符合安全規範，沒提違規"]]},{"q":"When will the loudest work be carried out?","o":["Only on weekends","During regular office hours","Between 7:00 P.M. and 6:00 A.M.","Between 8:30 and 9:30 A.M."],"a":2,"k":"細節題：找 noisiest → 'between 7:00 P.M. and 6:00 A.M.'","n":[["只在週末","","文中沒限定週末，限制的是夜間時段"],["一般上班時間","","吵的作業被限制在夜間，正是避開上班時段"],["晚上 7 點到清晨 6 點","","文中 'noisiest tasks' 限於 7 P.M. 到 6 A.M."],["上午 8:30 到 9:30","","那是等電梯較久的尖峰，不是噪音作業時段"]]},{"q":"The word \"mitigate\" in paragraph 2 is closest in meaning to","o":["schedule","predict","explain","lessen"],"a":3,"k":"字義題：mitigate disruption → 減輕干擾，措施是一次只停一部","n":[["(v.) 安排時程","","『安排』套進 mitigate disruption 語意不通"],["(v.) 預測","","預測干擾，與『一次只停一部』的措施不合"],["(v.) 解釋","","解釋干擾，語意不通；措施是為了減少不便"],["(v.) 減輕","","'only one elevator ... at a time' 是為了減輕干擾"]]}]},
{"id":"r990-05","lv":990,"p":7,"k":"advertisement","ti":"Procurement Manager wanted at Alder & Finch","tx":"Procurement Manager — Alder & Finch Foods\n\nAlder & Finch, an established producer of packaged snacks with a diversified clientele in twelve countries, is seeking a Procurement Manager for its Riverside headquarters.\n\nThe successful candidate will oversee a team of six buyers, negotiate contracts with suppliers of raw commodities such as wheat and sugar, and liaise with the logistics department to keep production lines supplied. Because commodity prices fluctuate sharply, the role demands sound judgment and the ability to assess risk under tight time constraints.\n\nApplicants must hold a degree in business or a related field and have at least five years of managerial experience in purchasing. Proficiency in a second language is desirable but not essential. Familiarity with food-safety legislation will be regarded as a considerable advantage.\n\nWe offer a competitive salary, performance-based incentives, and reimbursement of relocation costs up to $6,000.\n\nTo apply, submit a résumé and a letter outlining your credentials through the Careers page of our website by November 30. Shortlisted candidates will be invited to a preliminary video interview in mid-December; final interviews will be held onsite in January.","zh":"採購經理 — Alder & Finch Foods\n\nAlder & Finch 是一家信譽卓著的包裝零食製造商，客戶群多元，遍及十二個國家。本公司 Riverside 總部現正招募採購經理一名。\n\n錄取者將負責督導六名採購人員、與小麥和糖等原物料商品的供應商洽談合約，並與物流部門聯繫協調，確保生產線供料無虞。由於原物料價格波動劇烈，這個職位需要良好的判斷力，以及在緊迫的時間限制下評估風險的能力。\n\n應徵者必須具備商學或相關科系的學位，並有至少五年的採購管理經驗。精通第二外語者尤佳，但並非必要條件。熟悉食品安全法規者將大為加分。\n\n我們提供具競爭力的薪資、依績效發放的獎勵金，以及最高 6,000 美元的搬遷費用補助。\n\n有意應徵者，請於 11 月 30 日前透過本公司網站的「徵才」頁面，提交履歷及一封說明個人資歷的信函。進入候選名單者將受邀於十二月中旬參加初步的視訊面試；最終面試將於一月在公司現場舉行。","w":[824,806,923,986,918,842,775,988],"qs":[{"q":"What is indicated about Alder & Finch?","o":["It was founded twelve years ago","It grows its own wheat and sugar","It has customers in many countries","It recently moved its headquarters"],"a":2,"k":"細節題：找 clientele → 'clientele in twelve countries'","n":[["成立於十二年前","","twelve 指國家數，不是創立年數"],["自己種植小麥和糖","","小麥、糖是向 suppliers 採購，不是自己種"],["在許多國家都有客戶","","文中 'clientele in twelve countries'，即多國客戶"],["最近搬遷了總部","","只說總部在 Riverside，沒提搬遷"]]},{"q":"What is a requirement for the position?","o":["Familiarity with food-safety legislation","Proficiency in a second language","Managerial experience in purchasing","Previous work in the snack industry"],"a":2,"k":"細節題：找 must → 'at least five years of managerial experience'","n":[["熟悉食品安全法規","","只是 'a considerable advantage'，非必要"],["精通第二外語","","'desirable but not essential'，非必要"],["採購方面的管理經驗","","文中 'must' + 'managerial experience in purchasing'"],["先前在零食業工作過","","只要求採購管理經驗，不限零食業"]]},{"q":"What is suggested about the interview process?","o":["All interviews will take place in December","The first round will be conducted by video","Final interviews will be held online","Candidates will be interviewed by six buyers"],"a":1,"k":"推論題：看最後一句 → 'preliminary video interview'","n":[["所有面試都在十二月","","初步面試在十二月，final 在 January"],["第一輪將以視訊進行","","文中 'a preliminary video interview'"],["最終面試將在線上舉行","","final interviews 是 'onsite'，不是線上"],["應徵者將由六名採購員面試","","六名採購員是新經理要帶領的團隊，不是面試官"]]}]},
{"id":"r990-06","lv":990,"p":7,"k":"message","ti":"Payroll software rollout: team chat","tx":"Ravi Menon (9:02 A.M.): Good morning. I brief the executives at 11:00, so I need a quick update. Where are we on the payroll software rollout?\n\nSofia Lindqvist (9:05 A.M.): The new system was deployed in the Denver and Austin offices over the weekend. Denver is running smoothly. Austin is reporting intermittent connectivity: users are logged out every twenty minutes or so.\n\nRavi Menon (9:07 A.M.): Is that our software or their network?\n\nTomas Vega (9:10 A.M.): Almost certainly their network. I spent an hour troubleshooting with their technician this morning. The application itself never crashed; the connection to the server simply drops. Their router has not been updated in years.\n\nSofia Lindqvist (9:12 A.M.): I agree. But until that is fixed, Austin cannot process Friday's payroll on the new system.\n\nRavi Menon (9:15 A.M.): Then let's be pragmatic. Austin goes back to the old system for this pay cycle. Tomas, please escalate the router issue to the infrastructure team and ask them to treat it as urgent. Sofia, postpone the Seattle rollout by a week so that we don't add to the backlog.\n\nTomas Vega (9:16 A.M.): Will do. You'll have a written summary by 10:30.","zh":"Ravi Menon（上午 9:02）：早安。我 11:00 要向高階主管做簡報，所以需要大家快速更新一下進度。薪資軟體的導入目前進行到哪裡了？\n\nSofia Lindqvist（上午 9:05）：新系統已在週末部署到 Denver 和 Austin 兩個辦公室。Denver 運作順利。Austin 則回報連線時斷時續：使用者大約每二十分鐘就會被登出一次。\n\nRavi Menon（上午 9:07）：是我們軟體的問題，還是他們網路的問題？\n\nTomas Vega（上午 9:10）：幾乎可以確定是他們的網路。今天早上我和他們的技術人員花了一個小時排查問題。應用程式本身從來沒有當機，只是和伺服器之間的連線會中斷。他們的路由器已經好幾年沒更新了。\n\nSofia Lindqvist（上午 9:12）：我同意。不過在修好之前，Austin 沒辦法用新系統處理星期五的薪資發放。\n\nRavi Menon（上午 9:15）：那我們就務實一點。這一期的薪資，Austin 先改回舊系統。Tomas，請把路由器的問題往上呈報給基礎設施團隊，並請他們列為緊急事項處理。Sofia，請把 Seattle 的導入時程延後一週，免得待處理的工作越積越多。\n\nTomas Vega（上午 9:16）：沒問題。10:30 前會給您一份書面摘要。","w":[753,784,971,904,771,943,950,804],"qs":[{"q":"What problem are the writers discussing?","o":["A technician did not arrive in Austin","Users in one office keep losing their connection","Employees in Denver were paid late","The payroll software has crashed several times"],"a":1,"k":"主旨題：Austin 'logged out every twenty minutes' → 連線一直斷","n":[["技術人員沒有抵達 Austin","","Vega 已與他們的技術人員一起排除問題"],["一個辦公室的使用者一直斷線","","文中 'users are logged out every twenty minutes'"],["Denver 員工被延遲發薪","","文中 Denver 'is running smoothly'，無發薪問題"],["薪資軟體當機多次","","Vega 說 'The application itself never crashed'"]]},{"q":"According to Mr. Vega, what is the most likely cause of the problem?","o":["A mistake made during the weekend installation","A shortage of trained technicians","A defect in the new software","Outdated network equipment in Austin"],"a":3,"k":"細節題：Vega 說 'Almost certainly their network' + 路由器","n":[["週末安裝時出了錯","","沒提安裝失誤，Vega 歸咎於對方網路"],["受過訓練的技術人員不足","","文中沒提人力不足"],["新軟體有缺陷","","Vega 說軟體本身 'never crashed'"],["Austin 老舊的網路設備","","文中 'router has not been updated in years'"]]},{"q":"What will most likely happen on Friday?","o":["Austin staff will be paid through the old system","The Denver office will return to the old system","Mr. Menon will travel to Austin","The Seattle office will start using the new software"],"a":0,"k":"推論題：Sofia 'cannot process Friday's payroll' → Ravi 決定退回舊系統","n":[["Austin 員工將用舊系統領薪","","文中 'Austin goes back to the old system'"],["Denver 辦公室將退回舊系統","","Denver 運作順暢，沒有退回的理由"],["Menon 先生將前往 Austin","","文中沒提 Menon 出差"],["Seattle 辦公室將開始用新軟體","","Seattle 被指示 'postpone ... by a week'，不是開始"]]}]},
{"id":"r990-07","lv":990,"p":7,"k":"letter","ti":"Notice regarding your dormant savings account","tx":"Larkfield Community Bank\n218 Canal Street\n\nApril 4\n\nMr. Victor Lopez\n57 Birchwood Lane\n\nDear Mr. Lopez,\n\nOur records show that no deposits or withdrawals have been made on your savings account ending in 3306 since March of last year. Under current banking legislation, an account that shows no customer activity for twelve consecutive months must be classified as dormant.\n\nYour funds remain safe and will continue to accrue interest at the current rate. However, a provision in your account agreement entitles the bank to charge a monthly maintenance fee of $5 on dormant accounts, commencing 60 days from the date of this letter. In addition, if an account stays inactive for five years, we are required by law to close it and transfer the balance to the government's unclaimed-funds office.\n\nTo restore your account to active status, simply make a transaction of any amount or visit any branch with valid photo identification. No fee will be incurred if you do so before June 3.\n\nIf you believe this letter was sent in error, please contact us promptly at 555-0142.\n\nSincerely,\nGrace Okafor\nCustomer Accounts Manager","zh":"Larkfield Community Bank\n218 Canal Street\n\n4 月 4 日\n\nVictor Lopez 先生\n57 Birchwood Lane\n\nLopez 先生您好：\n\n本行紀錄顯示，您尾號 3306 的儲蓄帳戶自去年三月以來，沒有任何存款或提款紀錄。依現行銀行法規，連續十二個月沒有客戶交易往來的帳戶，必須列為靜止戶。\n\n您的存款依然安全，並會繼續依目前的利率累計利息。不過，依照帳戶約定書中的一項條款，本行有權自本函日期起 60 天後，開始對靜止戶每月收取 5 美元的帳戶管理費。此外，帳戶若連續五年沒有往來，本行依法必須將其結清，並將餘額移交政府的無人認領款項管理單位。\n\n如要恢復帳戶的正常狀態，只需進行一筆任何金額的交易，或攜帶有效的附照片身分證件至任一分行辦理即可。若您在 6 月 3 日前完成，就不會產生任何費用。\n\n如果您認為本函是誤寄，請盡快來電 555-0142 與我們聯絡。\n\n客戶帳戶經理\nGrace Okafor 敬上","w":[882,825,965,816,939,974,954],"qs":[{"q":"Why was the letter sent to Mr. Lopez?","o":["To request repayment of a loan","To warn him that his account is considered inactive","To confirm that his account has been closed","To announce a change in interest rates"],"a":1,"k":"主旨題：'must be classified as dormant' + 收費預告 → 警告帳戶靜止","n":[["要求償還貸款","","文中沒提貸款"],["警告他帳戶被視為不活躍","","文中 'no customer activity ... dormant'"],["確認他的帳戶已被結清","","帳戶尚未關閉，五年未動才會被關"],["宣布利率調整","","文中 'at the current rate'，利率沒變"]]},{"q":"How can Mr. Lopez avoid the monthly fee?","o":["By signing a new account agreement","By making a transaction before June 3","By opening a second savings account","By writing to the unclaimed-funds office"],"a":1,"k":"細節題：找 avoid fee → 'No fee ... before June 3'","n":[["簽署新的帳戶合約","","文中沒要求簽新合約"],["在 6 月 3 日前進行一筆交易","","文中 'make a transaction ... before June 3'"],["再開一個儲蓄帳戶","","文中沒提開第二個帳戶"],["寫信給無人認領資金辦公室","","該單位只在五年後接收餘額，不能免收費"]]},{"q":"The word \"accrue\" in paragraph 2 is closest in meaning to","o":["owe","lose","accumulate","transfer"],"a":2,"k":"字義題：accrue interest → 利息累積，搭配 remain safe","n":[["(v.) 欠","","『欠』與存款孳息語意不合"],["(v.) 失去","","與 'remain safe' 語意相反"],["(v.) 累積","","'accrue interest' = 利息累積"],["(v.) 轉移","","轉移的是後句的餘額，不是利息"]]}]},
{"id":"r990-08","lv":990,"p":7,"k":"review","ti":"Review: Stratus Rise standing desk","tx":"Product review: Stratus Rise standing desk\nRating: 4 out of 5\nReviewed by Hannah Brooks, office manager\n\nWe bought twelve Stratus Rise desks when our firm refurbished its workstations last spring, and after eight months of daily use I can offer a fair appraisal.\n\nThe ergonomic design is the desk's foremost strength. The height adjusts quietly at the touch of a button, and the control panel is so intuitive that nobody on our staff needed the manual. Several colleagues say that alternating between sitting and standing has alleviated the discomfort of long hours at a desk. The steel frame feels solid, and the surface shows no scratches despite heavy use.\n\nMy reservations concern assembly and price. The printed instructions deviate from the parts actually supplied, and each desk took two people about ninety minutes to put together. At $640, it also costs considerably more than comparable models. On the other hand, the manufacturer's customer service was exceptional: when one motor failed in the fifth month, a replacement was dispatched within 48 hours at no charge.\n\nOverall, this is a sophisticated, durable product, provided you are willing to pay a premium and set aside an afternoon for assembly.","zh":"產品評論：Stratus Rise 升降桌\n評分：4 分（滿分 5 分）\n評論者：辦公室經理 Hannah Brooks\n\n去年春天公司翻新工作站時，我們買了十二張 Stratus Rise 升降桌。每天使用了八個月之後，我可以給出一個公允的評價。\n\n符合人體工學的設計是這張桌子最大的優點。只要按一個按鈕，桌面高度就能安靜地調整；控制面板非常直覺，我們沒有任何同事需要看說明書。好幾位同事說，坐著和站著交替工作，減輕了長時間坐在桌前的不適。鋼製桌架感覺很穩固，桌面雖然使用頻繁，卻沒有任何刮痕。\n\n我有所保留的地方是組裝和價格。紙本說明書和實際附的零件不一致，每張桌子要兩個人花大約九十分鐘才能組好。640 美元的售價也比同級產品貴上不少。不過另一方面，製造商的客服非常出色：第五個月時有一個馬達故障，替換品在 48 小時內就免費寄出了。\n\n整體來說，這是一款精密又耐用的產品，前提是你願意多付一些錢，並且空出一個下午來組裝。","w":[757,812,903,908,877,984,976,991],"qs":[{"q":"What does the reviewer consider the desk's greatest strength?","o":["Its detailed manual","Its low price","Its simple assembly","Its ergonomic design"],"a":3,"k":"細節題：greatest ≈ foremost → 主詞 'The ergonomic design'","n":[["詳細的說明書","","文中說明書 'deviate from the parts'，是缺點"],["低廉的價格","","文中 'costs considerably more'，價格偏高"],["簡單的組裝","","要兩人約九十分鐘，被列為保留意見"],["符合人體工學的設計","","文中 'ergonomic design is the ... foremost strength'"]]},{"q":"What happened in the fifth month of use?","o":["A desk was returned for a refund","A motor stopped working","The control panel was replaced","The surface became scratched"],"a":1,"k":"細節題：找 fifth month → 'one motor failed'","n":[["有桌子被退貨退款","","文中是免費寄替換品，沒提退款"],["一個馬達故障","","文中 'one motor failed in the fifth month'"],["控制面板被更換","","換的是馬達，控制面板反而 'intuitive'"],["桌面出現刮痕","","文中 'shows no scratches'"]]},{"q":"What is NOT mentioned as a drawback of the desk?","o":["Noisy height adjustment","A relatively high price","Lengthy assembly","Inaccurate assembly instructions"],"a":0,"k":"NOT 題：缺點在第三段；噪音沒列為缺點，反而說安靜","n":[["調整高度時噪音大","","文中 'adjusts quietly'，不是缺點，故為答案"],["價格相對偏高","","文中有：'costs considerably more'"],["組裝耗時","","文中有：'about ninety minutes'"],["組裝說明不準確","","文中有：'instructions deviate from the parts'"]]}]},
{"id":"r990-09","lv":990,"p":7,"k":"announcement","ti":"Lakeshore Entrepreneurs' Forum returns in October","tx":"Lakeshore Entrepreneurs' Forum Returns in October\n\nThe Lakeshore Chamber of Commerce is pleased to announce that its ninth annual Entrepreneurs' Forum will convene on October 17 and 18 at the Marlowe Conference Center.\n\nThis year's theme, \"Growing Without Outside Capital,\" will be addressed by a panel of accomplished business owners. The keynote speaker is Irene Castillo, cofounder of the renowned bakery franchise Maple Oven, who will describe how she turned a single shop into a chain of sixty outlets without borrowing from a bank. Other sessions encompass topics ranging from cybersecurity for small firms to practical ways of monetizing an online audience.\n\nRegistration costs $180 for both days or $110 for a single day. Chamber members are entitled to a 20 percent discount, and full-time students may attend free of charge on presentation of valid identification. Seating is limited to 300, and last year's forum sold out three weeks in advance, so prompt registration is advised.\n\nAll proceeds will fund the Chamber's outreach program, which offers free mentoring to prospective business owners in the region.\n\nTo register, visit the Chamber's website or call 555-0177.","zh":"Lakeshore 創業家論壇十月再度登場\n\nLakeshore 商會很高興宣布，第九屆年度創業家論壇將於 10 月 17 日及 18 日在 Marlowe 會議中心舉行。\n\n今年的主題是「不靠外部資本也能成長」，將由多位成就卓越的企業主組成座談小組進行探討。主講人是知名烘焙連鎖加盟品牌 Maple Oven 的共同創辦人 Irene Castillo，她將分享自己如何在不向銀行借款的情況下，把一家小店發展成擁有六十家門市的連鎖體系。其他場次涵蓋的主題，從小型企業的資訊安全，到把線上觀眾變現的實用方法，應有盡有。\n\n兩日的報名費為 180 美元，單日為 110 美元。商會會員可享八折優惠，全職學生出示有效證件即可免費參加。座位限額 300 名，而去年的論壇在活動三週前就已售完，因此建議盡早報名。\n\n所有收益將用於贊助商會的外展計畫，該計畫為本地區有意創業的人士提供免費輔導。\n\n報名請上商會網站，或致電 555-0177。","w":[750,956,776,869,993,957,813,848],"qs":[{"q":"What is being announced?","o":["A two-day event for business owners","A change in chamber membership fees","The opening of a new bakery outlet","A mentoring program for students"],"a":0,"k":"主旨題：首句 'Forum will convene on October 17 and 18'","n":[["為企業主舉辦的兩天活動","","文中 'Forum will convene on October 17 and 18'"],["商會會費的異動","","會員只是有折扣，沒說會費異動"],["新烘焙分店開幕","","烘焙品牌只是主講人的背景"],["針對學生的輔導計畫","","輔導對象是 prospective business owners，非學生"]]},{"q":"How much would a chamber member pay to attend both days?","o":["$110","$144","$88","$180"],"a":1,"k":"細節題：兩日 $180 × 20% 折扣 = $144","n":[["110 美元","","那是非會員的單日票價"],["144 美元","","文中 '$180 for both days'，會員折 20% = 144"],["88 美元","","那是會員單日價（110 打八折）"],["180 美元","","那是非會員的兩日票價"]]},{"q":"What is suggested about last year's forum?","o":["It was held at a different venue","It was free for chamber members","It lasted only one day","All of its seats were filled"],"a":3,"k":"推論題：找 last year → 'sold out three weeks in advance'","n":[["在不同場地舉行","","文中沒提去年場地"],["會員免費入場","","會員只有八折；免費的是學生"],["只舉辦一天","","文中沒提去年天數"],["所有座位都被訂滿","","文中 'last year's forum sold out'"]]}]},
{"id":"r990-10","lv":990,"p":7,"k":"form","ti":"Consignment confirmation no. TR-58214","tx":"TRANSPACIFIC FREIGHT SERVICES\nConsignment Confirmation No. TR-58214\n\nShipper: Dalton Machine Parts, 9 Foundry Road\nRecipient: Kobe Precision Tools (Attention: Mr. Hiro Tanaka)\nContents: 14 crates of steel fittings, total weight 2,310 kg\nService: Standard ocean freight\nDate dispatched: August 6\nEstimated arrival: September 2\n\nCharges\nFreight: $3,420\nInsurance (declared value $58,000): $290\nCustoms documentation: $150\nTotal due: $3,860, payable within 30 days of dispatch\n\nTerms\n1. The estimated arrival date is provisional and may change owing to weather or port congestion.\n2. Our liability for loss or damage is limited to the declared value stated above.\n3. The shipper is accountable for ensuring that the contents match the specifications given on the customs declaration. Any fines or storage fees incurred as a result of a discrepancy will be charged to the shipper.\n4. Delivery may be expedited by transferring the consignment to air freight before it is loaded onto the vessel. An additional fee applies, and requests must be made in writing.\n\nPlease quote the confirmation number in all correspondence and inquiries.","zh":"TRANSPACIFIC FREIGHT SERVICES\n託運確認單　編號 TR-58214\n\n託運人：Dalton Machine Parts，9 Foundry Road\n收件人：Kobe Precision Tools（Hiro Tanaka 先生收）\n內容物：鋼製配件 14 箱，總重量 2,310 公斤\n服務類別：一般海運\n發送日期：8 月 6 日\n預計抵達日期：9 月 2 日\n\n費用\n運費：3,420 美元\n保險費（申報價值 58,000 美元）：290 美元\n報關文件費：150 美元\n應付總額：3,860 美元，須於發送後 30 天內付清\n\n條款\n1. 預計抵達日期為暫定日期，可能因天候或港口壅塞而變動。\n2. 本公司對貨物遺失或損壞的賠償責任，以上述申報價值為限。\n3. 託運人須負責確保內容物與報關單上所載的規格相符。若因兩者不符而產生任何罰款或倉儲費用，將向託運人收取。\n4. 貨物裝船前，可改以空運運送以加速送達。此服務須另外收費，且須以書面提出申請。\n\n來函或洽詢時，請一律註明確認單編號。","w":[832,991,900,835,856,809,810,932],"qs":[{"q":"What is the purpose of this document?","o":["To cancel a freight booking","To request a customs inspection","To confirm the details of a shipment","To report goods damaged in transit"],"a":2,"k":"主旨題：標題 'Consignment Confirmation' + 貨物與費用明細","n":[["取消貨運訂位","","文件是確認單，不是取消"],["要求海關查驗","","'Customs documentation' 只是收費項目"],["確認一批貨物的運送細節","","標題 'Consignment Confirmation'，並列貨物、費用"],["通報貨物運送途中受損","","沒提貨損；條款 2 只說賠償上限"]]},{"q":"What is the most the carrier would pay if the goods were lost?","o":["$58,000","$3,860","$290","$3,420"],"a":0,"k":"推論題：條款 2 'limited to the declared value' → $58,000","n":[["58,000 美元","","文中 'limited to the declared value'，即 $58,000"],["3,860 美元","","那是應付總額，不是賠償上限"],["290 美元","","那是保險費"],["3,420 美元","","那是運費"]]},{"q":"Who would be charged if the customs declaration proved inaccurate?","o":["Kobe Precision Tools","Dalton Machine Parts","Transpacific Freight Services","Mr. Tanaka"],"a":1,"k":"細節題：條款 3 'charged to the shipper' → Shipper 欄","n":[["Kobe 精密工具公司（收件人）","","它是 Recipient 收件人，不是 shipper"],["Dalton 機械零件公司（託運人）","","條款 3 'charged to the shipper'，Shipper 即 Dalton"],["Transpacific 貨運公司（承運人）","","它是收費的承運人，不是被收費方"],["Tanaka 先生（收件聯絡人）","","他是收件公司的聯絡人，不是 shipper"]]}]},
{"id":"r990-11","lv":990,"p":7,"k":"email","ti":"Provisional booking for your leadership retreat","tx":"To: Olivia Grant, Fenwick Pharmaceutical Group\nFrom: Marco Bellini, Events Manager, Pinecrest Lodge\nSubject: Provisional booking for your leadership retreat\n\nDear Ms. Grant,\n\nThank you for your inquiry about holding your leadership retreat at Pinecrest Lodge from May 14 to 16. I am pleased to confirm that I have placed a provisional hold on 24 guest rooms and the Lakeview meeting hall.\n\nOur lodge caters almost exclusively to a corporate clientele, and its setting, forty minutes from the nearest town, is conducive to focused discussion. The hall has state-of-the-art projection equipment, and breakfast and lunch are included in the quoted rate of $210 per person per night. Dinner can be arranged at an additional charge.\n\nPlease note that the hold will lapse on March 31 unless we have received a signed agreement and a deposit of 25 percent. The deposit is refundable in full for cancellations made before April 20; after that date it is forfeited.\n\nYou mentioned that some participants have limited mobility. All ground-floor rooms meet current accessibility standards, and I will gladly set those rooms aside for the guests concerned once you tell me how many are needed.\n\nKind regards,\nMarco Bellini","zh":"收件人：Olivia Grant，Fenwick Pharmaceutical Group\n寄件人：Marco Bellini，Pinecrest Lodge 活動經理\n主旨：貴公司主管共識營的暫定訂位\n\nGrant 女士您好：\n\n感謝您來信詢問 5 月 14 日至 16 日在 Pinecrest Lodge 舉辦主管共識營的事宜。很高興通知您，我已為您暫時保留 24 間客房及 Lakeview 會議廳。\n\n本旅館的客群幾乎全是企業客戶，而且地點距離最近的城鎮有四十分鐘車程，環境很適合專心討論。會議廳配有最先進的投影設備；報價為每人每晚 210 美元，已包含早餐和午餐。晚餐可另外付費安排。\n\n請留意，除非我們在 3 月 31 日前收到簽妥的合約及 25% 的訂金，否則這項暫定保留將會失效。若在 4 月 20 日前取消，訂金可全額退還；超過該日期，訂金將被沒收。\n\n您提到有幾位與會者行動不便。本旅館一樓的所有客房都符合現行的無障礙標準，只要您告訴我需要幾間，我很樂意為這幾位貴賓預留。\n\nMarco Bellini 敬上","w":[774,900,916,806,864,907,996,872],"qs":[{"q":"Why did Mr. Bellini write to Ms. Grant?","o":["To request payment of an overdue invoice","To cancel a reservation she made","To invite her to a hotel opening","To reply to her request about booking an event"],"a":3,"k":"主旨題：首句 'Thank you for your inquiry' → 回覆訂場詢問","n":[["要求支付逾期發票","","文中沒提任何發票"],["取消她所做的預約","","他是替她 'placed a provisional hold'，不是取消"],["邀請她參加飯店開幕","","文中沒提開幕活動"],["回覆她關於訂辦活動的詢問","","文中 'Thank you for your inquiry about holding'"]]},{"q":"What must Pinecrest Lodge receive by March 31?","o":["Full payment for 24 rooms","A final list of participants","A signed agreement and a deposit","A choice of dinner menu"],"a":2,"k":"細節題：找 March 31 → 'signed agreement and a deposit'","n":[["24 間房的全額款項","","文中只要求 25 percent 的訂金"],["最終的與會者名單","","只要求之後告知所需無障礙房數，沒訂 3/31 期限"],["簽署的合約與訂金","","文中 'signed agreement and a deposit of 25 percent'"],["晚餐菜單的選擇","","晚餐只說 'arranged at an additional charge'，無期限"]]},{"q":"What would most likely happen if Ms. Grant canceled on April 25?","o":["A fee of $210 would be charged","The booking would be moved to June","The deposit would be refunded in full","Her company would lose its deposit"],"a":3,"k":"推論題：April 25 晚於 April 20 → 'after that date it is forfeited'","n":[["會收取 210 美元的費用","","$210 是每人每晚房價，不是取消費"],["訂位會改到六月","","文中沒提改期"],["訂金會全額退還","","全額退款只限 'before April 20'"],["她的公司會損失訂金","","文中 'after that date it is forfeited'"]]}]},
{"id":"r990-12","lv":990,"p":7,"k":"article","ti":"Verlane Paper reports progress on emissions","tx":"Verlane Paper Reports Progress on Emissions\n\nVerlane Paper, one of the region's foremost packaging manufacturers, announced yesterday that it has cut carbon emissions at its three mills by 18 percent over the past two years, surpassing the 15 percent benchmark it set when it launched its sustainability initiative.\n\nThe company attributes most of the reduction to a $40 million upgrade of its energy infrastructure, including boilers that burn wood waste instead of natural gas. A smaller share came from optimizing delivery routes, which shortened the average truck journey by eleven kilometers.\n\nChief executive Laura Stein acknowledged that the remaining targets will be harder to attain. \"The easy savings are behind us,\" she said. \"Halving our emissions by the end of the decade will entail investment on an unprecedented scale.\" She added that the firm does not intend to buy carbon credits to offset its output, a practice she described as a way of postponing real change.\n\nStakeholders have responded favorably. An independent auditor has verified the figures, and two major retail clients have since extended their supply contracts with Verlane.","zh":"Verlane Paper 公布減排進展\n\n本地區首屈一指的包裝材料製造商之一 Verlane Paper 昨日宣布，過去兩年來，旗下三座紙廠的碳排放量已減少 18%，超越了當初啟動永續發展計畫時所訂下的 15% 基準。\n\n該公司表示，減排成果大部分要歸功於斥資 4,000 萬美元升級能源基礎設施，其中包括改用燃燒廢木料而非天然氣的鍋爐。另有一小部分來自配送路線的最佳化，使每趟貨車的平均行駛距離縮短了十一公里。\n\n執行長 Laura Stein 坦言，剩下的目標會更難達成。她說：「容易省的部分我們都已經做完了。要在這個十年結束前把排放量減半，將需要規模空前的投資。」她還表示，公司不打算購買碳權來抵銷排放量，並形容這種做法只是在拖延真正的改變。\n\n利害關係人的反應相當正面。一位獨立稽核人員已查證這些數據，而且有兩家大型零售客戶隨後與 Verlane 延長了供貨合約。","w":[760,945,752,829,782,998,823,930],"qs":[{"q":"What is the article mainly about?","o":["A new regulation on packaging waste","A paper company's plan to close a mill","An increase in natural gas prices","A manufacturer's progress in reducing emissions"],"a":3,"k":"主旨題：標題 + 首句 'cut carbon emissions ... by 18 percent'","n":[["包裝廢棄物的新法規","","文中沒提任何新法規"],["造紙公司關閉紙廠的計畫","","三座紙廠仍在運作，沒提關廠"],["天然氣價格上漲","","天然氣只是被木料廢棄物取代，沒提漲價"],["製造商在減排上的進展","","文中 'has cut carbon emissions ... by 18 percent'"]]},{"q":"What accounted for most of the reduction?","o":["Shorter delivery routes","An upgrade of energy equipment","A decline in paper production","The purchase of carbon credits"],"a":1,"k":"細節題：找 attributes most → '$40 million upgrade'","n":[["縮短配送路線","","文中說這只是 'A smaller share'"],["能源設備升級","","文中 'most of the reduction' → '$40 million upgrade'"],["紙張產量下降","","文中沒提減產"],["購買碳權","","Stein 說公司 'does not intend to buy carbon credits'"]]},{"q":"The word \"attain\" in paragraph 3 is closest in meaning to","o":["explain","reach","lower","publish"],"a":1,"k":"字義題：harder to attain targets → 達成目標","n":[["(v.) 解釋","","目標無法被『解釋』，語意不通"],["(v.) 達到","","'attain targets' = 達成目標，同 reach"],["(v.) 降低","","『降低目標』與 'harder to' 的語意不合"],["(v.) 公布","","公布目標與『更難』的語意不連貫"]]}]},
{"id":"r990-13","lv":990,"p":7,"k":"memo","ti":"Pilot of flexible scheduling","tx":"MEMO\n\nTo: Customer Support team leaders\nFrom: Anita Rao, Vice President of Human Resources\nDate: September 8\nSubject: Pilot of flexible scheduling\n\nStaff turnover in Customer Support reached 31 percent last year, nearly double the company average. Exit interviews indicate that rigid shift schedules, rather than pay, are the underlying cause. The executive team has therefore authorized a six-month pilot of flexible scheduling, commencing October 1.\n\nUnder the pilot, agents may choose their own start time between 7:00 and 10:00 A.M., provided that each team maintains its required coverage. Team leaders will coordinate the schedules and will have full discretion to resolve conflicts within their respective teams.\n\nWe will gauge the results using three metrics: staff retention, average response time, and customer satisfaction scores. If response times deteriorate by more than 10 percent, the pilot will be suspended.\n\nIt is a common misconception that flexibility lowers productivity. Evidence from our Dublin subsidiary, where a similar program has operated since last year, suggests the opposite. Nevertheless, please report any adverse effects to me promptly.\n\nA briefing for team leaders will be held on September 22 in the boardroom.","zh":"備忘錄\n\n收件人：客服部各組組長\n寄件人：人力資源副總 Anita Rao\n日期：9 月 8 日\n主旨：彈性排班試辦計畫\n\n客服部去年的員工流動率達到 31%，幾乎是全公司平均的兩倍。離職面談顯示，根本原因是僵化的輪班方式，而不是薪資。因此，高階主管團隊已核准自 10 月 1 日起試辦彈性排班，為期六個月。\n\n試辦期間，只要各組維持規定的值班人力，客服人員可以在上午 7:00 到 10:00 之間自行選擇上班時間。組長將負責協調班表，並有完全的決定權處理各自組內的排班衝突。\n\n我們將以三項指標來評估成效：員工留任率、平均回覆時間，以及顧客滿意度分數。如果回覆時間惡化超過 10%，試辦計畫將會暫停。\n\n「彈性會降低生產力」是常見的錯誤觀念。我們的 Dublin 子公司自去年起實施類似的制度，當地的資料顯示情況正好相反。儘管如此，若有任何負面影響，仍請盡快向我回報。\n\n組長說明會將於 9 月 22 日在董事會會議室舉行。","w":[828,890,960,799,994,844,803,967],"qs":[{"q":"Why is the pilot being introduced?","o":["To reduce the number of employees who leave","To extend customer support hours","To lower payroll costs","To prepare for opening a Dublin office"],"a":0,"k":"細節題：turnover 31% + 'rigid shift schedules' → 降離職","n":[["減少離職的員工人數","","文中 'turnover ... 31 percent'，彈性排班是對策"],["延長客服時間","","只是讓員工自選上班時間，須維持 required coverage"],["降低薪資成本","","文中說原因是排班 'rather than pay'，沒提降成本"],["籌備設立 Dublin 辦公室","","Dublin 是已有的子公司，只是參考案例"]]},{"q":"What would cause the pilot to be suspended?","o":["Scheduling conflicts among agents","Complaints from the Dublin subsidiary","A fall in the number of job applicants","A significant worsening of response times"],"a":3,"k":"細節題：找 suspended → 'deteriorate by more than 10 percent'","n":[["員工之間的排班衝突","","組長有權 'resolve conflicts'，不會導致暫停"],["Dublin 子公司的抱怨","","文中沒提 Dublin 的抱怨"],["求職者人數減少","","文中沒提應徵人數"],["回應時間明顯惡化","","文中 'deteriorate by more than 10 percent'"]]},{"q":"What is NOT listed as a measure of the pilot's results?","o":["Average response time","Staff retention","Customer satisfaction scores","Sales revenue"],"a":3,"k":"NOT 題：三項指標是留任率、回應時間、滿意度，營收沒列","n":[["平均回應時間","","文中有：'average response time'"],["員工留任率","","文中有：'staff retention'"],["顧客滿意度分數","","文中有：'customer satisfaction scores'"],["銷售營收","","三項指標中沒有，故為答案"]]}]},
{"id":"r990-14","lv":990,"p":7,"k":"notice","ti":"Mandatory cybersecurity training","tx":"NOTICE: MANDATORY CYBERSECURITY TRAINING\n\nFollowing last month's attempted breach of our customer database, the IT Security Office is instituting annual cybersecurity training for every employee. No customer data was exposed in the incident, but our investigation revealed that the attackers had exploited a password that two staff members had shared by e-mail.\n\nThe training is a preemptive measure, not a punishment. It consists of a 45-minute online course, administered through the staff portal, followed by a short quiz. A score of at least 80 percent is required; those who fall short may retake the quiz as many times as necessary.\n\nIt is imperative that all staff complete the course by November 30. On December 1, the network credentials of anyone who has not done so will be suspended until the training is finished. Only employees on extended leave are exempt, and they must complete the course within two weeks of their return.\n\nContractors with access to company systems are also covered by this requirement. Their respective supervisors are accountable for ensuring compliance.\n\nQuestions may be directed to the IT Security Office at extension 4410.","zh":"公告：資訊安全訓練（全員必修）\n\n繼上個月有人企圖入侵本公司的客戶資料庫之後，資訊安全室即將建立制度，要求每位員工每年接受資訊安全訓練。這起事件中沒有任何客戶資料外洩，但調查發現，攻擊者利用了兩名員工透過電子郵件互傳的一組密碼。\n\n這項訓練是預防性的措施，而不是處罰。內容包括一堂 45 分鐘的線上課程，透過員工入口網站進行，課後有一份簡短的測驗。測驗成績必須達到 80% 以上；未達標者可以重考，次數不限。\n\n所有員工務必在 11 月 30 日前完成課程。自 12 月 1 日起，凡是尚未完成者，其網路登入憑證將被停用，直到完成訓練為止。只有請長假的員工可以免除，但必須在返回工作崗位後兩週內完成課程。\n\n可存取公司系統的外包人員同樣適用這項規定。他們各自的主管須負責確保規定確實遵守。\n\n如有疑問，請洽資訊安全室，分機 4410。","w":[833,854,997,934,902,919,881,775],"qs":[{"q":"Why is the training being introduced?","o":["Customer data was stolen last month","Someone recently tried to break into a company database","A new staff portal has been launched","New legislation requires it"],"a":1,"k":"細節題：首句 'attempted breach of our customer database'","n":[["客戶資料上個月被竊","","文中 'No customer data was exposed'"],["最近有人試圖闖入公司資料庫","","文中 'attempted breach of our customer database'"],["新的員工入口網站上線","","入口網站只是課程的平台，不是原因"],["新法規要求這麼做","","文中沒提任何法規"]]},{"q":"What will happen on December 1 to staff who have not finished the course?","o":["Their quiz scores will be lowered","They will have to pay a fine","Their network access will be suspended","They must attend a class in person"],"a":2,"k":"細節題：找 December 1 → 'credentials ... will be suspended'","n":[["測驗分數會被調降","","文中沒提調降分數"],["必須繳納罰款","","文中沒提罰款，且說 'not a punishment'"],["網路存取權會被停用","","文中 'network credentials ... will be suspended'"],["必須親自去上課","","課程是 'online course'，不是現場"]]},{"q":"The word \"imperative\" in paragraph 3 is closest in meaning to","o":["difficult","customary","optional","essential"],"a":3,"k":"字義題：imperative + 逾期停權 → 非做不可","n":[["(adj.) 困難的","","句子談的是必須完成，不是難度"],["(adj.) 慣例的","","這是新制度，逾期還會停權，不是慣例"],["(adj.) 可選擇的","","與 'required' 及停權的處分相反"],["(adj.) 必要的","","'imperative' = 必須，呼應 'required' 與停權"]]}]},
{"id":"r990-15","lv":990,"p":7,"k":"email","ti":"Re: Missing items in order 77-2093","tx":"To: Jonathan Park\nFrom: Elena Marsh, Customer Care, Corbin Kitchenware\nSubject: Re: Missing items in order 77-2093\n\nDear Mr. Park,\n\nThank you for your message of January 9. Please accept my apologies for the trouble you have had with your order.\n\nHaving looked into the matter, I can confirm that your consignment left our warehouse complete. The box, however, was damaged in transit, and we attribute the loss of two of the six saucepans to that damage. Although the courier disputes its liability, we do not believe that a customer should have to wait while that question is settled.\n\nI have therefore authorized two replacement saucepans, which will be dispatched tomorrow by express service at no cost to you. In addition, the $12 delivery fee you paid will be reimbursed to your credit card within five business days. As a gesture of goodwill, I have also attached a voucher for 15 percent off your next purchase.\n\nIf you would rather not receive replacements, you are entitled to a refund for the missing items instead; simply reply to this message by noon tomorrow.\n\nShould you have any further inquiries, please quote your order number in all correspondence.\n\nYours sincerely,\nElena Marsh","zh":"收件人：Jonathan Park\n寄件人：Elena Marsh，Corbin Kitchenware 顧客服務部\n主旨：回覆：訂單 77-2093 缺少商品\n\nPark 先生您好：\n\n感謝您 1 月 9 日的來信。對於這筆訂單給您帶來的困擾，謹此致上歉意。\n\n經過調查，我可以確認您的貨物離開本公司倉庫時是完整的。然而，箱子在運送途中受損，我們認為六個湯鍋中有兩個遺失，就是這個原因造成的。雖然貨運公司對自身的賠償責任有異議，但我們認為不該讓顧客等到這個問題解決為止。\n\n因此，我已核准補寄兩個湯鍋，明天將以快遞寄出，您不需負擔任何費用。此外，您支付的 12 美元運費將在五個工作天內退回您的信用卡。為了表達我們的誠意，我也附上一張下次購物可享八五折的優惠券。\n\n如果您不想收到補寄的商品，您也有權改為就缺少的商品辦理退款；只要在明天中午前回覆這封信即可。\n\n日後如有任何其他疑問，來信時請一律註明您的訂單編號。\n\nElena Marsh 敬上","w":[832,998,835,960,991,981,939,765],"qs":[{"q":"What is the main purpose of the e-mail?","o":["To explain how an order problem will be resolved","To ask a customer to return damaged goods","To notify a customer of a price increase","To confirm that an order arrived complete"],"a":0,"k":"主旨題：'I have therefore authorized' 補寄 + 退運費 + 折價券","n":[["說明訂單問題將如何解決","","文中 'I have therefore authorized two replacement'"],["要求客戶退回受損商品","","文中沒要求寄回商品"],["通知客戶價格上漲","","文中沒提漲價"],["確認訂單完整送達","","貨物只是 'left our warehouse complete'，到貨少了兩個"]]},{"q":"According to Ms. Marsh, why were two saucepans missing?","o":["The order was sent to the wrong address","The items were out of stock","The warehouse packed too few items","The box was damaged during shipping"],"a":3,"k":"細節題：找 two of six → 'damaged in transit'","n":[["訂單寄錯地址","","文中沒提地址錯誤"],["商品缺貨","","文中說貨 'left our warehouse complete'，非缺貨"],["倉庫少裝了商品","","文中 'left our warehouse complete'，出倉時齊全"],["箱子在運送中受損","","文中 'The box ... was damaged in transit'"]]},{"q":"What is NOT offered to Mr. Park?","o":["Free delivery on future orders","Repayment of the delivery fee","Replacement saucepans","A discount voucher"],"a":0,"k":"NOT 題：補寄、退運費、15% 折價券都有，未來免運沒提","n":[["未來訂單免運費","","只給 15 percent 折價券，沒提免運，故為答案"],["退還運費","","文中有：'$12 delivery fee ... reimbursed'"],["補寄湯鍋","","文中有：'two replacement saucepans'"],["折價券","","文中有：'15 percent off your next purchase'"]]}]},
{"id":"r990-16","lv":990,"p":7,"k":"review","ti":"Review: Tallyview Analytics for small shops","tx":"Tallyview Analytics\nReviewed by Owen Travers, owner of Travers Cycle Shop\nRating: 4.5 out of 5\n\nLike many small enterprises, my shop had years of sales records that nobody ever looked at. I subscribed to Tallyview ten months ago hoping to turn that accumulation of data into something useful, and on the whole it has delivered.\n\nIts chief merit is simplicity. I have no technical expertise, yet the intuitive dashboard took me under an hour to learn. Tallyview complements the accounting program I already use rather than replacing it, and it compiles a sales report automatically every morning. The forecasting tool has been invaluable: last spring it predicted a surge in demand for children's bicycles, and because I ordered extra stock in advance, sales in that category rose 30 percent.\n\nIt is not flawless. Reports cannot be customized as much as I would like, and the mobile app lacks some of the functionality of the desktop version. Support, though, is prompt: both of my inquiries were answered within a day.\n\nAt $49 a month, Tallyview is not the cheapest option, but for a business without a data specialist it is well worth the expenditure.","zh":"Tallyview Analytics\n評論者：Travers Cycle Shop 老闆 Owen Travers\n評分：4.5 分（滿分 5 分）\n\n和許多小型企業一樣，我的店裡累積了好幾年的銷售紀錄，卻從來沒有人去看。十個月前我訂閱了 Tallyview，希望把這些累積下來的資料變成有用的東西，而整體來說，它確實做到了。\n\n它最大的優點就是簡單。我沒有任何技術方面的專業知識，但這個直覺式的儀表板我不到一小時就學會了。Tallyview 是搭配我原本就在用的會計程式一起使用，而不是取代它，而且每天早上會自動彙整出一份銷售報告。預測工具更是幫了大忙：去年春天它預測兒童腳踏車的需求會激增，我因此提前多訂了貨，結果這個類別的銷售額成長了 30%。\n\n它並非毫無缺點。報表可以自訂的程度不如我的期望，而且手機 App 少了桌面版的部分功能。不過客服的回覆很迅速：我兩次詢問都在一天內得到答覆。\n\n每月 49 美元的 Tallyview 並不是最便宜的選擇，但對於沒有資料分析專員的店家來說，這筆支出非常值得。","w":[802,817,877,924,938,894,819,860],"qs":[{"q":"What does the reviewer regard as the software's main advantage?","o":["It is easy to use","It replaces his accounting program","It costs less than rival products","It allows full customization of reports"],"a":0,"k":"細節題：找 chief merit → 'Its chief merit is simplicity'","n":[["容易使用","","文中 'chief merit is simplicity'"],["取代他的會計程式","","文中是 'complements ... rather than replacing'"],["比競爭產品便宜","","文中說 'not the cheapest option'"],["報表可完全客製化","","文中說報表 'cannot be customized as much'，是缺點"]]},{"q":"What happened after the software forecast higher demand?","o":["The shop ran out of stock","The shop sold more children's bicycles","The shop lowered its prices","The shop hired a data specialist"],"a":1,"k":"細節題：找 children's bicycles → 'sales ... rose 30 percent'","n":[["店裡缺貨","","他事先 'ordered extra stock'，沒缺貨"],["店裡賣出更多兒童腳踏車","","文中 'sales in that category rose 30 percent'"],["店裡降價","","文中沒提降價"],["店裡聘請資料專員","","文中 'without a data specialist'，並沒聘請"]]},{"q":"The word \"prompt\" in paragraph 3 is closest in meaning to","o":["automatic","costly","quick","polite"],"a":2,"k":"字義題：prompt 支援 → 'answered within a day' → 迅速","n":[["(adj.) 自動的","","支援由人回覆，重點是 'within a day' 的速度"],["(adj.) 昂貴的","","費用另在末段談，此處講回覆時間"],["(adj.) 迅速的","","'prompt' 支援 = 'answered within a day'"],["(adj.) 有禮貌的","","文中只說一天內回覆，講速度不講禮貌"]]}]},
{"id":"r990-17","lv":990,"p":7,"k":"letter","ti":"Notice concerning your cleaning services contract","tx":"Hartwell Property Management\n40 Mason Avenue\n\nFebruary 11\n\nMr. Stephen Doyle\nBrightSpan Cleaning Services\n\nDear Mr. Doyle,\n\nI am writing with respect to the cleaning contract for the Ridgeway Business Center that our two firms signed last July.\n\nOver the past three months, the standard of service has deteriorated markedly. Our inspections on December 4, January 8, and February 5 each found that the lobby floors had not been polished and that waste had been left uncollected on the third and fourth floors. These were not isolated oversights. They deviate from the specifications in section 3 of the agreement, and two tenants have made formal complaints.\n\nUnder section 9, either party may terminate the contract if the other fails to remedy a breach within 30 days of written notice. Please regard this letter as such notice. Should the problems be corrected by March 13, the contract will continue as before. Otherwise, your services will cease on March 31, and we will withhold payment for any work found deficient in the meantime.\n\nI would welcome a meeting to discuss how this matter might be resolved and am available any afternoon next week.\n\nYours sincerely,\nPatricia Nolan\nFacilities Director","zh":"Hartwell Property Management\n40 Mason Avenue\n\n2 月 11 日\n\nStephen Doyle 先生\nBrightSpan Cleaning Services\n\nDoyle 先生您好：\n\n本函是關於我們兩家公司去年七月就 Ridgeway Business Center 所簽訂的清潔合約。\n\n過去三個月來，服務水準明顯惡化。我們在 12 月 4 日、1 月 8 日和 2 月 5 日的檢查中，每次都發現大廳地板沒有打蠟拋光，三樓和四樓的垃圾也沒有清運。這些並不是偶發的疏忽。這些情況不符合合約第 3 條所訂的規格，而且已有兩家租戶提出正式申訴。\n\n依據第 9 條，若一方在收到書面通知後 30 天內未能改正違約情事，另一方得終止合約。請將本函視為該項書面通知。如果問題在 3 月 13 日前改善，合約將照常繼續。否則，貴公司的服務將於 3 月 31 日終止，而且在此期間凡經查驗不合格的工作，我們都將暫不付款。\n\n我很樂意安排會面，討論如何解決這件事；下週任何一天的下午我都有空。\n\n設施處長\nPatricia Nolan 敬上","w":[853,967,830,976,809,970,854,935],"qs":[{"q":"What is the purpose of the letter?","o":["To warn a contractor that its service must improve","To request a price quotation","To thank a company for its work","To renew a cleaning contract"],"a":0,"k":"主旨題：'Please regard this letter as such notice' → 警告改善","n":[["警告承包商必須改善服務","","文中 'regard this letter as such notice' 並限期改善"],["要求提供報價","","文中沒提報價"],["感謝公司的服務","","文中 'standard of service has deteriorated'，是批評"],["續簽清潔合約","","文中是可能終止合約，不是續約"]]},{"q":"What will happen if the problems are corrected by March 13?","o":["A new agreement will be signed","The contract will end on March 31","The contract will remain in effect","Payment will be withheld"],"a":2,"k":"細節題：找 March 13 → 'the contract will continue as before'","n":[["會簽署新協議","","文中 'continue as before'，不需新協議"],["合約將在 3 月 31 日結束","","那是未改善的後果：'Otherwise ... March 31'"],["合約仍然有效","","文中 'the contract will continue as before'"],["款項將被扣留","","扣款屬 'Otherwise' 的情況，且只針對不合格工作"]]},{"q":"The phrase \"with respect to\" in paragraph 1 is closest in meaning to","o":["instead of","concerning","in honor of","in spite of"],"a":1,"k":"字義題：with respect to the contract → 關於","n":[["(prep.) 而不是","","『取代』不合，信是在談合約這件事"],["(prep.) 關於","","'with respect to the cleaning contract' = 關於合約"],["(prep.) 為了向...致敬","","『致敬』與談合約的語意不符"],["(prep.) 儘管","","『儘管』語意不通，後面不是讓步內容"]]}]},
{"id":"r990-18","lv":990,"p":7,"k":"article","ti":"Local coffee roaster turns to franchising","tx":"Local Coffee Roaster Turns to Franchising\n\nWhen Marcus Bell opened Graystone Coffee Roasters in a converted garage eleven years ago, he did not imagine building a national brand. Today the entrepreneur runs nine company-owned cafés, and last week he announced plans to franchise the concept, with twenty franchised outlets to open over the next three years.\n\nMr. Bell said franchising was the only viable route to rapid growth. \"Opening a café costs us around $400,000,\" he explained. \"We could not raise that much capital for dozens of sites without handing a substantial share of equity to outside investors, and I was not willing to do that.\" Franchisees will instead bear the opening costs and pay Graystone 6 percent of their sales.\n\nDespite inflation in the price of coffee beans, the company's profitability has held up, a result Mr. Bell attributes to a loyal clientele and a diversified menu; food now accounts for a third of revenue.\n\nProspective franchisees must have at least five years of managerial experience in retail or hospitality. A shortlist of applicants will be drawn up in March, and those selected will undergo eight weeks of training at Graystone's roasting plant.","zh":"在地咖啡烘焙商改走加盟路線\n\n十一年前，Marcus Bell 在一間改建的車庫裡開設 Graystone Coffee Roasters 時，並沒有想過要打造全國性的品牌。如今，這位創業家經營九家直營咖啡店，上週他更宣布計畫開放加盟，預計在未來三年內開設二十家加盟店。\n\nBell 先生表示，加盟是快速成長唯一可行的途徑。他解釋：「我們開一家咖啡店大約要花 40 萬美元。要為幾十個據點籌措這麼多資本，就不得不把相當大比例的股權讓給外部投資人，而我不願意這麼做。」改採加盟後，開店成本將由加盟主負擔，加盟主並須將營業額的 6% 支付給 Graystone。\n\n儘管咖啡豆價格上漲，公司的獲利能力依然維持穩定，Bell 先生把這個成果歸功於忠實的顧客群和多樣化的菜單；目前餐點已占營收的三分之一。\n\n有意加盟者必須具備至少五年的零售業或餐旅業管理經驗。公司將在三月擬定申請人的候選名單，獲選者將在 Graystone 的烘焙廠接受八週的訓練。","w":[750,993,866,781,811,773,755,806],"qs":[{"q":"What is the article mainly about?","o":["A new training school for café managers","A sharp rise in coffee bean prices","The sale of a café chain to investors","A coffee company's plan to grow through franchising"],"a":3,"k":"主旨題：標題 + 'announced plans to franchise the concept'","n":[["咖啡店經理的新訓練學校","","訓練只是加盟者的條件，不是主題"],["咖啡豆價格大漲","","豆價只是背景，且說獲利 'has held up'"],["連鎖咖啡店賣給投資人","","Bell 不願 'handing ... equity to outside investors'"],["咖啡公司以加盟方式擴張的計畫","","文中 'plans to franchise the concept'"]]},{"q":"Why did Mr. Bell decide to franchise his business?","o":["He could not find suitable café sites","His customers asked for more locations","He did not want to give up much ownership","His company-owned cafés were losing money"],"a":2,"k":"細節題：找 Bell 的理由 → 'not willing' 讓出 equity","n":[["找不到合適的店面","","文中沒提找不到店面"],["顧客要求更多據點","","文中沒提顧客要求"],["不想讓出太多所有權","","文中 'handing a substantial share of equity' 他不願意"],["自營店虧損","","文中 'profitability has held up'，並未虧損"]]},{"q":"What is NOT mentioned as something franchisees will do?","o":["Give Graystone a share of their sales","Complete eight weeks of training","Pay the cost of opening a café","Roast their own coffee beans"],"a":3,"k":"NOT 題：抽成、八週訓練、自付開店費都有；沒提自己烘豆","n":[["把銷售額的一部分交給 Graystone","","文中有：'6 percent of their sales'"],["完成八週訓練","","文中有：'eight weeks of training'"],["負擔開店成本","","文中有：'bear the opening costs'"],["自己烘焙咖啡豆","","文中只說在烘焙廠受訓，沒說自己烘豆"]]}]},
{"id":"r990-19","lv":990,"p":7,"k":"message","ti":"Flight delay before the board meeting","tx":"Diane Foster (6:48 A.M.): Kenji, bad news. My flight from Portland is delayed at least three hours because of fog, and we have not even boarded yet. I will not make the 10:00 board meeting.\n\nKenji Watanabe (6:53 A.M.): Understood. The chairperson will not want to postpone, since two directors fly home tonight. Shall I ask to move your item to the end of the agenda?\n\nDiane Foster (6:55 A.M.): Even then I would miss it. I would rather you presented the acquisition proposal in my place. You compiled most of the figures, and you know the justification for the price as well as I do.\n\nKenji Watanabe (6:58 A.M.): I am comfortable with the figures, but the directors will ask about the implications for our debt. That is your area.\n\nDiane Foster (7:01 A.M.): Fair point. I will write a one-page note on that now and e-mail it before I board. If they need more, they can call me after I land, around 11:30.\n\nKenji Watanabe (7:03 A.M.): That works. I will inform the board secretary and make sure your absence is recorded in the minutes.\n\nDiane Foster (7:04 A.M.): Thanks. Let's debrief this afternoon.","zh":"Diane Foster（上午 6:48）：Kenji，有個壞消息。我從 Portland 出發的班機因為起霧，至少要延誤三個小時，我們到現在都還沒登機。10:00 的董事會我是趕不上了。\n\nKenji Watanabe（上午 6:53）：了解。董事長應該不會想延期，因為有兩位董事今晚就要搭機回去。要不要我去問問看，能不能把您的議案挪到議程的最後？\n\nDiane Foster（上午 6:55）：就算那樣我也趕不上。我希望由你代替我報告收購提案。大部分的數字都是你彙整的，而且這個價格的理由，你和我一樣清楚。\n\nKenji Watanabe（上午 6:58）：數字的部分我沒問題，但董事們一定會問到這對公司負債的影響。那是您的專長。\n\nDiane Foster（上午 7:01）：說得有道理。我現在就寫一頁關於這部分的說明，登機前用電子郵件寄給你。如果他們需要更多資訊，可以等我落地後打電話給我，大約是 11:30。\n\nKenji Watanabe（上午 7:03）：這樣可行。我會通知董事會秘書，並確認您缺席一事有記入會議紀錄。\n\nDiane Foster（上午 7:04）：謝謝。我們今天下午再來檢討一下。","w":[849,759,807,938,787,751,783,999],"qs":[{"q":"Why is Ms. Foster unable to attend the meeting?","o":["The meeting was moved to an earlier time","She is busy compiling figures","Her flight has been delayed","She has to fly home tonight"],"a":2,"k":"細節題：Diane 首句 'flight ... is delayed at least three hours'","n":[["會議被提前","","文中會議仍在 10:00，沒提提前"],["她忙著整理數據","","整理數據的是 Kenji：'You compiled most of the figures'"],["她的班機延誤","","文中 'My flight from Portland is delayed'"],["她今晚要飛回家","","今晚飛回家的是 'two directors'"]]},{"q":"What does Ms. Foster ask Mr. Watanabe to do?","o":["Book her a seat on another flight","Postpone the board meeting","Present a proposal on her behalf","Move her item to the end of the agenda"],"a":2,"k":"細節題：找請求 → 'I would rather you presented ... in my place'","n":[["替她訂另一班飛機","","文中沒提改訂班機"],["延後董事會","","是 Kenji 說主席不想延期，她沒要求"],["代替她報告提案","","文中 'rather you presented the acquisition proposal'"],["把她的議程移到最後","","那是 Kenji 的提議，她說 'Even then I would miss it'"]]},{"q":"What will Ms. Foster most likely do next?","o":["Prepare a short document about debt","Lower the proposed purchase price","Telephone the chairperson","Record the minutes of the meeting"],"a":0,"k":"推論題：Diane 7:01 'I will write a one-page note on that now'","n":[["寫一份有關債務的簡短文件","","文中 'one-page note' 談 'implications for our debt'"],["調降擬議的收購價","","文中沒提調價"],["打電話給董事會主席","","是董事可能在她降落後打給她，不是她打"],["記錄會議紀錄","","Kenji 只確認她缺席被記入 minutes，記錄者不是她"]]}]},
{"id":"r990-20","lv":990,"p":7,"k":"announcement","ti":"Thornbury Group names new chief operating officer","tx":"Thornbury Group Names New Chief Operating Officer\n\nThornbury Group is pleased to announce that Priya Raman has been appointed chief operating officer, effective July 1. She succeeds Gerald Hsu, who is retiring after 26 years with the company.\n\nMs. Raman joined Thornbury nine years ago as a logistics analyst and has led our Singapore subsidiary since 2021. Under her leadership, the subsidiary restructured its distribution network, cut delivery times by a fifth, and attained the highest customer retention rate of any unit in the group. Her pragmatic approach and her ability to foster cooperation between departments exemplify the qualities the board was seeking, and the directors voted unanimously in favor of her appointment.\n\nIn her new role, Ms. Raman will oversee manufacturing, procurement, and distribution in all eleven countries where Thornbury operates. Her foremost priority will be to consolidate the group's four regional warehouses in Europe into two by the end of next year.\n\nMr. Hsu will stay on in an advisory capacity until September 30 to facilitate the transition. A reception in recognition of his service will be held at headquarters on June 27, and all employees are welcome.","zh":"Thornbury Group 任命新任營運長\n\nThornbury Group 很高興宣布，Priya Raman 已獲任命為營運長，自 7 月 1 日起生效。她將接替 Gerald Hsu，Hsu 先生在公司服務 26 年後即將退休。\n\nRaman 女士九年前加入 Thornbury 擔任物流分析師，自 2021 年起領導本集團的新加坡子公司。在她的帶領下，該子公司重整了配送網路，將送貨時間縮短五分之一，並達到全集團各單位中最高的顧客留存率。她務實的作風，以及促進跨部門合作的能力，正是董事會所尋求特質的最佳典範，董事們一致投票贊成這項任命。\n\n就任新職後，Raman 女士將督導 Thornbury 在全部十一個營運國家的製造、採購和配送業務。她的首要任務是在明年年底前，把集團在歐洲的四座區域倉庫整併為兩座。\n\nHsu 先生將以顧問身分留任至 9 月 30 日，以協助交接順利進行。表彰他多年貢獻的茶會將於 6 月 27 日在總部舉行，歡迎全體員工參加。","w":[949,805,936,803,898,940,923,942],"qs":[{"q":"What is the purpose of the announcement?","o":["To announce a merger with another firm","To introduce a newly appointed executive","To invite employees to a training session","To report the closure of a subsidiary"],"a":1,"k":"主旨題：首句 'has been appointed chief operating officer'","n":[["宣布與另一家公司合併","","文中沒提併購"],["介紹新任命的主管","","文中 'has been appointed chief operating officer'"],["邀請員工參加訓練課程","","邀請的是 June 27 的歡送會，不是訓練"],["報告子公司關閉","","新加坡子公司表現亮眼，沒提關閉"]]},{"q":"What did the Singapore subsidiary achieve under Ms. Raman?","o":["It shortened its delivery times","It lowered its manufacturing costs","It doubled its number of warehouses","It expanded into eleven countries"],"a":0,"k":"細節題：找 Singapore → 'cut delivery times by a fifth'","n":[["縮短了配送時間","","文中 'cut delivery times by a fifth'"],["降低了製造成本","","文中沒提製造成本"],["倉庫數量增加一倍","","四合為二是她未來的任務，且在歐洲"],["擴展到十一個國家","","eleven countries 是整個集團的營運國家數"]]},{"q":"Which area is NOT mentioned as part of Ms. Raman's new responsibilities?","o":["Manufacturing","Marketing","Distribution","Procurement"],"a":1,"k":"NOT 題：新職責是 manufacturing、procurement、distribution","n":[["製造","","文中有：'oversee manufacturing'"],["行銷","","文中職責清單沒有行銷，故為答案"],["配送","","文中有：'distribution'"],["採購","","文中有：'procurement'"]]}]},
{"id":"r990-21","lv":990,"p":6,"k":"email","ti":"Your first week at Calloway Engineering","tx":"To: New employees starting June 2\nFrom: Rachel Kim, Human Resources\nSubject: Your first week at Calloway Engineering\n\nDear new colleagues,\n\nWelcome to Calloway Engineering. To help you settle in quickly, we have prepared a comprehensive onboarding program that will occupy most of your first week.\n\nOn Monday morning, please report to the reception desk in the main lobby by 8:45, where you [1] ------- by a member of my team and issued a security badge. The morning session covers company policies, payroll procedures, and your leave entitlements. After lunch, each of you will be introduced to the mentor who has been [2] ------- to guide you through your first three months.\n\nTuesday through Thursday will be spent in your respective departments, where you will shadow experienced colleagues and learn the workflow. On Friday, all new staff will convene again for a short debrief with the managing director.\n\nPlease bring photo identification and your bank details on the first day. [3] -------, we will be unable to add you to the payroll in time for the June payment.\n\nIf you have any questions beforehand, do not hesitate to contact me.\n\nBest regards,\nRachel Kim","zh":"收件人：6 月 2 日到職的新進員工\n寄件人：人力資源部 Rachel Kim\n主旨：您在 Calloway Engineering 的第一週\n\n各位新同事好：\n\n歡迎加入 Calloway Engineering。為了幫助各位盡快適應，我們準備了一套完整的入職培訓計畫，將占去各位第一週的大部分時間。\n\n星期一早上，請在 8:45 前到大廳的接待櫃台報到，屆時我的團隊成員會在那裡迎接您，並發給您門禁識別證。上午的課程涵蓋公司政策、薪資作業流程，以及您應享有的休假權益。午餐後，我們會為每位新人介紹指定的輔導員，他們將在您到職的前三個月帶領您。\n\n星期二到星期四，各位將待在各自的部門，跟在資深同事身邊觀摩，並熟悉工作流程。星期五，所有新進員工會再次集合，與總經理進行簡短的檢討座談。\n\n第一天請攜帶附照片的身分證件及您的銀行帳戶資料。否則，我們將來不及把您加入薪資名單，趕不上六月的發薪。\n\n在此之前如有任何問題，歡迎隨時與我聯絡。\n\nRachel Kim 敬上","w":[880,814,753,831,977,868,754,956],"qs":[{"q":"[1]","o":["are meeting","will be met","will meet","have met"],"a":1,"k":"時態／語態：you 被接待並 'issued' 徽章，'by' 帶出施動者 → 未來被動","n":[["(進行式) 正在見面","","主動語態，後面缺受詞，也無法接 'by a member'"],["(未來被動) 將被接待","will be + p.p. + by","'by a member of my team' + 'issued' 並列，週一尚未發生"],["(未來式) 將會見","","主動語態，缺受詞，與 'by a member' 矛盾"],["(完成式) 已經見過","","主動且缺受詞；週一是未來，不能用現在完成"]]},{"q":"[2]","o":["depreciated","deterred","designated","disclosed"],"a":2,"k":"單字：has been ___ to guide → 被指派去指導 → designated","n":[["(v.) 貶值","","語意不通，導師不會被『貶值』"],["(v.) 阻止","","deter 要接 from + V-ing，與 'to guide' 不合"],["(v.) 指派","be designated to + V","'the mentor ... designated to guide you' 導師被指派"],["(v.) 揭露","","disclose 不接 to V，語意也不通"]]},{"q":"[3]","o":["Likewise","Meanwhile","Therefore","Otherwise"],"a":3,"k":"連接詞：前句要求帶資料、後句說無法入薪資 → 否則 Otherwise","n":[["(adv.) 同樣地","","表示並列相似，文中是『不帶就會…』的後果"],["(adv.) 同時","","表示同時發生，沒有條件與後果的關係"],["(adv.) 因此","","因果方向反了：不是帶了資料所以無法入薪資"],["(adv.) 否則","Otherwise, + 後果","'bring ... Otherwise, we will be unable' 條件的反面"]]}]},
{"id":"r990-22","lv":990,"p":6,"k":"memo","ti":"Changes to this year's performance appraisals","tx":"MEMO\n\nTo: All department heads\nFrom: Thomas Becker, Director of Human Resources\nSubject: Changes to this year's performance appraisals\n\nAnnual appraisals will commence on November 3. In response to feedback from last year, we are making two changes intended to make the process fairer and more transparent.\n\nFirst, managers will no longer rely [1] ------- on their own observations. Each appraisal will also draw on comments solicited from two of the employee's colleagues and, in the case of supervisors, from their subordinates.\n\nSecond, every rating must be supported by concrete examples. A rating given without [2] ------- may be perceived as arbitrary and will be returned to the manager for revision.\n\nCompleted forms are due by November 28. Because salary adjustments and incentive payments are calculated from the final ratings, any forms submitted after that date [3] ------- the December payroll for the entire department.\n\nManagers are accountable for the accuracy of every appraisal they sign. Training sessions on the new format will be held on October 20 and 22, and attendance is mandatory.","zh":"備忘錄\n\n收件人：各部門主管\n寄件人：人力資源處長 Thomas Becker\n主旨：今年績效考核的變更事項\n\n年度考核將於 11 月 3 日開始。因應去年收到的意見，我們將做兩項調整，目的是讓考核過程更公平、更透明。\n\n第一，主管不再只憑自己的觀察來評分。每一份考核還會參考向該員工的兩位同事徵詢而來的意見；如果受評者是主管，也會徵詢其下屬的意見。\n\n第二，每一項評等都必須有具體事例佐證。沒有正當理由的評等可能會被視為主觀武斷，並將退回給主管修改。\n\n填妥的表格須於 11 月 28 日前繳交。由於調薪和獎金都是根據最終評等計算，任何在該日期之後才交的表格，都會延誤整個部門十二月的薪資發放。\n\n主管必須為自己簽核的每一份考核的正確性負責。新格式的說明訓練將於 10 月 20 日及 22 日舉行，所有主管都必須參加。","w":[812,974,916,933,847,787,889,856],"qs":[{"q":"[1]","o":["exclusively","unanimously","respectively","approximately"],"a":0,"k":"單字：no longer rely ___ on own observations → 不再『只』靠","n":[["(adv.) 僅僅、只","rely exclusively on + N","'no longer rely exclusively on'；後句 'also draw on'"],["(adv.) 一致地","","常修飾表決或同意，不能修飾 rely on"],["(adv.) 分別地","","要有兩組對應項才能用，此處不適用"],["(adv.) 大約","","修飾數字，語意不通"]]},{"q":"[2]","o":["justification","justifiably","justified","justify"],"a":0,"k":"詞性：介系詞 without 後 → 要接名詞 justification","n":[["(n.) 正當理由","without + N","without 後接名詞：'without justification'"],["(adv.) 合理地","","副詞不能當 without 的受詞"],["(adj.) 正當的","","形容詞後面沒有名詞可修飾，不能單獨接在 without 後"],["(v.) 證明正當","","介系詞後不能直接接動詞原形"]]},{"q":"[3]","o":["will delay","have delayed","delayed","delaying"],"a":0,"k":"時態／語態：規則預告 'any forms submitted after' → 未來式","n":[["(未來式) 將延誤","","主詞是 'any forms'，規則的後果用 will + 原形"],["(完成式) 已經延誤","","現在完成表示已發生，但逾期尚未發生"],["(過去式) 延誤了","","文法可以，但時間不合：這是對未來的預告"],["(V-ing) 延誤","","缺助動詞，不能單獨當述語"]]}]},
{"id":"r990-23","lv":990,"p":6,"k":"notice","ti":"Temporary closure of the east parking garage","tx":"NOTICE TO EMPLOYEES AND VISITORS\n\nTemporary Closure of the East Parking Garage\n\nThe east parking garage will be closed from Monday, August 4, through Friday, August 22, while a contractor resurfaces levels 1 to 3 and installs new lighting. The work, originally planned for the spring, [1] ------- because of a delay in obtaining a building permit.\n\nDuring the closure, staff are asked to use the west garage or the surface lot on Dover Street. To [2] ------- the shortage of spaces, the company will subsidize monthly transit passes for August and run a shuttle from Dover Street to the main entrance every fifteen minutes. To maintain accessibility, the spaces reserved for visitors with limited mobility have been moved to the front of the west garage.\n\nAny vehicle remaining in the east garage after 6:00 P.M. on Sunday, August 3, will be towed at the owner's expense. [3] -------, we urge you to move your car before the weekend.\n\nPlease expect intermittent noise near the east entrance of the premises while the work is under way. We apologize for the inconvenience and thank you for your cooperation.","zh":"員工及訪客公告\n\n東側停車場暫時關閉\n\n東側停車場將自 8 月 4 日星期一起關閉，至 8 月 22 日星期五為止，期間承包商將重鋪一至三樓的地面，並安裝新的照明設備。這項工程原定在春季進行，但因為建築許可證延遲核發而延期。\n\n關閉期間，請同仁改用西側停車場或 Dover Street 的平面停車場。為了緩解車位不足的情況，公司將補助八月份的大眾運輸月票，並安排接駁車，每十五分鐘一班，從 Dover Street 開往正門。為了維持無障礙通行，保留給行動不便訪客的車位已移到西側停車場的前方。\n\n8 月 3 日星期日下午 6:00 之後仍停在東側停車場的車輛，將被拖吊，費用由車主負擔。因此，我們呼籲您在週末前把車移走。\n\n施工期間，本場區東側入口附近預計會有斷斷續續的噪音。造成不便，敬請見諒，並感謝您的配合。","w":[766,984,972,872,913,904,758],"qs":[{"q":"[1]","o":["postponed","was postponed","is postponing","has postponed"],"a":1,"k":"時態／語態：work 被延後 + 'originally planned' → 過去被動","n":[["(p.p.) 被延後","","缺 be 動詞，句子沒有述語"],["(過去被動) 被延後了","was + p.p.","work 是被延後的對象；'originally planned for the spring'"],["(進行式) 正在延後","","主動語態，缺受詞，work 不會自己延後別的事"],["(完成式) 已延後","","主動語態，缺受詞，主詞 work 無法 postpone"]]},{"q":"[2]","o":["advocate","accumulate","authorize","alleviate"],"a":3,"k":"單字：To ___ the shortage of spaces → 緩解車位不足","n":[["(v.) 提倡","","advocate 指公開支持主張，不能搭配 shortage"],["(v.) 累積","","累積車位短缺，與後面補助措施的目的相反"],["(v.) 授權","","authorize 要搭配許可的事項，語意不通"],["(v.) 緩解","alleviate + shortage/problem","補助通勤月票與接駁車是為了減輕短缺"]]},{"q":"[3]","o":["Nevertheless","Similarly","Accordingly","Otherwise"],"a":2,"k":"連接詞：前句說會被拖吊、後句呼籲移車 → 因此 Accordingly","n":[["(adv.) 儘管如此","","表讓步，前後並非轉折"],["(adv.) 同樣地","","表相似並列，這裡是後果引出行動"],["(adv.) 因此","Accordingly, + 建議或行動","'will be towed' → 因此 'we urge you to move'"],["(adv.) 否則","","文法可以，但前句已是後果，沒有可被『否則』的條件"]]}]},
{"id":"r990-24","lv":990,"p":6,"k":"letter","ti":"Preliminary approval of your business loan","tx":"Summit Trust Bank\nCommercial Lending Department\n\nMay 19\n\nMs. Angela Rossi\nRossi Catering Ltd.\n\nDear Ms. Rossi,\n\nWe are pleased to inform you that your application for a business loan of $150,000 has received preliminary approval from our lending committee.\n\nThe loan will be secured by the kitchen equipment that you have offered as [1] -------. An independent appraisal has valued this equipment at $210,000, which is sufficient for the amount requested. Interest will accrue at a fixed annual rate of 6.2 percent, and the loan is to be repaid in monthly installments over five years.\n\nBefore final approval can be granted, you are required to [2] ------- any outstanding debts owed by your company and to provide audited financial statements for the last two fiscal years. These must reach us by June 6.\n\nOnce we [3] ------- these documents, a definitive decision will be issued within five business days. Please note that a provision in the loan agreement entitles the bank to review the interest rate if repayments are missed.\n\nShould you have any inquiries, please contact me directly.\n\nYours sincerely,\nEdward Lin\nSenior Lending Officer","zh":"Summit Trust Bank\n商業貸款部\n\n5 月 19 日\n\nAngela Rossi 女士\nRossi Catering Ltd.\n\nRossi 女士您好：\n\n很高興通知您，您申請的 150,000 美元企業貸款已獲得本行貸款審查委員會的初步核准。\n\n這筆貸款將以您提供作為擔保品的廚房設備作擔保。經獨立鑑價，這批設備的價值為 210,000 美元，足以支應您申請的金額。利息將以 6.2% 的固定年利率計算，貸款須在五年內按月分期償還。\n\n在最終核准之前，您必須揭露貴公司所有尚未清償的債務，並提供最近兩個會計年度經會計師查核的財務報表。這些文件必須在 6 月 6 日前送達本行。\n\n我們收到這些文件後，將在五個工作天內做出最終決定。請注意，依貸款合約中的一項條款，若有未按期還款的情形，本行有權重新審視利率。\n\n如有任何疑問，請直接與我聯絡。\n\n資深貸款專員\nEdward Lin 敬上","w":[863,846,812,965,922,875,891,816],"qs":[{"q":"[1]","o":["correspondence","clientele","compliance","collateral"],"a":3,"k":"單字：loan secured by equipment 'offered as ___' → 抵押品","n":[["(n.) 書信往來","","語意不通，設備不能當作書信往來提供"],["(n.) 顧客群","","設備不是顧客群"],["(n.) 遵守","","'offered as compliance' 語意不通"],["(n.) 擔保品","offer ... as collateral","文中 'loan will be secured by the equipment'"]]},{"q":"[2]","o":["disclosing","disclose","disclosure","disclosed"],"a":1,"k":"詞性：'required to' 的 to 是不定詞 → 後接原形動詞","n":[["(V-ing) 揭露","","to 在此是不定詞標記，後面接原形，不接 V-ing"],["(v.) 揭露","be required to + 原形","文中 'required to disclose any outstanding debts'"],["(n.) 揭露","","名詞後不能再直接帶受詞 'any outstanding debts'"],["(p.p.) 被揭露","","to 後接過去分詞，形式錯誤"]]},{"q":"[3]","o":["will receive","had received","have received","received"],"a":2,"k":"時態：Once 時間子句 + 主句 will be issued → 現在完成代替未來","n":[["(未來式) 將收到","","時間子句不用 will，要用現在式或現在完成"],["(過去完成) 已收到","","過去完成與主句的未來 will be issued 不搭"],["(現在完成) 已收到","Once + 現在完成, 未來式","'Once we have received ...' 現在完成表示未來某時已完成"],["(過去式) 收到了","","過去式與主句的未來時間不合"]]}]},
{"id":"r990-25","lv":990,"p":6,"k":"article","ti":"Halden Stores posts stronger second quarter","tx":"Halden Stores Posts Stronger Second Quarter\n\nHalden Stores, the home-furnishings retailer, reported yesterday that second-quarter revenue rose 9 percent to $412 million, [1] ------- analysts' forecasts for the third consecutive quarter.\n\nChief executive Nora Fielding attributed the result to a surge in online orders and to the firm's decision last year to consolidate its two distribution centers, which reduced delivery costs. Profit margins, [2] -------, narrowed slightly as inflation pushed up the cost of imported lumber.\n\nThe company said it does not intend to raise prices in the foreseeable future. Instead, it will seek to offset higher material costs by buying more of its products from domestic suppliers.\n\n[3] ------- The board has approved a dividend of 45 cents per share, up from 40 cents a year earlier, payable on September 15.\n\nHalden's shares closed 3 percent higher following the announcement. The retailer, which operates 140 stores, expects revenue for the full fiscal year to grow by between 6 and 8 percent.","zh":"Halden Stores 第二季業績走強\n\n居家家具零售商 Halden Stores 昨日公布，第二季營收成長 9%，達到 4.12 億美元，連續第三季超越分析師的預測。\n\n執行長 Nora Fielding 把這項成果歸功於線上訂單激增，以及公司去年決定整併兩座配送中心，因而降低了配送成本。不過，由於通貨膨脹推升了進口木材的成本，利潤率略為縮小。\n\n該公司表示，在可預見的未來不打算調漲售價。相反地，公司會設法向國內供應商採購更多產品，以抵銷上漲的原料成本。\n\n股東也將分享到業績改善的成果。董事會已核准每股配發 45 美分的股息，高於一年前的 40 美分，將於 9 月 15 日發放。\n\n消息公布後，Halden 的股價收盤上漲 3%。這家擁有 140 家門市的零售商預期，整個會計年度的營收將成長 6% 到 8%。","w":[945,998,992,942,755,867,990,808],"qs":[{"q":"[1]","o":["deterring","curtailing","withholding","surpassing"],"a":3,"k":"單字：營收 rose 9% ___ analysts' forecasts → 超越預期","n":[["(v.) 阻止","","與 'revenue rose' 的好消息語意不合"],["(v.) 削減","","營收成長不是削減預測"],["(v.) 扣留","","withhold a forecast 指不公布預測，此處語意不通"],["(v.) 超越","surpass + 預期、預測","文中 '9 percent' → 'surpassing' 預期"]]},{"q":"[2]","o":["therefore","otherwise","however","moreover"],"a":2,"k":"連接詞：營收成長、利潤率 'narrowed slightly' → 轉折 however","n":[["(adv.) 因此","","因果不合：營收成長不會導致利潤率縮小"],["(adv.) 否則","","前句沒有條件，不能用 otherwise"],["(adv.) 然而","插入語：, however,","營收上升 vs. 利潤率下滑，前後對比"],["(adv.) 此外","","表遞進，但前後是好壞對比，不是補充"]]},{"q":"[3]","o":["Several stores are scheduled to close next month.","Shareholders will also share in the improved results.","Analysts had expected revenue to rise much more.","Customers have complained about slow deliveries."],"a":1,"k":"句子插入：後句談股利 → 空格要引出股東受惠","n":[["數家門市預定下個月關閉","","與後句的股利無關，也與好消息的脈絡不合"],["股東也將分享營運成果","also 呼應前面營收成長","'Shareholders will also share' 引出後句股利"],["分析師原本預期營收成長更多","","與前文 surpassing forecasts 矛盾"],["顧客抱怨配送太慢","","與前文降低配送成本及後句股利都無關"]]}]},
{"id":"r990-26","lv":990,"p":6,"k":"advertisement","ti":"The Aldgate Hotel: built for business","tx":"The Aldgate Hotel: Built for Business\n\nLocated two blocks from the financial district, the Aldgate Hotel has served a corporate clientele for more than forty years. Following a year-long renovation, we are proud to reopen with facilities designed around the way professionals actually work.\n\nEvery guest room now features an ergonomic desk, high-speed connectivity, and soundproofed windows, creating an environment [1] ------- to concentration. Our six meeting rooms accommodate between 8 and 120 people, and each [2] ------- with state-of-the-art presentation equipment. A dedicated events team will coordinate the logistics of your meeting, from catering to printing, so that you can focus on your agenda.\n\nWhen the working day is over, guests can relax in our rooftop restaurant or make use of the fitness center, which is open around the clock.\n\nGuests staying three nights or more are [3] ------- to complimentary airport transfers and late checkout. Rates start at $189 per night, and companies that book at least fifty room nights a year qualify for our corporate discount.\n\nTo make a reservation or to request a quotation for an event, call 555-0163 or visit our website.","zh":"Aldgate Hotel：為商務而生\n\nAldgate Hotel 距離金融區只有兩個街區，四十多年來一直服務企業客群。經過為期一年的整修，我們很榮幸重新開幕，所有設施都是依照專業人士實際的工作方式而設計。\n\n現在每間客房都備有符合人體工學的書桌、高速網路連線和隔音窗，營造出有助於專注的環境。我們的六間會議室可容納 8 到 120 人，每一間都配備最先進的簡報設備。專屬的活動團隊會為您協調會議的各項後勤事務，從餐飲到文件印製一手包辦，讓您可以專心在議程上。\n\n結束一天的工作後，房客可以到頂樓餐廳放鬆一下，或使用全天候開放的健身中心。\n\n住宿三晚以上的房客，可享有免費機場接送及延後退房。房價每晚 189 美元起，每年訂房達五十個房晚以上的公司，可享企業優惠價。\n\n如需訂房或索取活動報價，請致電 555-0163 或上我們的網站。","w":[806,903,771,864,907,921,797,939],"qs":[{"q":"[1]","o":["contractual","comprehensive","conducive","considerable"],"a":2,"k":"單字：environment ___ to concentration → conducive to","n":[["(adj.) 合約的","","'contractual to' 語意不通，不是固定搭配"],["(adj.) 全面的","","comprehensive 不搭配 to concentration"],["(adj.) 有助於…的","be conducive to + N","environment conducive to concentration 有助專注"],["(adj.) 相當大的","","considerable 不搭配 to，也不合語意"]]},{"q":"[2]","o":["has equipped","is equipped","equipping","equips"],"a":1,"k":"時態／語態：each (meeting room) 被配備，後接 with → 被動","n":[["(完成式) 已配備","","主動語態缺受詞，房間不是配備者"],["(被動) 配備有","be equipped with + N","each 是被配備的對象；單數主詞 + is"],["(V-ing) 配備","","缺助動詞，不能單獨當述語"],["(現在式) 配備","","主動語態缺受詞，each 是被配備的一方"]]},{"q":"[3]","o":["entitled","entitlement","entitling","entitle"],"a":0,"k":"詞性：are ___ to complimentary transfers → 過去分詞 entitled","n":[["(p.p.) 有權享有","be entitled to + N","文中 'entitled to complimentary airport transfers'"],["(n.) 權利","","be 後可接名詞，但「房客＝權利」語意不通"],["(V-ing) 賦予權利","","are entitling 是主動進行式，缺受詞且語意不通"],["(v.) 賦予權利","","are 後不能接動詞原形"]]}]},
{"id":"r990-27","lv":990,"p":6,"k":"email","ti":"Update on your delayed order","tx":"To: Samuel Greene, Greene's Garden Center\nFrom: Lucy Hartmann, Customer Accounts, Tolland Tools\nSubject: Update on your delayed order\n\nDear Mr. Greene,\n\nI am writing to apologize for the delay in delivering your order of 200 pruning sets, which was due to reach you on April 10.\n\nAn unprecedented surge in spring orders, in conjunction with an equipment failure at our steel supplier's plant, has left us with a [1] ------- of more than 3,000 unfilled orders. Production returned to full capacity on Monday, and your order [2] ------- priority status. We now expect to dispatch the consignment by April 24. To expedite delivery, it will travel by air freight rather than by road, and we will bear the additional cost.\n\n[3] -------, we recognize that the delay may already have affected your own sales. We would therefore like to offer you a 10 percent reduction on this invoice.\n\nIf this arrangement is not acceptable, you may cancel the order without incurring any charge. Please let me know by Friday how you wish to proceed.\n\nWith apologies once again,\nLucy Hartmann","zh":"收件人：Samuel Greene，Greene's Garden Center\n寄件人：Lucy Hartmann，Tolland Tools 客戶帳務部\n主旨：您延遲訂單的最新進度\n\nGreene 先生您好：\n\n您訂購的 200 組修枝工具原本應於 4 月 10 日送達，卻延遲交貨，我特此來信致歉。\n\n春季訂單出現空前的激增，加上我們鋼材供應商的工廠設備故障，導致我們積壓了三千多筆尚未出貨的訂單。生產線已在星期一恢復全面運轉，您的訂單也已列為優先處理。我們目前預計在 4 月 24 日前發貨。為了加快送達速度，這批貨將改用空運而非陸運，額外的費用由我們負擔。\n\n儘管如此，我們明白這次延誤可能已經影響到您店裡的銷售。因此，我們願意為這張發票提供九折優惠。\n\n如果您無法接受這樣的安排，您可以取消訂單，不會產生任何費用。請在星期五前告訴我您希望如何處理。\n\n再次向您致歉。\nLucy Hartmann","w":[905,992,767,804,991,832,932,954],"qs":[{"q":"[1]","o":["boardroom","blueprint","backlog","benchmark"],"a":2,"k":"單字：a ___ of more than 3,000 unfilled orders → 積壓訂單","n":[["(n.) 會議室","","語意不通，不能是 unfilled orders 的集合"],["(n.) 藍圖","","語意不通，與 unfilled orders 無關"],["(n.) 積壓的工作","a backlog of + N","'a backlog of ... unfilled orders' 積壓的訂單"],["(n.) 基準","","benchmark 指衡量標準，不是未出貨的量"]]},{"q":"[2]","o":["gave","has been given","has given","is giving"],"a":1,"k":"時態／語態：order 被賦予優先，後面仍接 priority status → 被動","n":[["(過去式) 給予","","主動語態，訂單不會自己給予地位"],["(現在完成被動) 被賦予","has been given + N","order 是被賦予者；Production returned Monday 後的現況"],["(現在完成) 給予","","主動語態，order 不是給予者"],["(進行式) 正在給予","","主動語態，order 不是給予者"]]},{"q":"[3]","o":["For example","Consequently","In other words","Nevertheless"],"a":3,"k":"連接詞：前句已補救（空運、吸收運費）→ 仍承認影響 → 讓步 Nevertheless","n":[["(adv.) 例如","","後句不是前句的例子"],["(adv.) 因此","","後句不是前面補救措施造成的結果"],["(adv.) 換句話說","","後句不是重述前句，而是新的歉意內容"],["(adv.) 儘管如此","Nevertheless, + 句子","已補救，但 'may already have affected' 仍有影響"]]}]},
{"id":"r990-28","lv":990,"p":6,"k":"announcement","ti":"Riverside Charity Run set for May 9","tx":"Riverside Charity Run Set for May 9\n\nHollis & Byrne Insurance is proud to sponsor the twelfth annual Riverside Charity Run, which will take place on Saturday, May 9. The run has become a prominent event on the city's calendar, [1] ------- more than 2,000 participants last year.\n\nAll [2] ------- from registration fees will go to the Riverside Literacy Project, an outreach program that provides free reading classes for adults.\n\nEmployees who wish to take part may register through the staff portal until April 24. The company will subsidize the $30 entry fee in full, and participants are entitled to leave work two hours early on the Friday before the race.\n\nVolunteers are also needed to hand out water along the route and to direct runners at the finish line. [3] ------- A short briefing will be given at 7:00 A.M. on the day of the race.\n\nThe renowned marathon runner Carla Voss, who has endorsed the run since its first year, will present the medals. For further details, contact Peter Aldana in Human Resources at extension 2215.","zh":"Riverside 慈善路跑 5 月 9 日開跑\n\nHollis & Byrne Insurance 很榮幸贊助第十二屆年度 Riverside 慈善路跑，活動將於 5 月 9 日星期六舉行。這項路跑已成為本市年度行事曆上的重要活動，去年吸引了超過 2,000 人參加。\n\n報名費的所有收益將捐給 Riverside Literacy Project，這是一項為成人提供免費閱讀課程的外展計畫。\n\n想參加的同仁可在 4 月 24 日前透過員工入口網站報名。公司將全額補助 30 美元的報名費，參加者並可在賽前的星期五提早兩小時下班。\n\n我們也需要志工在路線沿途發水，以及在終點線引導跑者。不需要任何相關經驗。比賽當天上午 7:00 會有簡短的行前說明。\n\n知名馬拉松選手 Carla Voss 從第一屆起就支持這項路跑，她將擔任頒獎人。詳情請洽人力資源部 Peter Aldana，分機 2215。","w":[878,813,848,972,939,869,964],"qs":[{"q":"[1]","o":["attracting","attracted","attraction","attracts"],"a":0,"k":"詞性：主句已有 has become → 逗號後用分詞構句 attracting","n":[["(V-ing) 吸引","分詞構句 V-ing + O","接在逗號後的分詞構句，後接受詞 'more than 2,000'"],["(p.p.) 吸引了","","逗號後多一個述語，缺連接詞；過去分詞也不接受詞"],["(n.) 吸引力","","名詞後面不能再接 'more than 2,000 participants'"],["(現在式) 吸引","","時態與 last year 衝突，也會造成逗號連接兩句"]]},{"q":"[2]","o":["minutes","premises","proceeds","credentials"],"a":2,"k":"單字：All ___ from registration fees → 報名費的收益","n":[["(n.) 分鐘、會議紀錄","","'All minutes from registration fees' 語意不通"],["(n.) 場所","","premises 指場地，不能來自報名費"],["(n.) 收益","proceeds from + N","'proceeds from registration fees' 報名費的收益"],["(n.) 資格證明","","credentials 指資歷，不是報名費的來源"]]},{"q":"[3]","o":["No previous experience is necessary.","Registration closed at the end of March.","The race has been postponed until next year.","Runners must bring their own water."],"a":0,"k":"句子插入：前句徵志工、後句 briefing → 補充說明免經驗","n":[["不需要任何先前經驗","","接在徵志工後，並引出簡短說明 'short briefing'"],["三月底已截止報名","","與員工 'until April 24' 報名的日期矛盾"],["比賽已延到明年","","與 'May 9' 和比賽當日 briefing 矛盾"],["跑者必須自備飲水","","與志工在沿途 'hand out water' 矛盾"]]}]},
{"id":"r990-29","lv":990,"p":6,"k":"memo","ti":"Spending measures for the second half of the year","tx":"MEMO\n\nTo: All department managers\nFrom: Linda Osei, Chief Financial Officer\nSubject: Spending measures for the second half of the year\n\nAs you know, first-half revenue fell 8 percent short of our forecast, leaving the company with a projected deficit of $2.4 million for the fiscal year. It is therefore imperative that we [1] ------- spending in every department without delay.\n\nThe following measures apply from July 1. All non-essential travel is suspended, and any expenditure above $2,000 must be authorized by my office. Hiring is frozen except for positions that generate revenue directly. In addition, the funds set aside for the office refurbishment [2] ------- to the product launch in September.\n\nI want to reiterate that these steps are not a first move toward downsizing. [3] -------, they are intended to protect jobs by restoring a surplus before the end of the year.\n\nManagers will be held accountable for staying within their revised budgets, which will be distributed on Friday. I appreciate your cooperation during this difficult period.","zh":"備忘錄\n\n收件人：各部門經理\n寄件人：財務長 Linda Osei\n主旨：下半年的支出管控措施\n\n如各位所知，上半年營收比預測少了 8%，使公司本會計年度預估將出現 240 萬美元的虧損。因此，我們務必立刻削減每個部門的支出。\n\n以下措施自 7 月 1 日起實施。所有非必要的出差一律暫停，凡是超過 2,000 美元的支出都必須經過我的辦公室核准。除了能直接創造營收的職位之外，人員招募全面凍結。此外，原本預留給辦公室整修的經費，將重新分配給九月的產品上市活動。\n\n我要重申，這些措施並不是裁員的前兆。相反地，這些措施是為了在年底前恢復盈餘，藉此保住大家的工作。\n\n各部門經理必須負責把支出控制在修訂後的預算之內，新預算將於星期五發給各位。感謝各位在這段艱難時期的配合。","w":[769,892,881,961,821,953,983,793],"qs":[{"q":"[1]","o":["escalate","accrue","deteriorate","curtail"],"a":3,"k":"單字：imperative that we ___ spending → 削減支出","n":[["(v.) 升高","It is imperative that + S + 原形","與要降低赤字、削減支出的語意相反"],["(v.) 累積","","accrue 指利息等累積，不搭配 spending"],["(v.) 惡化","","deteriorate 是不及物動詞，不能接 spending"],["(v.) 削減","curtail spending","為了處理赤字，'curtail spending' 削減支出"]]},{"q":"[2]","o":["will reallocate","will be reallocated","reallocating","have reallocated"],"a":1,"k":"時態／語態：funds 被重新分配 to product launch → 未來被動","n":[["(未來式) 將重新分配","","主動語態缺受詞，funds 是被分配的對象"],["(未來被動) 將被重新分配","will be + p.p. + to","funds 是被分配的對象；措施自 July 1 起"],["(V-ing) 重新分配","","缺助動詞，不能單獨當述語"],["(現在完成) 已重新分配","","主動語態缺受詞，措施是 'apply from July 1' 的未來"]]},{"q":"[3]","o":["For instance","On the contrary","In addition","As a result"],"a":1,"k":"連接詞：前句 not ... downsizing，後句說反面 → On the contrary","n":[["(adv.) 例如","","後句不是舉例"],["(adv.) 相反地","On the contrary, + 句子","前句否定裁員，後句 'protect jobs' 說相反意思"],["(adv.) 此外","","表新增並列，這裡是否定後的反面說法"],["(adv.) 因此","","後句不是前句造成的結果"]]}]},
{"id":"r990-30","lv":990,"p":6,"k":"notice","ti":"Scheduled network maintenance this weekend","tx":"NOTICE FROM THE IT DEPARTMENT\n\nScheduled Network Maintenance This Weekend\n\nOver the past month, many of you have reported intermittent connectivity problems, particularly on the fourth floor. Our technicians have inspected every workstation and found no defects. The underlying cause is aging network equipment [1] ------- a fault in any individual computer.\n\nTo resolve the problem, new switches will be [2] ------- throughout the building this weekend. As a result, the network, including e-mail and the shared drives, will be unavailable from 8:00 P.M. on Friday until 6:00 A.M. on Monday. Staff who need to work during this period should copy the necessary files to their laptops before leaving on Friday.\n\nWe expect that all of the work [3] ------- by the time the office reopens on Monday. As a preemptive measure, however, two technicians will be onsite that morning to troubleshoot any remaining problems. If your connection is still unstable after the upgrade, please call the help desk at extension 3000 instead of restarting the equipment yourself.\n\nWe apologize for the disruption and thank you for your patience.","zh":"資訊部公告\n\n本週末網路例行維護\n\n過去一個月，許多同仁反映網路連線時斷時續，四樓的情況尤其明顯。我們的技術人員已經檢查過每一台工作站，並未發現任何故障。根本原因在於網路設備老舊，而不是哪一台電腦出了問題。\n\n為了解決這個問題，本週末將在整棟大樓部署新的交換器。因此，包括電子郵件和共用磁碟在內的網路，將從星期五晚上 8:00 起停止服務，到星期一早上 6:00 恢復。這段期間需要工作的同仁，請在星期五下班前把需要的檔案複製到筆記型電腦裡。\n\n我們預計所有工程會在星期一辦公室恢復上班前完成。不過，為了預防萬一，當天早上會有兩名技術人員在現場，協助排除任何殘留的問題。如果升級後您的連線仍然不穩定，請撥分機 3000 聯絡服務台，不要自行重新啟動設備。\n\n造成不便，敬請見諒，並感謝您的耐心配合。","w":[904,771,757,890,971,902,943],"qs":[{"q":"[1]","o":["in case of","as well as","rather than","because of"],"a":2,"k":"連接詞：cause is old equipment ___ a fault in any computer → 而非","n":[["(prep.) 以防","","in case of 表預防，語意不通"],["(prep.) 以及","","as well as 表並列，但前句說 'found no defects'"],["(prep.) 而不是","A rather than B","'old equipment rather than a fault' 是設備而非電腦"],["(prep.) 因為","","because of a fault 把原因說反了，與 'no defects' 矛盾"]]},{"q":"[2]","o":["depreciated","deployed","disclosed","deterred"],"a":1,"k":"單字：new switches will be ___ throughout the building → 部署","n":[["(v.) 折舊","","語意不通，新交換器不會被折舊"],["(v.) 部署、安裝","deploy + 設備","文中 'switches will be deployed' 部署新設備"],["(v.) 揭露","","disclose 指公開資訊，不是設備"],["(v.) 阻止","","語意不通：deter 是「阻止（人）做某事」，設備不會被阻止"]]},{"q":"[3]","o":["was completing","will have been completed","has completed","had been completed"],"a":1,"k":"時態／語態：by the time 子句用現在式 → 主句未來完成被動","n":[["(過去進行) 當時正在完成","","主動且時間是過去，與 'We expect' 的未來不合"],["(未來完成被動) 屆時已完成","will have been + p.p.","'by the time the office reopens' 的未來完成"],["(現在完成) 已完成","","主動語態缺受詞，work 是被完成的對象"],["(過去完成被動) 早已完成","","過去完成與 'We expect' 的未來不合"]]}]}];
